  ui_story_5037_50370101_69_dialog_content = "...",
  ui_story_5037_50370101_70_dialog_content = "Anyway, please join my show, PlayerName!",
  ui_story_5037_50370101_71_dialog_content = "I admit to knowing nothing about idols, so I definitely am the complete noob you're looking for.",
