  ui_story_5037_50370101_73_dialog_content = "You've got notoriety on Astra, PlayerName.",
  ui_story_5037_50370101_74_dialog_content = "You must be looking to take advantage of PlayerName's clout and popularity, right, Lady Sheol?",
