  ui_story_5037_50370101_88_dialog_content = "On second thought, I can't think of a reason why not, either...",
  ui_story_5037_50370101_89_dialog_content = "Trust me, darling, it's a win-win situation for you.",
  ui_story_5037_50370101_90_dialog_content = "If you've made up your mind, just sign the dotted line.",
