  ui_story_5037_50370101_95_option_content = "sign the dotted line!",
  ui_story_5037_50370101_96_dialog_content = "Perfect, my dear!",
  ui_story_5037_50370101_97_dialog_content = "Since it's signed, let's get started!",
  ui_story_5037_50370101_98_dialog_content = "From now on, you must be completely dedicated to the show.",
  ui_story_5037_50370101_99_dialog_content = "You need to figure out how to package your idol, schedule practice sessions, negotiate endorsement deals, and maintain their popularity with fans...",
  ui_story_5037_50370101_100_dialog_content = "Until the idol is ready for upcoming concerts and evaluations.",
  ui_story_5037_50370101_101_dialog_content = "Hooooold on a second, a producer has to do all that?",
  ui_story_5037_50370101_102_dialog_content = "I don't even remember anything you just said! Is it too late for me to back out?",
  ui_story_5037_50370101_103_dialog_content = "You can breach the contract, as long as you pay me a hundred times in compensation.",
  ui_story_5037_50370101_104_dialog_content = "If you can afford it, then I don't mind.",
  ui_story_5037_50370101_105_dialog_content = "What?",
  ui_story_5037_50370101_106_dialog_content = "Oh, speaking of that, I have another surprise I forgot to tell you.",
  ui_story_5037_50370101_107_dialog_content = "You get a bonus if you can beat your opponent!",
  ui_story_5037_50370101_108_dialog_content = "Opponent? Why am I only hearing about this now?",
