  ui_story_5037_50370101_110_dialog_content = "What's a reality show without a little conflict?",
  ui_story_5037_50370101_111_dialog_content = "Don't worry. You're very familiar with your opponent.",
  ui_story_5037_50370101_112_dialog_content = "As for who it is... You'll see when it's time.",
  ui_story_5037_50370101_113_dialog_content = "I-I'm getting a headache...",
  ui_story_5037_50370101_114_dialog_content = "Relax, PlayerName. Let me and Vice know if we can help you with anything.",
  ui_story_5037_50370101_115_dialog_content = "I can consult my former music and dance instructors for you.",
  ui_story_5037_50370101_116_dialog_content = "Yeah, and don't forget I'm pretty good at planning!",
  ui_story_5037_50370101_117_dialog_content = "If you're interested, Lady Carleen and Miss Vice, the two of you can join PlayerName's squad.",
  ui_story_5037_50370101_118_dialog_content = "You can strategize for him and monitor his development.",
  ui_story_5037_50370101_119_dialog_content = "Of course, you'll be paid properly for it.",
