  ui_story_5037_50370101_121_dialog_content = "We promise to make PlayerName the best producer there is!",
  ui_story_5037_50370101_122_dialog_content = "The two of you seem so confident all of a sudden!",
  ui_story_5037_50370101_123_dialog_content = "Now then, come with me, PlayerName.",
  ui_story_5037_50370101_124_dialog_content = "Where are we going?",
  ui_story_5037_50370101_125_dialog_content = "We're going to...",
  ui_story_5037_50370101_126_dialog_content = "Hello, Producer. Welcome to the biggest idol maker in Umbraton—the <color=#793f76>Starlit Agency</color>!",
  ui_story_5037_50370101_127_dialog_content = "This is where you'll discover potential idols and guide them on their journey to stardom!",
