  ui_story_5037_50370101_129_dialog_content = "What do you prefer, Producer PlayerName?",
  ui_story_5037_50370101_130_dialog_content = "What? Uh...",
  ui_story_5037_50370101_131_dialog_content = "Well...",
  ui_story_5037_50370101_132_dialog_content = "Cut!",
  ui_story_5037_50370101_133_dialog_content = "Can you make yourself appear more comfortable in front of the camera, PlayerName?",
  ui_story_5037_50370101_134_dialog_content = "This is a reality show. You don't have to keep looking at the camera.",
  ui_story_5037_50370101_135_dialog_content = "Sorry! I didn't think we'd be filming as soon as I walked through the door.",
  ui_story_5037_50370101_136_dialog_content = "Whether I can make a name in the reality show biz depends on this!",
  ui_story_5037_50370101_137_dialog_content = "So starting now, please ignore my presence and the camera, PlayerName.",
  ui_story_5037_50370101_138_dialog_content = "React how you'd normally react and say what you'd normally say, alright?",
  ui_story_5037_50370101_139_dialog_content = "Okay...",
  ui_story_5037_50370101_140_dialog_content = "Take two!",
  ui_story_5037_50370101_141_dialog_content = "I hope the trip was pleasant for you, Producer PlayerName.",
