  ui_story_5037_50370101_144_dialog_content = "Uh, Goldie...",
  ui_story_5037_50370101_145_dialog_content = "I just realized something very serious!",
  ui_story_5037_50370101_146_dialog_content = "Sheol told me I would see my opponent here.",
  ui_story_5037_50370101_147_dialog_content = "That wouldn't be you, would it?",
