  ui_story_5037_50370101_154_dialog_content = "No high-calorie junk food during the training period!",
  ui_story_5037_50370101_155_dialog_content = "You keep practicing. I'll go find something filling and low-calorie for you.",
  ui_story_5037_50370101_156_dialog_content = "... Thank you so much.",
  ui_story_5037_50370101_157_dialog_content = "It looks like our opponents have got a head start already.",
  ui_story_5037_50370101_158_dialog_content = "Hmm, PlayerName? So you're the opponent Lady Sheol mentioned!",
  ui_story_5037_50370101_159_dialog_content = "Hehe, I won't hold back, even if it's you.",
  ui_story_5037_50370101_160_dialog_content = "I'll lead my master to victory and get the prize money!",
  ui_story_5037_50370101_161_dialog_content = "By the way, don't peek in on his sessions when I'm not around!",
  ui_story_5037_50370101_162_dialog_content = "Those two are our competition.",
  ui_story_5037_50370101_163_dialog_content = "Aren't they supposed to be too busy studying wondrous beasts to be interested in a reality show?",
  ui_story_5037_50370101_164_dialog_content = "Hey, wait a minute... Did you say \"our competition\"?",
  ui_story_5037_50370101_165_dialog_content = "Are you the idol I'm gonna be training, Goldie?",
  ui_story_5037_50370101_166_dialog_content = "Didn't Lady Sheol tell you?",
