  ui_story_5037_50370101_169_dialog_content = "Hee, it's true I'm sorta famous, but that's in the past.",
  ui_story_5037_50370101_170_dialog_content = "I just joined the Starlit Agency, and now need to prove myself.",
  ui_story_5037_50370101_171_dialog_content = "So I'll need a lot of help from you, PlayerName!",
