  ui_story_5037_50370101_173_dialog_content = "I didn't expect Lady Sheol to set us up with competition.",
  ui_story_5037_50370101_174_dialog_content = "This is my first time in such a situation too, so I'm a bit nervous, heheh.",
  ui_story_5037_50370101_175_dialog_content = "If I don't do well, won't that impact your career in the future?",
  ui_story_5037_50370101_176_dialog_content = "Boy, I'm suddenly feeling super stressed out.",
  ui_story_5037_50370101_177_dialog_content = "Come on, Producer PlayerName, that stuff's too far down the line.",
  ui_story_5037_50370101_178_dialog_content = "What's important right now is the challenge that lays before us.",
  ui_story_5037_50370101_179_dialog_content = "That way, even if we don't end up with exactly what we want, there's no regret!",
  ui_story_5037_50370101_180_dialog_content = "You're right!",
  ui_story_5037_50370101_181_dialog_content = "But I think it's the producer's job to encourage the idol, isn't it?",
  ui_story_5037_50370101_182_dialog_content = "How come you're encouraging me instead?",
