  ui_story_5037_50370101_187_dialog_content = "Ah... Okay, for both our careers!",
  ui_story_5037_50370101_188_dialog_content = "But I still don't get what we're supposed to do. Or more specifically, what I'm supposed to do.",
  ui_story_5037_50370101_189_dialog_content = "Our mission is to hold three concerts within a certain period of time.",
  ui_story_5037_50370101_190_dialog_content = "And there's so much for you to do, PlayerName!",
  ui_story_5037_50370101_191_dialog_content = "Such as scheduling timely practice sessions, picking out promotional activities, producing songs for me, and so on.",
  ui_story_5037_50370101_192_dialog_content = "All of that sounds completely out of my realm...",
  ui_story_5037_50370101_193_dialog_content = "Hands-on experience is the best experience, PlayerName!",
  ui_story_5037_50370101_194_dialog_content = "Who was your former producer, Goldie? Maybe I can learn something from them.",
  ui_story_5037_50370101_195_dialog_content = "Hee, I was my own producer!",
  ui_story_5037_50370101_196_dialog_content = "What? Didn't that tire you out?",
  ui_story_5037_50370101_197_dialog_content = "It was exhausting, but that's all in the past.",
  ui_story_5037_50370101_198_dialog_content = "Now I'm an idol with my own exclusive producer!",
  ui_story_5037_50370101_199_dialog_content = "Heh...",
  ui_story_5037_50370101_200_dialog_content = "Why don't I show you what a producer is supposed to do right now, PlayerName?",
  ui_story_5037_50370101_201_dialog_content = "Sure!",
  ui_story_5037_50370201_1_dialog_content = "The concert is starting soon...",
  ui_story_5037_50370201_2_dialog_content = "but I forgot to leave the cough drops for Goldie backstage!",
  ui_story_5037_50370201_3_dialog_content = "<color=#828282>*Rummage*</color>",
  ui_story_5037_50370201_4_dialog_content = "I can't believe I left them with the reference books.",
  ui_story_5037_50370201_5_dialog_content = "At least I found them, though. I'd better get them to Goldie now!",
  ui_story_5037_50370201_6_dialog_content = "Hurry up, Master!",
  ui_story_5037_50370201_7_dialog_content = "That sounds like Fia.",
  ui_story_5037_50370201_8_dialog_content = "Aren't they backstage yet?",
  ui_story_5037_50370201_9_dialog_content = "What are you doing sleeping here? The concert's about to start!",
  ui_story_5037_50370201_10_dialog_content = "It took me so long to find you!",
  ui_story_5037_50370201_11_dialog_content = "How would I have the energy to perform without my beauty sleep?",
  ui_story_5037_50370201_12_dialog_content = "Give me a few more minutes, and I'll head on over.",
  ui_story_5037_50370201_13_dialog_content = "<size=45>Master—!</size>",
  ui_story_5037_50370201_14_dialog_content = "How are you so relaxed at a time like this?!",
  ui_story_5037_50370201_15_dialog_content = "Goldie and PlayerName already rehearsed a whole bunch.",
  ui_story_5037_50370201_16_dialog_content = "Well if they've already done so, I don't think we need to.",
  ui_story_5037_50370201_17_dialog_content = "It's a waste of time for everyone to do the same thing.",
  ui_story_5037_50370201_18_dialog_content = "*Inhales* Are you spewing nonsense again?",
  ui_story_5037_50370201_19_dialog_content = "It's one thing when it's during practice, but now we have to get serious!",
  ui_story_5037_50370201_20_dialog_content = "We won't get the bonus if we lose to PlayerName!",
  ui_story_5037_50370201_21_dialog_content = "I know! Let's get Shira to take my place!",
  ui_story_5037_50370201_22_dialog_content = "N-O, NO!",
  ui_story_5037_50370201_23_dialog_content = "I don't get it... Why do you insist on making life difficult for your old master?",
  ui_story_5037_50370201_24_dialog_content = "Hmm, I wonder who bragged about almost becoming an idol.",
  ui_story_5037_50370201_25_dialog_content = "When did I brag, Fia? It was a fact!",
  ui_story_5037_50370201_26_dialog_content = "Well, there you go.",
  ui_story_5037_50370201_27_dialog_content = "You have the chance to be an idol today! Shouldn't you be glad?",
  ui_story_5037_50370201_28_dialog_content = "Just in name only is fine. I don't want to be an idol for real.",
  ui_story_5037_50370201_29_dialog_content = "If I did, it would be an idol trainer for wondrous beasts!",
  ui_story_5037_50370201_30_dialog_content = "All the more reason for you to make some money so you can care for the creatures you have!",
  ui_story_5037_50370201_31_dialog_content = "The pay for being on the show can only sustain your own living needs.",
  ui_story_5037_50370201_32_dialog_content = "You need to beat PlayerName so we have the means to improve the wondrous beasts' lives!",
  ui_story_5037_50370201_33_dialog_content = "But I worked hard and took side jobs...",
  ui_story_5037_50370201_34_dialog_content = "The pay combined from those jobs don't even match this gig.",
  ui_story_5037_50370201_35_dialog_content = "The poor animals are going to starve to death if you stick to those side jobs.",
  ui_story_5037_50370201_36_dialog_content = "I have to keep you on a leash this time and win that bonus!",
  ui_story_5037_50370201_37_dialog_content = "(I didn't quite hear what they said...)",
  ui_story_5037_50370201_38_dialog_content = "(But Fia sounded determined and impressive. In comparison, I feel...)",
  ui_story_5037_50370201_39_dialog_content = "Wow, this cough drop is really minty and cool!",
  ui_story_5037_50370201_40_dialog_content = "You're so thoughtful to think of this, Producer PlayerName!",
  ui_story_5037_50370201_41_dialog_content = "...",
  ui_story_5037_50370201_42_dialog_content = "What's on your mind?",
  ui_story_5037_50370201_43_dialog_content = "Nothing. I'm just happy you like it.",
  ui_story_5037_50370201_44_dialog_content = "In the future I'll prepare more soothing, tasty cough drop flavors to soothe your throat!",
  ui_story_5037_50370201_45_dialog_content = "Hey, looks like you're ready to go.",
  ui_story_5037_50370201_46_dialog_content = "Yeah! I'll make sure you love the result!",
  ui_story_5037_50370201_47_dialog_content = "Love your confidence, darling. I look forward to it.",
  ui_story_5037_50370201_48_dialog_content = "Uh, Lady Sheol?",
  ui_story_5037_50370201_49_dialog_content = "Yes, PlayerName?",
  ui_story_5037_50370201_50_dialog_content = "Will Vic be performing with Goldie on stage?",
  ui_story_5037_50370201_51_dialog_content = "What are you worried about?",
  ui_story_5037_50370201_52_dialog_content = "Oh, I-I was just checking.",
  ui_story_5037_50370201_53_dialog_content = "Just proceed with whatever you've planned.",
  ui_story_5037_50370201_54_dialog_content = "Vic's concert isn't here. It's on a neighboring stage.",
  ui_story_5037_50370201_55_dialog_content = "Goldie and Vic will be holding their shows simultaneously.",
  ui_story_5037_50370201_56_dialog_content = "Another stage? No wonder I didn't see Vic backstage.",
  ui_story_5037_50370201_57_dialog_content = "I see. So you anticipated this way back when you built the concert hall, huh?",
  ui_story_5037_50370201_58_dialog_content = "That's why you set up two side-by-side stages.",
  ui_story_5037_50370201_59_dialog_content = "Two side-by-side stages?",
  ui_story_5037_50370201_60_dialog_content = "You should be surprised, darling. This is one of my best masterpieces.",
  ui_story_5037_50370201_61_dialog_content = "Only one aisle separates the two stages.",
  ui_story_5037_50370201_62_dialog_content = "After the shows start, the audience can follow their preferences and move freely between the stages.",
  ui_story_5037_50370201_63_dialog_content = "In the end, whichever stage manages to gain a larger crowd will be declared the winner.",
  ui_story_5037_50370201_64_dialog_content = "The experience will be unprecedented, and garner publicity for the reality show too.",
  ui_story_5037_50370201_65_dialog_content = "Make sure you edit that last line out of the broadcast, Lilica.",
  ui_story_5037_50370201_66_dialog_content = "No problem!",
  ui_story_5037_50370201_67_dialog_content = "(I got so used to Lilica and her camera that I forgot she was with us!)",
  ui_story_5037_50370201_68_dialog_content = "Well then, good luck, darling!",
  ui_story_5037_50370201_69_dialog_content = "Why weren't we told about this?",
  ui_story_5037_50370201_70_dialog_content = "Now I need to rework the concert program to make it more alluring!",
  ui_story_5037_50370201_71_dialog_content = "Ah! I haven't checked the sound and lighting yet...",
  ui_story_5037_50370201_72_dialog_content = "You did check, PlayerName.",
  ui_story_5037_50370201_73_dialog_content = "What? I did?",
  ui_story_5037_50370201_74_dialog_content = "What's the matter with my memory...",
  ui_story_5037_50370201_75_dialog_content = "Are you nervous, PlayerName?",
  ui_story_5037_50370201_76_dialog_content = "Relax, we've put enough effort into our preparation!",
  ui_story_5037_50370201_77_dialog_content = "We don't need to think about what will happen.",
  ui_story_5037_50370201_78_dialog_content = "As long as we put on a show like we rehearsed and make the crowd happy, we can count that a victory!",
  ui_story_5037_50370201_79_dialog_content = "Yes, yes, you're right, Goldie.",
  ui_story_5037_50370201_80_dialog_content = "We just need to show them what we've been practicing!",
  ui_story_5037_50370201_81_dialog_content = "<color=#793f76>Five minutes</color> to the show!",
  ui_story_5037_50370201_82_dialog_content = "Ahhhh!",
  ui_story_5037_50370201_83_dialog_content = "No, no, no! It feels like I still have a whole bunch of things to do!",
  ui_story_5037_50370201_84_dialog_content = "Relax. All we have to do now is wait for the show to start!",
  ui_story_5037_50370201_85_dialog_content = "You sure?",
  ui_story_5037_50370201_86_dialog_content = "Sorry. I hope my anxiety isn't affecting you.",
  ui_story_5037_50370201_87_dialog_content = "I'm really not a competent producer.",
  ui_story_5037_50370201_88_dialog_content = "That's not true!",
  ui_story_5037_50370201_89_dialog_content = "This is only your first time!",
  ui_story_5037_50370201_90_dialog_content = "You're showing a thousand times more composure now than when I got on a stage for the first time.",
  ui_story_5037_50370201_91_dialog_content = "Your first time on a stage?",
  ui_story_5037_50370201_92_dialog_content = "Yeah. No one wanted to give me a chance back then.",
  ui_story_5037_50370201_93_dialog_content = "I had to fight for an opportunity to be on stage.",
  ui_story_5037_50370201_94_dialog_content = "Next, Goldie will be bringing us a happy song!",
  ui_story_5037_50370201_95_dialog_content = "H...Hi, everyone!",
  ui_story_5037_50370201_96_dialog_content = "Who's that?",
  ui_story_5037_50370201_97_dialog_content = "Don't know, don't care.",
  ui_story_5037_50370201_98_dialog_content = "Never mind. It's a good time to run to the restroom.",
  ui_story_5037_50370201_99_dialog_content = "Sigh...",
  ui_story_5037_50370201_100_dialog_content = "(How come so many of them just left?)",
  ui_story_5037_50370201_101_dialog_content = "(Everyone else is just staring.)",
  ui_story_5037_50370201_102_dialog_content = "(Speaking of which, why am I here?)",
  ui_story_5037_50370201_103_dialog_content = "(What am I doing here...?)",
  ui_story_5037_50370201_104_dialog_content = "Are you going to do something or just stand there?",
  ui_story_5037_50370201_105_dialog_content = "Get off the stage if you can't sing!",
  ui_story_5037_50370201_106_dialog_content = "Uh, I...",
  ui_story_5037_50370201_107_dialog_content = "They booed you off the stage?",
  ui_story_5037_50370201_108_dialog_content = "Sorry, I didn't mean to remind you of such a bad memory.",
  ui_story_5037_50370201_109_dialog_content = "Oh, no worries. It doesn't bother me anymore.",
  ui_story_5037_50370201_110_dialog_content = "Huh?",
  ui_story_5037_50370201_111_dialog_content = "I told myself back then that the beginning of every journey is difficult.",
  ui_story_5037_50370201_112_dialog_content = "It's okay to make mistakes, just don't make the same mistakes twice!",
  ui_story_5037_50370201_113_dialog_content = "After that, I never got so nervous that I forgot my lyrics again.",
  ui_story_5037_50370201_114_dialog_content = "But if I hadn't gotten over my stage fright the first time and had instead wallowed in my misery...",
  ui_story_5037_50370201_115_dialog_content = "I wouldn't have become who I am today.",
  ui_story_5037_50370201_116_dialog_content = "Very inspiring!",
  ui_story_5037_50370201_117_dialog_content = "Actually, I still get a little nervous even now.",
  ui_story_5037_50370201_118_dialog_content = "But a bit of stress will improve your focus and makes you do better.",
  ui_story_5037_50370201_119_dialog_content = "I can't tell you're nervous at all!",
  ui_story_5037_50370201_120_dialog_content = "Really? It's probably because you're too nervous, so I look relaxed in comparison.",
  ui_story_5037_50370201_121_dialog_content = "But anyway, my point is...",
  ui_story_5037_50370201_122_dialog_content = "Please trust me.",
  ui_story_5037_50370201_123_dialog_content = "I'm a stage-hardened veteran idol, after all.",
  ui_story_5037_50370201_124_dialog_content = "Not to mention I now have an excellent producer who picked out fantastic songs, costumes, and props for me.",
  ui_story_5037_50370201_125_dialog_content = "Oh yeah, and the best cough drops I've ever had too!",
  ui_story_5037_50370201_126_dialog_content = "So I won't let you down!",
  ui_story_5037_50370201_127_dialog_content = "Goldie...",
  ui_story_5037_50370201_128_dialog_content = "Then I shouldn't let you down either!",
  ui_story_5037_50370201_129_dialog_content = "Ten seconds till the concert starts!",
  ui_story_5037_50370201_130_dialog_content = "Ten... nine... eight... seven...",
  ui_story_5037_50370201_131_dialog_content = "Time for me to hit the stage, Producer!",
  ui_story_5037_50370201_132_dialog_content = "Break a leg, Goldie!",
  ui_story_5037_50370201_133_dialog_content = "Thank you!",
  ui_story_5037_50370301_1_dialog_content = "Wherever Goldie goes, the Goldilocks follow!",
  ui_story_5037_50370301_2_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5037_50370301_3_dialog_content = "The crowd's pumped!",
  ui_story_5037_50370301_4_dialog_content = "The show's over, yet they're still shouting Goldie's name.",
  ui_story_5037_50370301_5_dialog_content = "I'm back, PlayerName!",
  ui_story_5037_50370301_6_dialog_content = "Well done, Goldie!",
  ui_story_5037_50370301_7_dialog_content = "Hey, what's wrong? Why do you look like you're about to cry?",
  ui_story_5037_50370301_8_dialog_content = "We did it... We did it!",
  ui_story_5037_50370301_9_dialog_content = "It went incredibly well. Everyone moved to your every note.",
  ui_story_5037_50370301_10_dialog_content = "Yeah, I felt it out there too, it was like I was one with the stage!",
  ui_story_5037_50370301_11_dialog_content = "Your ballads moved so many of them to tears.",
  ui_story_5037_50370301_12_dialog_content = "And the fast songs had everyone hopping to the beat!",
  ui_story_5037_50370301_13_dialog_content = "You put out a flawless performance out there today!",
  ui_story_5037_50370301_14_dialog_content = "All thanks to my great producer, of course.",
  ui_story_5037_50370301_15_dialog_content = "I never realized I could master songs like that before!",
  ui_story_5037_50370301_16_dialog_content = "It was possible only because of the lighting and stage design.",
  ui_story_5037_50370301_17_dialog_content = "Never mind the audience, even I enjoyed the performance.",
  ui_story_5037_50370301_18_dialog_content = "You don't seem like a newbie at all, you know.",
  ui_story_5037_50370301_19_dialog_content = "Instead, you're like a versatile idol producer who's capable of handling anything!",
  ui_story_5037_50370301_20_dialog_content = "Haha, you flatter me... I still have a lot of room for improvement.",
  ui_story_5037_50370301_21_dialog_content = "I almost made a mistake and didn't bring one of the props out in time.",
  ui_story_5037_50370301_22_dialog_content = "It took your experience to avert a disaster.",
  ui_story_5037_50370301_23_dialog_content = "But you won't make the same mistake next time, right?",
  ui_story_5037_50370301_24_dialog_content = "A-Absolutely not!",
  ui_story_5037_50370301_25_dialog_content = "Haha!",
  ui_story_5037_50370301_26_dialog_content = "Oh, Lady Sheol said she'll announce the results at the agency.",
  ui_story_5037_50370301_27_dialog_content = "Okay, let's go.",
  ui_story_5037_50370301_28_dialog_content = "What's the matter with you, Master? You didn't go all out on the stage!",
  ui_story_5037_50370301_29_dialog_content = "But surprisingly, they loved seeing you be your usual lazy self.",
  ui_story_5037_50370301_30_dialog_content = "They thought it was a deliberate part of your act!",
  ui_story_5037_50370301_31_dialog_content = "I guess you do have a knack for being an idol...",
  ui_story_5037_50370301_32_dialog_content = "Didn't I tell you I almost became one?",
  ui_story_5037_50370301_33_dialog_content = "Then why didn't you successfully debut until today?",
  ui_story_5037_50370301_34_dialog_content = "Hmm? I wonder...",
  ui_story_5037_50370301_35_dialog_content = "Because I've been keeping a close eye on your training!",
  ui_story_5037_50370301_36_dialog_content = "Vic and Fia sure are having fun.",
  ui_story_5037_50370301_37_dialog_content = "Looks like their concert was a success as well.",
  ui_story_5037_50370301_38_dialog_content = "...",
  ui_story_5037_50370301_39_dialog_content = "Don't look so stressed! Vic and I are both Starlit Agency's idols.",
  ui_story_5037_50370301_40_dialog_content = "It's fabulous news that we both had a successful debut!",
  ui_story_5037_50370301_41_dialog_content = "Yeah, you're right!",
  ui_story_5037_50370301_42_dialog_content = "I see that everyone's arrived.",
  ui_story_5037_50370301_43_dialog_content = "Good job all around. Now let me cut right to the chase.",
  ui_story_5037_50370301_44_dialog_content = "The result of the concert is as follows:",
  ui_story_5037_50370301_45_dialog_content = "...",
  ui_story_5037_50370301_46_dialog_content = "Go on...",
  ui_story_5037_50370301_47_dialog_content = "A tie!",
  ui_story_5037_50370301_48_dialog_content = "What?",
  ui_story_5037_50370301_49_dialog_content = "Our first-timer stood his own against the seasoned idol, making it a tie.",
  ui_story_5037_50370301_50_dialog_content = "Our variety show sure is full of twists and turns.",
  ui_story_5037_50370301_51_dialog_content = "I shouldn't have to worry about ratings from now on!",
  ui_story_5037_50370301_52_dialog_content = "Allow me to remind you, my darlings.",
  ui_story_5037_50370301_53_dialog_content = "Both idols received equal amounts of support in this concert...",
  ui_story_5037_50370301_54_dialog_content = "but we've still got <color=#793f76>two</color> more concerts to go.",
  ui_story_5037_50370301_55_dialog_content = "It's the <color=#793f76>cumulative fan support</color> you gain after all three concerts that I'm considering.",
  ui_story_5037_50370301_56_dialog_content = "So regardless of how you felt about this performance,",
  ui_story_5037_50370301_57_dialog_content = "be prepared for the next evaluation concert!",
  ui_story_5037_50370301_58_dialog_content = "I must be truly talented to stalemate Miss Goldie!",
  ui_story_5037_50370301_59_dialog_content = "But I don't think my old bones can withstand more practice, so can I go home now—",
  ui_story_5037_50370301_60_dialog_content = "Are you kidding me?! The results prove...",
  ui_story_5037_50370301_61_dialog_content = "that if you'd held nothing back and actually performed up to your potential, we would've beaten Goldie and PlayerName!",
  ui_story_5037_50370301_62_dialog_content = "Now we have to start from scratch again.",
  ui_story_5037_50370301_63_dialog_content = "Don't even think about slacking off next time, Master!",
  ui_story_5037_50370301_64_dialog_content = "Oi, Fia! Where are you going?",
  ui_story_5037_50370301_65_dialog_content = "The rehearsal room to train, duh!",
  ui_story_5037_50370301_66_dialog_content = "Oh for the love of... When do I get to take a break?",
  ui_story_5037_50370301_67_dialog_content = "Kyllo! Drag him over here!",
  ui_story_5037_50370301_68_dialog_content = "Lo!",
  ui_story_5037_50370301_69_dialog_content = "Be gentle! Kyllo...",
  ui_story_5037_50370301_70_dialog_content = "Vic was that impressive?",
  ui_story_5037_50370301_71_dialog_content = "Yeah, I knew he had the potential to be popular the moment I laid eyes on him.",
  ui_story_5037_50370301_72_dialog_content = "Plus Fia's truly been working hard as his producer.",
  ui_story_5037_50370301_73_dialog_content = "I heard she watches Vic practice till midnight every day herself.",
  ui_story_5037_50370301_74_dialog_content = "I actually saw it a few times myself.",
  ui_story_5037_50370301_75_dialog_content = "Whenever Vic slacked off, Fia would tell Kyllo to bite his ankle!",
  ui_story_5037_50370301_76_dialog_content = "Is that creature really that potent of a motivator?",
  ui_story_5037_50370301_77_dialog_content = "Should I find my own Kyllo to bite my ankle?",
  ui_story_5037_50370301_78_dialog_content = "I-I don't think that's necessary.",
  ui_story_5037_50370301_79_dialog_content = "You already work hard without that kind of external push!",
  ui_story_5037_50370301_80_dialog_content = "I'm the one who really needs a Kyllo.",
  ui_story_5037_50370301_81_dialog_content = "A rookie only caught up to a remarkable idol like you because I didn't work hard enough.",
  ui_story_5037_50370301_82_dialog_content = "You don't need to see it that way, PlayerName.",
  ui_story_5037_50370301_83_dialog_content = "Popularity is never an exact science.",
  ui_story_5037_50370301_84_dialog_content = "At least I enjoyed the show today and left behind no regrets. That's enough for me!",
  ui_story_5037_50370301_85_dialog_content = "Thank you...",
  ui_story_5037_50370301_86_dialog_content = "You can console me, but I can't console myself!",
  ui_story_5037_50370301_87_dialog_content = "Eh?",
  ui_story_5037_50370301_88_dialog_content = "I'll keep working hard to grasp the nuances of being a producer",
  ui_story_5037_50370301_89_dialog_content = "so I can plan a better training schedule for you.",
  ui_story_5037_50370301_90_dialog_content = "Then we'll put on an earthshaking concert!",
  ui_story_5037_50370301_91_dialog_content = "PlayerName...",
  ui_story_5037_50370301_92_dialog_content = "Just one won't do. We still have two more shows to go... Plus many more in the future!",
  ui_story_5037_50370301_93_dialog_content = "Right, let me rephrase that!",
  ui_story_5037_50370301_94_dialog_content = "All our concerts will be earthshaking from now on!",
  ui_story_5037_50370301_95_dialog_content = "Yes!",
  ui_story_5037_50370301_96_dialog_content = "I look forward to working with you!",
  ui_story_5037_50370301_97_dialog_content = "Post-concert friends interview...",
  ui_story_5037_50370301_98_dialog_content = "Action!",
  ui_story_5037_50370301_99_dialog_content = "On a scale of one to ten, how would you rate the concert?",
  ui_story_5037_50370301_100_dialog_content = "The max ten, of course!",
  ui_story_5037_50370301_101_dialog_content = "I'd say eight. There's still room for improvement.",
  ui_story_5037_50370301_102_dialog_content = "What can those two possibly achieve together?",
  ui_story_5037_50370301_103_dialog_content = "What? Oh, yeah I didn't watch the concert.",
  ui_story_5037_50370301_104_dialog_content = "The response was very positive, you said?",
  ui_story_5037_50370301_105_dialog_content = "How would you rate the opposing performance?",
  ui_story_5037_50370301_106_dialog_content = "Uh... Probably ten also, since we saw the effort Vic and Fia put in.",
  ui_story_5037_50370301_107_dialog_content = "Another eight. Still room for improvement.",
  ui_story_5037_50370301_108_dialog_content = "Must I answer?",
  ui_story_5037_50370301_109_dialog_content = "How has your friend changed recently?",
  ui_story_5037_50370301_110_dialog_content = "PlayerName is much more disciplined now, and doesn't oversleep anymore.",
  ui_story_5037_50370301_111_dialog_content = "He's a much faster learner than I anticipated, and really adapted to the role of a producer quite quickly.",
  ui_story_5037_50370301_112_dialog_content = "I dunno, they look the same to me.",
  ui_story_5037_50370301_113_dialog_content = "And that's a wrap for the post-concert interviews!",
  ui_story_5037_50370301_114_dialog_content = "What? They've already starting practicing?",
  ui_story_5037_50370301_115_dialog_content = "I have to go film this!",
  ui_story_5037_50370401_1_dialog_content = "Where should this bigger prop go, Producer?",
  ui_story_5037_50370401_2_dialog_content = "Please move it to the center stage, and make sure it's perfectly centered.",
  ui_story_5037_50370401_3_dialog_content = "How's this lighting, Producer?",
  ui_story_5037_50370401_4_dialog_content = "Too bright. Turn it down a bit, please.",
  ui_story_5037_50370401_5_dialog_content = "Mind checking this out, Producer?",
  ui_story_5037_50370401_6_dialog_content = "What about this problem here, Producer?",
  ui_story_5037_50370401_7_dialog_content = "Producer! Producer!",
  ui_story_5037_50370401_8_dialog_content = "One at a time, one at a time...!",
  ui_story_5037_50370401_9_dialog_content = "<color=#828282>Some time later</color>",
  ui_story_5037_50370401_10_dialog_content = "Phew, glad that's over.",
  ui_story_5037_50370401_11_dialog_content = "Good job.",
  ui_story_5037_50370401_12_dialog_content = "You're all set, Goldie?",
  ui_story_5037_50370401_13_dialog_content = "All set!",
  ui_story_5037_50370401_14_dialog_content = "Same old, same old?",
  ui_story_5037_50370401_15_dialog_content = "Same old, same old!",
  ui_story_5037_50370401_16_dialog_content = "Here.",
  ui_story_5037_50370401_17_dialog_content = "Thanks!",
  ui_story_5037_50370401_18_dialog_content = "Wait, what's \"same old, same old\"? Are you speaking in code?",
  ui_story_5037_50370401_19_dialog_content = "What did you just give to Goldie, PlayerName? My camera didn't catch it.",
  ui_story_5037_50370401_20_dialog_content = "Oh, it's a special thing we have.",
  ui_story_5037_50370401_21_dialog_content = "Knowing I like mint cough drops, my producer carries them on his person all the time.",
  ui_story_5037_50370401_22_dialog_content = "He just handed me a piece, that's all.",
  ui_story_5037_50370401_23_dialog_content = "When did you two develop such chemistry?",
  ui_story_5037_50370401_24_dialog_content = "Hmm, over the last few days.",
  ui_story_5037_50370401_25_dialog_content = "We've been working together long enough now that we can tell what the other is thinking just by looking.",
  ui_story_5037_50370401_26_dialog_content = "Unbelievable...",
  ui_story_5037_50370401_27_dialog_content = "Hold on!",
  ui_story_5037_50370401_28_dialog_content = "What am I supposed to film if you guys don't even talk?",
  ui_story_5037_50370401_29_dialog_content = "Do you er, want me to go have a conversation with him right now?",
  ui_story_5037_50370401_30_dialog_content = "That would be too fake.",
  ui_story_5037_50370401_31_dialog_content = "I know!",
  ui_story_5037_50370401_32_dialog_content = "I can interview you like I did with your friends!",
  ui_story_5037_50370401_33_dialog_content = "Ehehe, I'm such a genius!",
  ui_story_5037_50370401_34_dialog_content = "You interviewed my friends? When?",
  ui_story_5037_50370401_35_dialog_content = "You'll find out when the show comes out!",
  ui_story_5037_50370401_36_dialog_content = "Now let's make time for... the exclusive pre-concert interview!",
  ui_story_5037_50370401_37_dialog_content = "Exclusive Team PlayerName evaluation concert interview...",
  ui_story_5037_50370401_38_dialog_content = "Action!",
  ui_story_5037_50370401_39_dialog_content = "What's the difference between an evaluation concert and a debut concert?",
  ui_story_5037_50370401_40_dialog_content = "A debut concert only proves I can sign on as an idol with the Starlit Agency.",
  ui_story_5037_50370401_41_dialog_content = "To me, the debut concert is like the gateway to my dream.",
  ui_story_5037_50370401_42_dialog_content = "But what can I do once I attain my dream?",
  ui_story_5037_50370401_43_dialog_content = "Perform to the best of my abilities in order to prove myself, naturally.",
  ui_story_5037_50370401_44_dialog_content = "The evaluation concert is a test from the agency, aiming to verify how far we've come along in our training.",
  ui_story_5037_50370401_45_dialog_content = "But to us, it's more like a test of our abilities from the Goldilocks.",
  ui_story_5037_50370401_46_dialog_content = "That's right. I want to prove to everyone...",
  ui_story_5037_50370401_47_dialog_content = "that no matter where I am, I'll never forget where I came from!",
  ui_story_5037_50370401_48_dialog_content = "Do you feel any pressure preparing for the concert?",
  ui_story_5037_50370401_49_dialog_content = "None at all!",
  ui_story_5037_50370401_50_dialog_content = "Just kidding! It's normal to feel pressure.",
  ui_story_5037_50370401_51_dialog_content = "But I'm truly thankful that my producer here took a lot of the weight off my shoulders.",
  ui_story_5037_50370401_52_dialog_content = "I was able to focus on training, which made things so much easier for me.",
  ui_story_5037_50370401_53_dialog_content = "As for how far training came along... you'll see on stage later!",
  ui_story_5037_50370401_54_dialog_content = "Do you think producing is hard work?",
  ui_story_5037_50370401_55_dialog_content = "Honestly, in the period right before the debut concert, I did go through a very hard time.",
  ui_story_5037_50370401_56_dialog_content = "I made a ton of mistakes in the prep leading up to the show.",
  ui_story_5037_50370401_57_dialog_content = "But now I've pretty much settled into the job and gotten familiar with all its ins and outs.",
  ui_story_5037_50370401_58_dialog_content = "I'll never make the same mistake twice.",
  ui_story_5037_50370401_59_dialog_content = "Yup, I can testify to that!",
  ui_story_5037_50370401_60_dialog_content = "PlayerName is a very professional producer now.",
  ui_story_5037_50370401_61_dialog_content = "And he's been so busy. There was hardly any time to sleep.",
  ui_story_5037_50370401_62_dialog_content = "Producer PlayerName really worked super hard to prepare for the concert!",
  ui_story_5037_50370401_63_dialog_content = "I was just doing my job.",
  ui_story_5037_50370401_64_dialog_content = "Being able to help you prepare the most lavish stage to give the Goldilocks a performance to remember made it all worthwhile for me.",
  ui_story_5037_50370401_65_dialog_content = "To be honest, it doesn't even feel like work to me!",
  ui_story_5037_50370401_66_dialog_content = "Could you give us a little hint about what you've planned for us?",
  ui_story_5037_50370401_67_dialog_content = "It's a secret.",
  ui_story_5037_50370401_68_dialog_content = "Our program this time is totally new, never-before-seen.",
  ui_story_5037_50370401_69_dialog_content = "Actually, we can divulge the theme of our concert.",
  ui_story_5037_50370401_70_dialog_content = "Oh, right.",
  ui_story_5037_50370401_71_dialog_content = "PlayerName came up with three different themes for the three concerts.",
  ui_story_5037_50370401_72_dialog_content = "The theme for the debut concert was <color=#793f76>New Beginning</color>. I hope the audience caught the meaning behind that.",
  ui_story_5037_50370401_73_dialog_content = "The theme for the upcoming show is <color=#793f76>Budding Flower</color>!",
  ui_story_5037_50370401_74_dialog_content = "For that, I choreographed a whole new routine with the producer's help.",
  ui_story_5037_50370401_75_dialog_content = "You definitely won't be spending money to see an old show!",
  ui_story_5037_50370401_76_dialog_content = "I just handled the logistics. Goldie should get the bulk of the credit.",
  ui_story_5037_50370401_77_dialog_content = "At first, I was going to have her rehash some old songs.",
  ui_story_5037_50370401_78_dialog_content = "But she wrote several original songs just for the concert.",
  ui_story_5037_50370401_79_dialog_content = "That's because I was suddenly inspired during training one day.",
  ui_story_5037_50370401_80_dialog_content = "Since I decided to become an idol, life has been an uphill battle that I always fought on my own.",
  ui_story_5037_50370401_81_dialog_content = "Now, not only do I have Producer PlayerName to help me out...",
  ui_story_5037_50370401_82_dialog_content = "but also, I have an opponent who's reaching for the same goal.",
  ui_story_5037_50370401_83_dialog_content = "No, rather than an opponent, I think Vic is more akin to a comrade on this journey towards stardom.",
  ui_story_5037_50370401_84_dialog_content = "All these novel feelings inspired me to write many new songs.",
  ui_story_5037_50370401_85_dialog_content = "I heard them many times during our rehearsals, but every time I hear them...",
  ui_story_5037_50370401_86_dialog_content = "they still move me to the core.",
  ui_story_5037_50370401_87_dialog_content = "I believe everyone will find our sincere program emotionally fulfilling!",
  ui_story_5037_50370401_88_dialog_content = "I heard the producer passes out fliers every day to help Goldie?",
  ui_story_5037_50370401_89_dialog_content = "Really? Is that true?",
  ui_story_5037_50370401_90_dialog_content = "This is the first time I'm hearing that... How come you never told me, PlayerName?",
  ui_story_5037_50370401_91_dialog_content = "I was just doing my job.",
  ui_story_5037_50370401_92_dialog_content = "I remember now!",
  ui_story_5037_50370401_93_dialog_content = "There were times when you said you were grabbing food or snacks...",
  ui_story_5037_50370401_94_dialog_content = "You were passing out fliers instead?",
  ui_story_5037_50370401_95_dialog_content = "Yeah. Sorry, I didn't want to distract you, Goldie. That's why I didn't tell you.",
  ui_story_5037_50370401_96_dialog_content = "You always say that results aren't important, and that it's experiencing the journey with no regrets that matters...",
  ui_story_5037_50370401_97_dialog_content = "but I still want to help you obtain more support.",
  ui_story_5037_50370401_98_dialog_content = "That's the best way to make sure there are no regrets, I think.",
  ui_story_5037_50370401_99_dialog_content = "PlayerName...",
  ui_story_5037_50370401_100_dialog_content = "Take me with you next time! A street performance would definitely be more eye-catching!",
  ui_story_5037_50370401_101_dialog_content = "Don't forget we're a team!",
  ui_story_5037_50370401_102_dialog_content = "A team... Yes, we're a team!",
  ui_story_5037_50370401_103_dialog_content = "Do you feel confident about the concert?",
  ui_story_5037_50370401_104_dialog_content = "Are you confident in me, PlayerName?",
  ui_story_5037_50370401_105_dialog_content = "I've seen Goldie's rehearsals. They're flawless, virtually impeccable.",
  ui_story_5037_50370401_106_dialog_content = "Today's nothing more than a new venue, so I'm very confident in Goldie!",
  ui_story_5037_50370401_107_dialog_content = "What a coincidence, I'm also very confident in you!",
  ui_story_5037_50370401_108_dialog_content = "Same old, same old?",
  ui_story_5037_50370401_109_dialog_content = "Same old, same old!",
  ui_story_5037_50370401_110_dialog_content = "Go! Go! Go!",
  ui_story_5037_50370401_111_dialog_content = "Where does this prop go, Producer?",
  ui_story_5037_50370401_112_dialog_content = "Where's the producer?",
  ui_story_5037_50370401_113_dialog_content = "Producer! Producer!",
  ui_story_5037_50370401_114_dialog_content = "Ah, I-I need to go take care of things!",
  ui_story_5037_50370401_115_dialog_content = "Phew...",
  ui_story_5037_50370401_116_dialog_content = "The concert would be impossible without PlayerName.",
  ui_story_5037_50370401_117_dialog_content = "It's time for me to prepare for the stage now!",
  ui_story_5037_50370501_1_dialog_content = "Next, I'll announce our results.",
  ui_story_5037_50370501_2_dialog_content = "They're very shocking this time.",
  ui_story_5037_50370501_3_dialog_content = "(What would shock even Lady Sheol?)",
  ui_story_5037_50370501_4_dialog_content = "(Did Vic win...?)",
  ui_story_5037_50370501_5_dialog_content = "The winner weathered the pressure brought on by the first concert to successfully gain even more support in the audience this time.",
  ui_story_5037_50370501_6_dialog_content = "This was the fruits of the idol's hard work.",
  ui_story_5037_50370501_7_dialog_content = "As well as that of the producer, of course.",
  ui_story_5037_50370501_8_dialog_content = "(Hard work on both parts... That's Master and me, isn't it?)",
  ui_story_5037_50370501_9_dialog_content = "(Yes, Master finally beat Goldie!)",
  ui_story_5037_50370501_10_dialog_content = "And the winner is...",
  ui_story_5037_50370501_11_dialog_content = "...",
  ui_story_5037_50370501_12_dialog_content = "Hehe!",
  ui_story_5037_50370501_13_dialog_content = "<size=45>Goldie and PlayerName!</size>",
  ui_story_5037_50370501_14_dialog_content = "Did you hear that, PlayerName? We won!",
  ui_story_5037_50370501_15_dialog_content = "W-We won?",
  ui_story_5037_50370501_16_dialog_content = "Whaaaat? How can this be?",
  ui_story_5037_50370501_17_dialog_content = "Finally, one more step closer to home.",
  ui_story_5037_50370501_18_dialog_content = "Facts are harsh, but numbers don't lie, and more people supported Goldie than Vic this time.",
  ui_story_5037_50370501_19_dialog_content = "But Master's performance was obviously better than last time, so how come Goldie won?",
  ui_story_5037_50370501_20_dialog_content = "Well, Goldie truly gave a fantastic performance this time.",
  ui_story_5037_50370501_21_dialog_content = "The show itself was creative, but the lighting and stage design were also immaculate.",
  ui_story_5037_50370501_22_dialog_content = "What's more important is her concert converted many in the audience into her fans.",
  ui_story_5037_50370501_23_dialog_content = "They rushed to the Cloudrover Guild and bought out her merchandise.",
  ui_story_5037_50370501_24_dialog_content = "They even bought products that had nothing to do with Goldie.",
  ui_story_5037_50370501_25_dialog_content = "Through the Goldilocks' word of mouth...",
  ui_story_5037_50370501_26_dialog_content = "Catching a Goldie concert is now one of the ten must-dos in Umbraton.",
  ui_story_5037_50370501_27_dialog_content = "Everybody is looking forward to Starlit Agency's next concert.",
  ui_story_5037_50370501_28_dialog_content = "The tickets are sold out already! Can you imagine that?",
  ui_story_5037_50370501_29_dialog_content = "You mean I don't have to beg people to buy tickets now?",
  ui_story_5037_50370501_30_dialog_content = "I never thought I'd recoup my investment even before the reality show went on the air.",
  ui_story_5037_50370501_31_dialog_content = "You don't have to do extra promotions to get new fans anymore.",
  ui_story_5037_50370501_32_dialog_content = "Focus on your performance and embrace the final concert!",
  ui_story_5037_50370501_33_dialog_content = "Thank you, Lady Sheol.",
  ui_story_5037_50370501_34_dialog_content = "We'll strive to improve and reward you and the fans with better performances!",
  ui_story_5037_50370501_35_dialog_content = "I don't think I heard from you yet, Vic?",
  ui_story_5037_50370501_36_dialog_content = "Why don't we just forget it?",
  ui_story_5037_50370501_37_dialog_content = "Since I lost, you might as well let me go home now!",
  ui_story_5037_50370501_38_dialog_content = "I don't buy it, I just don't buy it.",
  ui_story_5037_50370501_39_dialog_content = "I think all of you conspired against Master and me.",
  ui_story_5037_50370501_40_dialog_content = "Tell me, Lady Sheol!",
  ui_story_5037_50370501_41_dialog_content = "This is how you wrote the script, right?",
  ui_story_5037_50370501_42_dialog_content = "A script for a reality show?",
  ui_story_5037_50370501_43_dialog_content = "You're a genius, Fia.",
  ui_story_5037_50370501_44_dialog_content = "Of course I am! Hehe.",
  ui_story_5037_50370501_45_dialog_content = "Wait a second, what made you say that?",
  ui_story_5037_50370501_46_dialog_content = "How come I didn't think of something as creative as writing a script for the reality show?",
  ui_story_5037_50370501_47_dialog_content = "I'd probably recoup my money faster.",
  ui_story_5037_50370501_48_dialog_content = "However, Fia, the results of this round are genuine.",
  ui_story_5037_50370501_49_dialog_content = "If you still have doubts, feel free to watch the concert replay.",
  ui_story_5037_50370501_50_dialog_content = "Come talk to me any time if you have questions afterward.",
  ui_story_5037_50370501_51_dialog_content = "<color=#828282>Some time later</color>",
  ui_story_5037_50370501_52_dialog_content = "How did they do that? How did they pull the trick off?!",
  ui_story_5037_50370501_53_dialog_content = "Goldie changed her outfit in just a second!?",
  ui_story_5037_50370501_54_dialog_content = "And appeared out of thin air in the audience, then flew back to the stage?",
  ui_story_5037_50370501_55_dialog_content = "In contrast, our concert fell more than just a little short.",
  ui_story_5037_50370501_56_dialog_content = "No wonder you never could make it before...",
  ui_story_5037_50370501_57_dialog_content = "Uh, ahem.",
  ui_story_5037_50370501_58_dialog_content = "So you finally get it now? Despite my vast talent, I can't measure up to a professional idol.",
  ui_story_5037_50370501_59_dialog_content = "It's not too early to concede now. I'll go pack up.",
  ui_story_5037_50370501_60_dialog_content = "Hold it right there!",
  ui_story_5037_50370501_61_dialog_content = "I know even without you saying it...",
  ui_story_5037_50370501_62_dialog_content = "that it's not your fault we lost.",
  ui_story_5037_50370501_63_dialog_content = "I'm the producer, but I was so fixated on your training that I neglected almost all other aspects of the show and stage.",
  ui_story_5037_50370501_64_dialog_content = "I thought you were the key to success this whole time...",
  ui_story_5037_50370501_65_dialog_content = "Until I just watched Goldie's show and realized how much other potential a concert can have!",
  ui_story_5037_50370501_66_dialog_content = "Your performance was outstanding.",
  ui_story_5037_50370501_67_dialog_content = "But I failed to give you the perfect stage.",
  ui_story_5037_50370501_68_dialog_content = "Honestly, just finishing the concert was good enough for me, so don't worry about that and let's go home...",
  ui_story_5037_50370501_69_dialog_content = "No way, I can't go yet!",
  ui_story_5037_50370501_70_dialog_content = "We have one last show to do. We can still turn things around.",
  ui_story_5037_50370501_71_dialog_content = "This time, I promise you'll be able to attain your idol dream and won't have any regrets!",
  ui_story_5037_50370501_72_dialog_content = "What...?",
  ui_story_5037_50370501_73_dialog_content = "I just watched the replay of Vic's concert.",
  ui_story_5037_50370501_74_dialog_content = "Your performance was like that of a pro idol, Vic.",
  ui_story_5037_50370501_75_dialog_content = "There were just a few dances in it that didn't properly showcase your charm.",
  ui_story_5037_50370501_76_dialog_content = "Really? Which ones?",
  ui_story_5037_50370501_77_dialog_content = "I'll do a review later and show it to you, Fia.",
  ui_story_5037_50370501_78_dialog_content = "By the way, I wrote a new ballad that I think would suit Vic well.",
  ui_story_5037_50370501_79_dialog_content = "I'll give that to you too when I'm done with the review!",
  ui_story_5037_50370501_80_dialog_content = "Wonderful!",
  ui_story_5037_50370501_81_dialog_content = "But is... is this appropriate?",
  ui_story_5037_50370501_82_dialog_content = "You're our competitor, so why are you helping us?",
  ui_story_5037_50370501_83_dialog_content = "Idols are supposed to bring hope and kindness to people.",
  ui_story_5037_50370501_84_dialog_content = "How can I be called an idol if I can't even bring kindness to those around me?",
  ui_story_5037_50370501_85_dialog_content = "I remember what you said before in an interview...",
  ui_story_5037_50370501_86_dialog_content = "Rather than an opponent, I think Vic is more akin to a comrade on this journey towards stardom.",
  ui_story_5037_50370501_87_dialog_content = "It was really brilliant...",
  ui_story_5037_50370501_88_dialog_content = "Amazing!!",
  ui_story_5037_50370501_89_dialog_content = "So that's how an idol is supposed to act?",
  ui_story_5037_50370501_90_dialog_content = "Oh no!",
  ui_story_5037_50370501_91_dialog_content = "People are going to think Master is a joke for saying what I told him to say in the interview!",
  ui_story_5037_50370501_92_dialog_content = "(I wonder what they said in the interview...)",
  ui_story_5037_50370501_93_dialog_content = "Would you mind deleting the interview we did and shooting another one, Lilica?",
  ui_story_5037_50370501_94_dialog_content = "I'm afraid that's not possible.",
  ui_story_5037_50370501_95_dialog_content = "This is a reality show, you know!",
  ui_story_5037_50370501_96_dialog_content = "Come over here, Kyllo!",
  ui_story_5037_50370501_97_dialog_content = "Lo!",
  ui_story_5037_50370501_98_dialog_content = "Hey, what do you think you're doing?",
  ui_story_5037_50370501_99_dialog_content = "No re-do even if you make Kyllo bite my ankle!",
  ui_story_5037_50370501_100_dialog_content = "Wait, don't run away!",
  ui_story_5037_50370501_101_dialog_content = "If you agree, you can play with Kyllo!",
  ui_story_5037_50370501_102_dialog_content = "Hmm, I think Fia has forgotten all about me...",
  ui_story_5037_50370501_103_dialog_content = "I can finally get my beauty sleep in!",
  ui_story_5037_50370501_104_dialog_content = "See you all later!",
  ui_story_5037_50370501_105_dialog_content = "The evaluation concert is finally over, Producer!",
  ui_story_5037_50370501_106_dialog_content = "You worked really hard for it, Goldie.",
  ui_story_5037_50370501_107_dialog_content = "And what a spectacular show it was... Dare I call it the greatest of all time?",
  ui_story_5037_50370501_108_dialog_content = "Let's not be rash, PlayerName.",
  ui_story_5037_50370501_109_dialog_content = "Don't we have one more to go?",
  ui_story_5037_50370501_110_dialog_content = "True. The best show is always the next one!",
  ui_story_5037_50370501_111_dialog_content = "Haha, that's a great line!",
  ui_story_5037_50370501_112_dialog_content = "Have you already decided on the last concert's theme?",
  ui_story_5037_50370501_113_dialog_content = "Oh, that's right, I still need to flesh it out.",
  ui_story_5037_50370501_114_dialog_content = "Don't worry about me, get yourself some rest!",
  ui_story_5037_50370501_115_dialog_content = "All right! You do the same too, PlayerName!",
  ui_story_5037_50370501_116_dialog_content = "Marshmallow.",
  ui_story_5037_50370501_117_dialog_content = "Woof!",
  ui_story_5037_50370501_118_dialog_content = "There was a thief stealing stuff at the concert.",
  ui_story_5037_50370501_119_dialog_content = "Did you notice too?",
  ui_story_5037_50370501_120_dialog_content = "Woof!",
  ui_story_5037_50370501_121_dialog_content = "I can't believe someone would dare do that at my show...",
  ui_story_5037_50370501_122_dialog_content = "Are you ready, Marshmallow?",
  ui_story_5037_50370501_123_dialog_content = "We're gonna deliver swift justice tonight!",
  ui_story_5037_50370501_124_dialog_content = "Woof!",
  ui_story_5037_50370501_125_dialog_content = "Post-concert friends interview...",
  ui_story_5037_50370501_126_dialog_content = "Action!",
  ui_story_5037_50370501_127_dialog_content = "On a scale of one to ten, how would you rate the concert?",
  ui_story_5037_50370501_128_dialog_content = "Twelve for sure!",
  ui_story_5037_50370501_129_dialog_content = "Close to a ten.",
  ui_story_5037_50370501_130_dialog_content = "Pfft, I can't believe that guy was actually singing and dancing on stage...",
  ui_story_5037_50370501_131_dialog_content = "But I don't want to give a score.",
  ui_story_5037_50370501_132_dialog_content = "Why? Because I don't want those two thinking too highly of themselves.",
  ui_story_5037_50370501_133_dialog_content = "How do you feel about the opponent's concert?",
  ui_story_5037_50370501_134_dialog_content = "Ten!",
  ui_story_5037_50370501_135_dialog_content = "It was flawless, but Goldie's show was obviously much more engaging.",
  ui_story_5037_50370501_136_dialog_content = "Nine.",
  ui_story_5037_50370501_137_dialog_content = "I didn't watch it, but probably not as good as Fia and Vic.",
  ui_story_5037_50370501_138_dialog_content = "Is there something you want to say to your friend?",
  ui_story_5037_50370501_139_dialog_content = "Be yourself and go get them, PlayerName!",
  ui_story_5037_50370501_140_dialog_content = "Effort yields outcomes.",
  ui_story_5037_50370501_141_dialog_content = "I heard there's prize money?",
  ui_story_5037_50370501_142_dialog_content = "You guys better bring it home!",
  ui_story_5037_50370501_143_dialog_content = "Or else...!",
  ui_story_5037_50370501_144_dialog_content = "Please do not wrap tentacles around the camera!",
  ui_story_5037_50370601_1_dialog_content = "Exclusive Team PlayerName pre-final concert interview...",
  ui_story_5037_50370601_2_dialog_content = "Action!",
  ui_story_5037_50370601_3_dialog_content = "What is the theme you've chosen for the final concert?",
  ui_story_5037_50370601_4_dialog_content = "Our theme this time is \"Unbridled Youth.\"",
  ui_story_5037_50370601_5_dialog_content = "Oh, by the way...",
  ui_story_5037_50370601_6_dialog_content = "The concert is final in name only. Goldie is not leaving Starlit Agency.",
  ui_story_5037_50370601_7_dialog_content = "That's right, from \"New Beginning\" to \"Budding Flower\" to \"Unbridled Youth\"...",
  ui_story_5037_50370601_8_dialog_content = "All three performances are meant to present the microcosm of an idol's metamorphosis through the course of the reality show.",
  ui_story_5037_50370601_9_dialog_content = "Goldie will remain active even after the program wraps.",
  ui_story_5037_50370601_10_dialog_content = "That is true. I'll have more shows to come!",
  ui_story_5037_50370601_11_dialog_content = "Though I may not be Goldie's producer anymore by then...",
  ui_story_5037_50370601_12_dialog_content = "...",
  ui_story_5037_50370601_13_dialog_content = "Well, it's very hard to become a producer for the Starlit Agency.",
  ui_story_5037_50370601_14_dialog_content = "You have to send in a resume and pass all kinds of tests.",
  ui_story_5037_50370601_15_dialog_content = "Even an outstanding producer like PlayerName would have doubts.",
  ui_story_5037_50370601_16_dialog_content = "If it wasn't for the reality show, I probably would have gotten lost in the shuffle among the talents in Umbraton.",
  ui_story_5037_50370601_17_dialog_content = "After the program is over, I don't think I'll be able to beat out other people to become a real producer.",
  ui_story_5037_50370601_18_dialog_content = "But I'm satisfied with just the chance to see Goldie through this portion of her career.",
  ui_story_5037_50370601_19_dialog_content = "PlayerName...",
  ui_story_5037_50370601_20_dialog_content = "It's too soon to get all sentimental!",
  ui_story_5037_50370601_21_dialog_content = "Did you write new songs for this concert, Goldie?",
  ui_story_5037_50370601_22_dialog_content = "Of course.",
  ui_story_5037_50370601_23_dialog_content = "After learning PlayerName chose \"Unbridled Youth\" for the theme...",
  ui_story_5037_50370601_24_dialog_content = "I asked myself, \"What exactly is youth??\"",
  ui_story_5037_50370601_25_dialog_content = "Immediately, images filled my head.",
  ui_story_5037_50370601_26_dialog_content = "Is it chasing each other, carefree, through the streets of Umbraton?",
  ui_story_5037_50370601_27_dialog_content = "Is it listening to a lecture in a classroom with sleepy eyes?",
  ui_story_5037_50370601_28_dialog_content = "Or is it sweating at your job to eke out a living?",
  ui_story_5037_50370601_29_dialog_content = "Then I reminded myself, youth is not rigid and set in stone.",
  ui_story_5037_50370601_30_dialog_content = "Every form of youth deserves to be celebrated!",
  ui_story_5037_50370601_31_dialog_content = "From those images, I composed the songs I wished to perform.",
  ui_story_5037_50370601_32_dialog_content = "How do you feel about Goldie's new songs this time, PlayerName?",
  ui_story_5037_50370601_33_dialog_content = "Oh, you can never go wrong with her songs!",
  ui_story_5037_50370601_34_dialog_content = "The ones she wrote for \"Unbridled Youth\" are particularly captivating.",
  ui_story_5037_50370601_35_dialog_content = "Especially the song about parting ways...",
  ui_story_5037_50370601_36_dialog_content = "Lady Sheol already grabbed it for the reality show's ending theme song.",
  ui_story_5037_50370601_37_dialog_content = "It's true that nothing's forever and parting is inevitable...",
  ui_story_5037_50370601_38_dialog_content = "but I'll keep working hard, stay relevant, and grow alongside everyone.",
  ui_story_5037_50370601_39_dialog_content = "So keep your eyes on my career developments!",
  ui_story_5037_50370601_40_dialog_content = "Anything you would like to say to your producer, Goldie?",
  ui_story_5037_50370601_41_dialog_content = "What? You're asking that before the concert?",
  ui_story_5037_50370601_42_dialog_content = "It's okay.",
  ui_story_5037_50370601_43_dialog_content = "I might be too choked up to talk after the concert anyway!",
  ui_story_5037_50370601_44_dialog_content = "Huh?",
  ui_story_5037_50370601_45_dialog_content = "Ahem, what I'd like to say to my producer is:",
  ui_story_5037_50370601_46_dialog_content = "Thank you for sticking with me all this time.",
  ui_story_5037_50370601_47_dialog_content = "To be honest, I've always gone solo in this business, so I'm not used to having a producer.",
  ui_story_5037_50370601_48_dialog_content = "It's only for the reality show that I agreed to take you on as my producer.",
  ui_story_5037_50370601_49_dialog_content = "But since then, you've gone from a total newbie to a consummate pro.",
  ui_story_5037_50370601_50_dialog_content = "You not only handled my schedule but also dealt with the paparazzi and sorted out concert details...",
  ui_story_5037_50370601_51_dialog_content = "Your presence allowed me to create and rehearse with ease.",
  ui_story_5037_50370601_52_dialog_content = "In fact, I find it more and more difficult to imagine doing this without you.",
  ui_story_5037_50370601_53_dialog_content = "Maybe you'll never be a producer again, but I still want you to know...",
  ui_story_5037_50370601_54_dialog_content = "you're the best producer to me...",
  ui_story_5037_50370601_55_dialog_content = "... so far.",
  ui_story_5037_50370601_56_dialog_content = "But I'm the only producer you've ever had.",
  ui_story_5037_50370601_57_dialog_content = "I'm not done yet. You've got my support in the future no matter where you go or what you do!",
  ui_story_5037_50370601_58_dialog_content = "I'm sure you'll excel in whatever you choose to do.",
  ui_story_5037_50370601_59_dialog_content = "And when that time comes...",
  ui_story_5037_50370601_60_dialog_content = "I'll also...",
  ui_story_5037_50370601_61_dialog_content = "Goldie?",
  ui_story_5037_50370601_62_dialog_content = "Cough...",
  ui_story_5037_50370601_63_dialog_content = "<size=30>Please edit that out, Lilica, and let me start over!</size>",
  ui_story_5037_50370601_64_dialog_content = "You've got my support in the future no matter where you go or what you do!",
  ui_story_5037_50370601_65_dialog_content = "I'm sure you'll excel in whatever you choose to do.",
  ui_story_5037_50370601_66_dialog_content = "While you're doing that, I'll still be striving along on my chosen path, building upon the groundwork you've laid for me!",
  ui_story_5037_50370601_67_dialog_content = "Anything you would like to say to Goldie, Producer?",
  ui_story_5037_50370601_68_dialog_content = "I want to thank Goldie as well.",
  ui_story_5037_50370601_69_dialog_content = "Because of your encouragement, I did so many things I wouldn't have dared dream about.",
  ui_story_5037_50370601_70_dialog_content = "We made it this far only because you're already a shining star!",
  ui_story_5037_50370601_71_dialog_content = "All the skills I've learned and developed during this time...",
  ui_story_5037_50370601_72_dialog_content = "Every bit is a reflection of the brilliance that is Goldie!",
  ui_story_5037_50370601_73_dialog_content = "You're brilliant yourself too, PlayerName!",
  ui_story_5037_50370601_74_dialog_content = "Even when I'm no longer by your side, Goldie...",
  ui_story_5037_50370601_75_dialog_content = "You'll always be a shining star.",
  ui_story_5037_50370601_76_dialog_content = "One day, you'll be a legendary idol in Astra!",
  ui_story_5037_50370601_77_dialog_content = "And you will always have my regards and blessings.",
  ui_story_5037_50370601_78_dialog_content = "Exclusive Team PlayerName pre-final concert interview...",
  ui_story_5037_50370601_79_dialog_content = "is a wrap!",
  ui_story_5037_50370601_80_dialog_content = "...",
  ui_story_5037_50370601_81_dialog_content = "...",
  ui_story_5037_50370601_82_dialog_content = "Uh, what's with the awkward silence?",
  ui_story_5037_50370601_83_dialog_content = "Should I not have asked those questions?",
  ui_story_5037_50370601_84_dialog_content = "Does this type of interview put a damper on the show's atmosphere?",
  ui_story_5037_50370601_85_dialog_content = "Please tell me it won't affect your upcoming performance...",
  ui_story_5037_50370601_86_dialog_content = "It's fine, Lilica.",
  ui_story_5037_50370601_87_dialog_content = "See, I'm totally fine!",
  ui_story_5037_50370601_88_dialog_content = "Wonderful, that's the Goldie smile we're familiar with!",
  ui_story_5037_50370601_89_dialog_content = "Producer PlayerName!",
  ui_story_5037_50370601_90_dialog_content = "Yeah, here.",
  ui_story_5037_50370601_91_dialog_content = "Thanks!",
  ui_story_5037_50370601_92_dialog_content = "Wait, did I miss something again?",
  ui_story_5037_50370601_93_dialog_content = "Ah!",
  ui_story_5037_50370601_94_dialog_content = "These mints really soothe me.",
  ui_story_5037_50370601_95_dialog_content = "Excuse me, which way to Goldie's concert?",
  ui_story_5037_50370601_96_dialog_content = "How did an audience member get backstage?",
  ui_story_5037_50370601_97_dialog_content = "Just follow this passage and make a left!",
  ui_story_5037_50370601_98_dialog_content = "Wow, I can't believe this luck! Isn't this Goldie herself?",
  ui_story_5037_50370601_99_dialog_content = "Yeah, it is! Can you sign my shirt, Goldie?!",
  ui_story_5037_50370601_100_dialog_content = "I came all the way from Northland!",
  ui_story_5037_50370601_101_dialog_content = "I'm a fan too! I'm from the Rediesel Wrench!",
  ui_story_5037_50370601_102_dialog_content = "I'm from Cloud Island!",
  ui_story_5037_50370601_103_dialog_content = "I'm from Euphoria!",
  ui_story_5037_50370601_104_dialog_content = "Everyone, everyone!",
  ui_story_5037_50370601_105_dialog_content = "Goldie will spare time to autograph and take pictures with everyone after the show.",
  ui_story_5037_50370601_106_dialog_content = "You should head over to the venue now because the concert is starting soon.",
  ui_story_5037_50370601_107_dialog_content = "Autographs and pictures after the show?",
  ui_story_5037_50370601_108_dialog_content = "I'm gonna head to the concert first, then!",
  ui_story_5037_50370601_109_dialog_content = "Hurry! I bet the ones that get there first will be first in line for autographs!",
  ui_story_5037_50370601_110_dialog_content = "No need to rush. Everyone will get a chance!",
  ui_story_5037_50370601_111_dialog_content = "They ran off so fast, I don't think they caught anything I said.",
  ui_story_5037_50370601_112_dialog_content = "There are so many people this time, from all over!",
  ui_story_5037_50370601_113_dialog_content = "It's a good sign for Goldie's future Astra tour!",
  ui_story_5037_50370601_114_dialog_content = "What's wrong, Goldie?",
  ui_story_5037_50370601_115_dialog_content = "I'm suddenly so nervous.",
  ui_story_5037_50370601_116_dialog_content = "It feels like I'm getting on stage for the first time...",
  ui_story_5037_50370601_117_dialog_content = "Look at the audience out there, Goldie.",
  ui_story_5037_50370601_118_dialog_content = "They came because they love you!",
  ui_story_5037_50370601_119_dialog_content = "And you deserve to be loved.",
  ui_story_5037_50370601_120_dialog_content = "PlayerName...",
  ui_story_5037_50370601_121_dialog_content = "You're right!",
  ui_story_5037_50370601_122_dialog_content = "I'm not the person I used to be.",
  ui_story_5037_50370601_123_dialog_content = "You just watch!",
  ui_story_5037_50370601_124_dialog_content = "I'll perform...",
  ui_story_5037_50370601_125_dialog_content = "to the best of my abilities!",
  ui_story_5037_50370701_1_dialog_content = "The graduation concert was a success.",
  ui_story_5037_50370701_2_dialog_content = "The lighting and props were all perfect, and Goldie's performance equally so.",
  ui_story_5037_50370701_3_dialog_content = "We presented everything we wanted down to the perfect detail.",
  ui_story_5037_50370701_4_dialog_content = "The crowd chanted Goldie's name and stuck around for a long time.",
  ui_story_5037_50370701_5_dialog_content = "There was nothing but excitement and joy all around the stage.",
  ui_story_5037_50370701_6_dialog_content = "But then...",
  ui_story_5037_50370701_7_dialog_content = "why do I suddenly feel sad?",
  ui_story_5037_50370701_8_dialog_content = "Oh!",
  ui_story_5037_50370701_9_dialog_content = "I almost forgot, Lady Sheol's supposed to announce the final results right now!",
  ui_story_5037_50370701_10_dialog_content = "I'm running late!",
  ui_story_5037_50370701_11_dialog_content = "Huff... huff...",
  ui_story_5037_50370701_12_dialog_content = "Sorry for being late!",
  ui_story_5037_50370701_13_dialog_content = "Any longer and I'd think you decided to forfeit, Producer PlayerName.",
  ui_story_5037_50370701_14_dialog_content = "Where's Goldie? How come you came by yourself?",
  ui_story_5037_50370701_15_dialog_content = "Goldie is tied up, mingling with the fans.",
  ui_story_5037_50370701_16_dialog_content = "Hmph! My master is currently being swarmed by fans wanting pictures too!",
  ui_story_5037_50370701_17_dialog_content = "My darling idols sure are popular.",
  ui_story_5037_50370701_18_dialog_content = "That's good. A very good sign!",
  ui_story_5037_50370701_19_dialog_content = "I'd love wait for them to finish so I can congratulate them both in person.",
  ui_story_5037_50370701_20_dialog_content = "But I have an appointment with a movie studio exec later.",
  ui_story_5037_50370701_21_dialog_content = "You seem busier than we are.",
  ui_story_5037_50370701_22_dialog_content = "It's all right, just tell us the outcome, Lady Sheol.",
  ui_story_5037_50370701_23_dialog_content = "You just can't wait, can you, Fia?",
  ui_story_5037_50370701_24_dialog_content = "But that's not a bad thing. It was evident from Vic's concert...",
  ui_story_5037_50370701_25_dialog_content = "that you learned how to plan a show in a very short time period.",
  ui_story_5037_50370701_26_dialog_content = "Vic's graduation concert showed significant improvements in presentation.",
  ui_story_5037_50370701_27_dialog_content = "Of course, I put in lots of effort!",
  ui_story_5037_50370701_28_dialog_content = "As for Goldie, her show was already almost unsurpassable.",
  ui_story_5037_50370701_29_dialog_content = "But PlayerName still managed to insert surprises on the stage for the audience to enjoy.",
  ui_story_5037_50370701_30_dialog_content = "Coupled with Goldie's new songs, it was touching and moving.",
  ui_story_5037_50370701_31_dialog_content = "What? I thought only I would get all the praise.",
  ui_story_5037_50370701_32_dialog_content = "Now as for the results, Team Fia—",
  ui_story_5037_50370701_33_dialog_content = "What what what?",
  ui_story_5037_50370701_34_dialog_content = "I won?!",
  ui_story_5037_50370701_35_dialog_content = "Let me finish, darling.",
  ui_story_5037_50370701_36_dialog_content = "Unfortunately, Team Fia lost to Team PlayerName by a very slim margin.",
  ui_story_5037_50370701_37_dialog_content = "They won by merely 10 tickets.",
  ui_story_5037_50370701_38_dialog_content = "Huh?",
  ui_story_5037_50370701_39_dialog_content = "After tallying the results of all three concerts, victory goes to...",
  ui_story_5037_50370701_40_dialog_content = "<size=45>PlayerName and Goldie!</size>",
  ui_story_5037_50370701_41_dialog_content = "...",
  ui_story_5037_50370701_42_dialog_content = "Waah...!",
  ui_story_5037_50370701_43_dialog_content = "I w-worked so hard...",
  ui_story_5037_50370701_44_dialog_content = "I spent so much time keeping my undisciplined master on a leash, but I also had to stay up all night learning how to stage a concert...",
  ui_story_5037_50370701_45_dialog_content = "Fia, you're going to miss my next announcement if you don't calm down.",
  ui_story_5037_50370701_46_dialog_content = "What?",
  ui_story_5037_50370701_47_dialog_content = "Fia and Vic managed to garner many fans during this time period through their endeavors and contributed to a lot of Cloudrover Guild merchandise sales.",
  ui_story_5037_50370701_48_dialog_content = "In light of your excellent performance...",
  ui_story_5037_50370701_49_dialog_content = "You'll get a bonus too!",
  ui_story_5037_50370701_50_dialog_content = "A bonus...",
  ui_story_5037_50370701_51_dialog_content = "Prize money?!",
  ui_story_5037_50370701_52_dialog_content = "I knew it. Master and I didn't suffer for nothing! Hard work can really lead to good outcomes! *Sob*",
  ui_story_5037_50370701_53_dialog_content = "Ahem, there's more!",
  ui_story_5037_50370701_54_dialog_content = "The winner of Hardest Working Idol on our reality show is...",
  ui_story_5037_50370701_55_dialog_content = "Vic!",
  ui_story_5037_50370701_56_dialog_content = "Master? Master won something?",
  ui_story_5037_50370701_57_dialog_content = "And Hardest Working Idol of all things?",
  ui_story_5037_50370701_58_dialog_content = "Master beat Goldie and received everyone's support!",
  ui_story_5037_50370701_59_dialog_content = "I'm so proud of my master!",
  ui_story_5037_50370701_60_dialog_content = "Hehe, this is also a nod to Kyllo and my efforts!",
  ui_story_5037_50370701_61_dialog_content = "Lo!",
  ui_story_5037_50370701_62_dialog_content = "Pardon us, PlayerName, but this one is ours!",
  ui_story_5037_50370701_63_dialog_content = "Vic worked very hard, indeed, so I feel he deserves it.",
  ui_story_5037_50370701_64_dialog_content = "Next, the Best Producer goes to...",
  ui_story_5037_50370701_65_dialog_content = "<size=45>PlayerName!</size>",
  ui_story_5037_50370701_66_dialog_content = "What?",
  ui_story_5037_50370701_67_dialog_content = "Me, best producer?",
  ui_story_5037_50370701_68_dialog_content = "...!",
  ui_story_5037_50370701_69_dialog_content = "Hmph, fine.",
  ui_story_5037_50370701_70_dialog_content = "I admit PlayerName mastered the skills of a producer quicker and better than I did.",
  ui_story_5037_50370701_71_dialog_content = "But he's also older than me!",
  ui_story_5037_50370701_72_dialog_content = "Wait till I'm his age. I'll be more awesome for sure!",
  ui_story_5037_50370701_73_dialog_content = "Fia?",
  ui_story_5037_50370701_74_dialog_content = "She just left like that.",
  ui_story_5037_50370701_75_dialog_content = "It's all right, she's likely going back to her master.",
  ui_story_5037_50370701_76_dialog_content = "She might have a sharp tongue, but her heart is in the right place.",
  ui_story_5037_50370701_77_dialog_content = "How do you have such insight into Fia?",
  ui_story_5037_50370701_78_dialog_content = "While I'm not a Caelestite and don't have psychic abilities...",
  ui_story_5037_50370701_79_dialog_content = "I'm more perceptive of people than even you.",
  ui_story_5037_50370701_80_dialog_content = "How else do you think I started from scratch and built Cloudrover Guild up to where it is now?",
  ui_story_5037_50370701_81_dialog_content = "...",
  ui_story_5037_50370701_82_dialog_content = "Lilica.",
  ui_story_5037_50370701_83_dialog_content = "I'm here, Lady Sheol!",
  ui_story_5037_50370701_84_dialog_content = "I love all the B-roll footage you took for the show.",
  ui_story_5037_50370701_85_dialog_content = "With proper editing, it will be a quality reality show.",
  ui_story_5037_50370701_86_dialog_content = "By then, lots of new directing opportunities will be waiting for you.",
  ui_story_5037_50370701_87_dialog_content = "I'll be sure the edit the best show ever!",
  ui_story_5037_50370701_88_dialog_content = "And please feel free to ask me for anything in the future, Lady Sheol!",
  ui_story_5037_50370701_89_dialog_content = "Sure. I expect interesting stories to come out post-concert, too.",
  ui_story_5037_50370701_90_dialog_content = "Keep an eye on them so you don't miss out on anything.",
  ui_story_5037_50370701_91_dialog_content = "Okay!",
  ui_story_5037_50370701_92_dialog_content = "I got this!",
  ui_story_5037_50370701_93_dialog_content = "You're welcome to stay and be a producer, PlayerName.",
  ui_story_5037_50370701_94_dialog_content = "Just remember to send your resume to my office.",
  ui_story_5037_50370701_95_dialog_content = "Okay!",
  ui_story_5037_50370701_96_dialog_content = "And I'm out of time. I have to go deal with business matters now.",
  ui_story_5037_50370701_97_dialog_content = "Looking forward to good news from all of you!",
  ui_story_5037_50370701_98_dialog_content = "Bye, Lady Sheol!",
  ui_story_5037_50370701_99_dialog_content = "Hmm, is this the end of my producer career?",
  ui_story_5037_50370701_100_dialog_content = "...",
  ui_story_5037_50370701_101_dialog_content = "What the... What are you doing with that camera in my face, Lilica?",
  ui_story_5037_50370701_102_dialog_content = "The reality show is not over yet.",
  ui_story_5037_50370701_103_dialog_content = "I have to keep working.",
  ui_story_5037_50370701_104_dialog_content = "But the concert is done, and there's nothing else to do...",
  ui_story_5037_50370701_105_dialog_content = "What else is there for you to film?",
  ui_story_5037_50370701_106_dialog_content = "You, of course.",
  ui_story_5037_50370701_107_dialog_content = "Best Producer!",
  ui_story_5037_50370701_108_dialog_content = "Uh, is there something I need to do?",
  ui_story_5037_50370701_109_dialog_content = "Ask yourself.",
  ui_story_5037_50370701_110_dialog_content = "Ask myself?",
  ui_story_5037_50370701_111_dialog_content = "Yeah, for example... who do you want to see most at the moment?",
  ui_story_5037_50370701_112_dialog_content = "Who do I want to see?",
  ui_story_5037_50370701_113_dialog_content = "That's right, the day's not over yet!",
  ui_story_5037_50370701_114_dialog_content = "I'd like to go see...",
  ui_story_5037_50370701_115_option_content = "Goldie",
  ui_story_5037_50370701_116_dialog_content = "I have to go tell her we won!",
  ui_story_5037_50370701_117_option_content = "Vic and Fia",
  ui_story_5037_50370701_118_dialog_content = "I have to go congratulate Vic!",
  ui_story_5037_50370701_119_option_content = "Vice and Carleen",
  ui_story_5037_50370701_120_dialog_content = "I want to thank them both...",
  ui_story_5037_50370701_121_dialog_content = "I want to tell Goldie we won as soon as possible!",
  ui_story_5037_50370701_122_dialog_content = "Then I'll tell her what I wanted to say to her...",
  ui_story_5037_50370701_123_dialog_content = "Hold it!",
  ui_story_5037_50370701_124_dialog_content = "But I said those things already!",
  ui_story_5037_50370701_125_dialog_content = "I guess I should talk about the prize money?",
  ui_story_5037_50370701_126_dialog_content = "\"Goldie, with this money, you'll be able to buy more dresses!\"",
  ui_story_5037_50370701_127_dialog_content = "That sounds awkward...",
  ui_story_5037_50370701_128_dialog_content = "\"We won the money all thanks to you, Goldie!\"",
  ui_story_5037_50370701_129_dialog_content = "No, that makes me sound like I'm sucking up to her.",
  ui_story_5037_50370701_130_dialog_content = "\"Good job, Goldie!\"",
  ui_story_5037_50370701_131_dialog_content = "That sound like too much of an understatement...",
  ui_story_5037_50370701_132_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5037_50370701_133_dialog_content = "Thank you all for your support!",
  ui_story_5037_50370701_134_dialog_content = "Please line up one at a time, don't trip!",
  ui_story_5037_50370701_135_dialog_content = "The concert ended a long while ago, but she's still got so many fans buzzing around her!",
  ui_story_5037_50370701_136_dialog_content = "She seems to be having a good time with them.",
  ui_story_5037_50370701_137_dialog_content = "I shouldn't barge in.",
  ui_story_5037_50370701_138_dialog_content = "I can use this time to figure out what I'm going to say to her later!",
  ui_story_5037_50370701_139_dialog_content = "<size=45>PlayerName!</size>",
  ui_story_5037_50370701_140_dialog_content = "Was that Goldie calling for me?",
  ui_story_5037_50370701_141_dialog_content = "<size=50>PlayerName, come here quick!</size>",
  ui_story_5037_50370701_142_dialog_content = "Does she want me to talk to the fans too?",
  ui_story_5037_50370701_143_dialog_content = "I don't think I should go. They're all her fans and wouldn't be interested in me.",
  ui_story_5037_50370701_144_dialog_content = "Please give me a minute, I'll be right back!",
  ui_story_5037_50370701_145_dialog_content = "Wherever Goldie goes, the Goldilocks follow!",
  ui_story_5037_50370701_146_dialog_content = "Wait...",
  ui_story_5037_50370701_147_dialog_content = "Why is she coming this way?",
  ui_story_5037_50370701_148_dialog_content = "What are you doing just standing here, Producer?",
  ui_story_5037_50370701_149_dialog_content = "Oh, I-I just came to tell you...",
  ui_story_5037_50370701_150_dialog_content = "We won!",
  ui_story_5037_50370701_151_dialog_content = "It's about time you found out, PlayerName.",
  ui_story_5037_50370701_152_dialog_content = "You knew already?",
  ui_story_5037_50370701_153_dialog_content = "Yeah, right after I finished the last song.",
  ui_story_5037_50370701_154_dialog_content = "We did our best at every performance and left no regrets behind on the stage.",
  ui_story_5037_50370701_155_dialog_content = "We already won when we conquered ourselves.",
  ui_story_5037_50370701_156_dialog_content = "So that's how you see this.",
  ui_story_5037_50370701_157_dialog_content = "A lot of fans were praising the stage designs. Why don't you go mingle with them?",
  ui_story_5037_50370701_158_dialog_content = "Well, I...",
  ui_story_5037_50370701_159_dialog_content = "It's not polite for idols or idol producers to keep fans waiting!",
  ui_story_5037_50370701_160_dialog_content = "Sorry to keep you waiting, my dear Goldilocks!",
  ui_story_5037_50370701_161_dialog_content = "I would like to introduce someone to you all.",
  ui_story_5037_50370701_162_dialog_content = "Drum roll, please!",
  ui_story_5037_50370701_163_dialog_content = "H-Hi, everybody!",
  ui_story_5037_50370701_164_dialog_content = "That's right, the shy person next to me is the legendary Caelestite, PlayerName!",
  ui_story_5037_50370701_165_dialog_content = "Also, PlayerName is the producer who's been helping me all this time!",
  ui_story_5037_50370701_166_dialog_content = "The shows went so well all thanks to him!",
  ui_story_5037_50370701_167_dialog_content = "I'm flattered. Actually, I'm very new to the role.",
  ui_story_5037_50370701_168_dialog_content = "Goldie's producer was a noob? I wouldn't have guessed.",
  ui_story_5037_50370701_169_dialog_content = "You know what they say, never judge a book by its cover!",
  ui_story_5037_50370701_170_dialog_content = "I would call myself a diehard Goldie fan who's been there since day one.",
  ui_story_5037_50370701_171_dialog_content = "Goldie was already outstanding in every aspect, but getting a producer...",
  ui_story_5037_50370701_172_dialog_content = "really helped her improve a lot and helped her find her own style!",
  ui_story_5037_50370701_173_dialog_content = "I don't understand all that jargon.",
  ui_story_5037_50370701_174_dialog_content = "All I know is I've never been to such a pleasant, delightful show!",
  ui_story_5037_50370701_175_dialog_content = "It's all thanks to Producer PlayerName!",
  ui_story_5037_50370701_176_dialog_content = "Producer PlayerName! Producer PlayerName! Producer PlayerName!",
  ui_story_5037_50370701_177_dialog_content = "...",
  ui_story_5037_50370701_178_dialog_content = "(It's kind of embarrassing to hear so many people call my name...)",
  ui_story_5037_50370701_179_dialog_content = "(All I did is some backstage stuff. Does that even warrant any cheers?)",
  ui_story_5037_50370701_180_dialog_content = "Producer PlayerName...",
  ui_story_5037_50370701_181_dialog_content = "Of course you deserve the cheers.",
  ui_story_5037_50370701_182_dialog_content = "You've worked so hard lately!",
  ui_story_5037_50370701_183_dialog_content = "(How did Goldie know what I was thinking?)",
  ui_story_5037_50370701_184_dialog_content = "(And she even stole my line!)",
  ui_story_5037_50370701_185_dialog_content = "I think everyone wants to talk to you, PlayerName!",
  ui_story_5037_50370701_186_dialog_content = "Huh?",
  ui_story_5037_50370701_187_dialog_content = "Autograph, please, Producer!",
  ui_story_5037_50370701_188_dialog_content = "I'm not a Lovegator, but I also want PlayerName's autograph!",
  ui_story_5037_50370701_189_dialog_content = "Me too!",
  ui_story_5037_50370701_190_dialog_content = "And me!",
  ui_story_5037_50370701_191_dialog_content = "What's going on...?!",
  ui_story_5037_50370701_192_dialog_content = "I would've practiced my signature if I knew this was going to happen...",
  ui_story_5037_50370701_193_dialog_content = "Wow!",
  ui_story_5037_50370701_194_dialog_content = "I've never counted so many Nightium before!",
  ui_story_5037_50370701_195_dialog_content = "So this is what it feels like to be rich?",
  ui_story_5037_50370701_196_dialog_content = "Lady Sheol is too generous!",
  ui_story_5037_50370701_197_dialog_content = "Who are you talking to, Fia?",
  ui_story_5037_50370701_198_dialog_content = "I don't see anyone else around.",
  ui_story_5037_50370701_199_dialog_content = "Who else could I be talking to other than my master?",
  ui_story_5037_50370701_200_dialog_content = "Your master?",
  ui_story_5037_50370701_201_dialog_content = "What the... I wouldn't even have noticed if you hadn't brought him up...",
  ui_story_5037_50370701_202_dialog_content = "That slacker master of mine dozed off under the table again!",
  ui_story_5037_50370701_203_dialog_content = "Drag Master out now, Kyllo!",
  ui_story_5037_50370701_204_dialog_content = "Lo!",
  ui_story_5037_50370701_205_dialog_content = "Huh?",
  ui_story_5037_50370701_206_dialog_content = "Anyways, where did you even come from, PlayerName?",
  ui_story_5037_50370701_207_dialog_content = "Well, the door was open, so I walked in.",
  ui_story_5037_50370701_208_dialog_content = "What?! How could I have forgotten to close the door before counting the money?!",
  ui_story_5037_50370701_209_dialog_content = "I-It's fine, Fia. I shut it for you.",
  ui_story_5037_50370701_210_dialog_content = "But what if a thief snuck in?!",
  ui_story_5037_50370701_211_dialog_content = "Ugh, nope, I have to count all the Nightium again!",
  ui_story_5037_50370701_212_dialog_content = "Lo-lo!",
  ui_story_5037_50370701_213_dialog_content = "Nnng... No more training, please...",
  ui_story_5037_50370701_214_dialog_content = "Vic?",
  ui_story_5037_50370701_215_dialog_content = "Let's run, Little Furball! Ruuuun!",
  ui_story_5037_50370701_216_dialog_content = "Is he... talking in his sleep?",
  ui_story_5037_50370701_217_dialog_content = "Eighty-three, eighty-four, eighty-five...",
  ui_story_5037_50370701_218_dialog_content = "Fia, there won't be more of it, no matter how many times you count it.",
  ui_story_5037_50370701_219_dialog_content = "Besides, don't you think you should check on your master? Just look at him.",
  ui_story_5037_50370701_220_dialog_content = "Kyllo dragged him out from under the table, but he still hasn't woken up!",
  ui_story_5037_50370701_221_dialog_content = "Just a second! I'll get to you once I count to a hundred...",
  ui_story_5037_50370701_222_dialog_content = "Ninety-eight, ninety-nine... One hundred!",
  ui_story_5037_50370701_223_dialog_content = "Alright, now, what were you saying just now?",
  ui_story_5037_50370701_224_dialog_content = "Uh, maybe you should check on your master.",
  ui_story_5037_50370701_225_dialog_content = "He's completely unresponsive.",
  ui_story_5037_50370701_226_dialog_content = "Oh, he's just taking one of his naps, that's all.",
  ui_story_5037_50370701_227_dialog_content = "The last few days have really done a number on him...",
  ui_story_5037_50370701_228_dialog_content = "Though I guess that's pretty normal for someone who's never worked a day in their life!",
  ui_story_5037_50370701_229_dialog_content = "Ruuuuuuuuun!!!",
  ui_story_5037_50370701_230_dialog_content = "Hey, Vic? Are you awake now?",
  ui_story_5037_50370701_231_dialog_content = "PlayerName? What are you doing here?!",
  ui_story_5037_50370701_232_dialog_content = "R-Run! Kyllo's gone into a frenzy! It keeps forcing me to train!",
  ui_story_5037_50370701_233_dialog_content = "Uh, are you sure you weren't just dreaming?",
  ui_story_5037_50370701_234_dialog_content = "Hah? Uh, Fia's here too...?",
  ui_story_5037_50370701_235_dialog_content = "Wait, where'd all that Nightium come from?!",
  ui_story_5037_50370701_236_dialog_content = "I'm definitely dreaming now!",
  ui_story_5037_50370701_237_dialog_content = "Though I must say, this dream feels much nicer than the last one.",
  ui_story_5037_50370701_238_dialog_content = "Uh, Fia? How do we convince Vic that he's not dreaming?",
  ui_story_5037_50370701_239_dialog_content = "Heheheh. Looks like it's Kyllo's time to shine again! Get him!",
  ui_story_5037_50370701_240_dialog_content = "!!!",
  ui_story_5037_50370701_241_dialog_content = "N-Now just hold on a second, Fia! Your master's wide awake now, I swear!",
  ui_story_5037_50370701_242_dialog_content = "Poor Vic. Imagine being that afraid of Kyllo.",
  ui_story_5037_50370701_243_dialog_content = "Hmm, looks like this Nightium is the real deal.",
  ui_story_5037_50370701_244_dialog_content = "Lady Sheol really is a generous person, huh?",
  ui_story_5037_50370701_245_dialog_content = "All we did was participate in her reality show for a few days, and she paid us this much Nightium in return...",
  ui_story_5037_50370701_246_dialog_content = "I wonder how much a real idol makes?",
  ui_story_5037_50370701_247_dialog_content = "Why do you care how much other people make, Fia? We should be satisfied with what we already have, don't you think?",
  ui_story_5037_50370701_248_dialog_content = "Sigh... I guess you're right.",
  ui_story_5037_50370701_249_dialog_content = "It's rare you hear you say something serious for once...",
  ui_story_5037_50370701_250_dialog_content = "Nonsense, I'm always like this! Now, if you'll excuse me, there's a table in a new Umbraton buffet with my name on it!",
  ui_story_5037_50370701_251_dialog_content = "... In your dreams!",
  ui_story_5037_50370701_252_dialog_content = "What? Why not?!",
  ui_story_5037_50370701_253_dialog_content = "For the last few days, I've done nothing but listen to your ridiculous demands!",
  ui_story_5037_50370701_254_dialog_content = "If I'm not training, I'm watching my weight. I can't even remember the last time I had a decent meal!",
  ui_story_5037_50370701_255_dialog_content = "We don't come into this kind of money daily, you know? We should treat ourselves when we have the chance!",
  ui_story_5037_50370701_256_dialog_content = "Looks like you still don't understand our situation very well, Master.",
  ui_story_5037_50370701_257_dialog_content = "This may look like a lot of money at first glance.",
  ui_story_5037_50370701_258_dialog_content = "But once you factor in your Drakolion snacks, our usual food expenses, repairs on the house, and my work wages...",
  ui_story_5037_50370701_259_dialog_content = "That burns through more than half of the money!",
  ui_story_5037_50370701_260_dialog_content = "And when we consider how unreliable you'll be as a source of income...",
  ui_story_5037_50370701_261_dialog_content = "I have no idea how long this money's going to last us!",
  ui_story_5037_50370701_262_dialog_content = "Wait, what do you mean about his income?",
  ui_story_5037_50370701_263_dialog_content = "Vic has so much potential as an idol! Why wouldn't he keep doing it?",
  ui_story_5037_50370701_264_dialog_content = "Spare me, PlayerName.",
  ui_story_5037_50370701_265_dialog_content = "For me to have lasted this many days was nothing short of a miracle, and you want me to do it for the rest of my life?",
  ui_story_5037_50370701_266_dialog_content = "Just thinking about it gives me nightmares.",
  ui_story_5037_50370701_267_dialog_content = "PlayerName is absolutely right, Master!",
  ui_story_5037_50370701_268_dialog_content = "You spend all your time at home instead of looking for work, and you don't even take good care of the wondrous beasts...",
  ui_story_5037_50370701_269_dialog_content = "You might as well make use of yourself as an idol.",
  ui_story_5037_50370701_270_dialog_content = "And who knows? Once the reality show airs, you might have even more fans than before, Master!",
  ui_story_5037_50370701_271_dialog_content = "Oh, my dear, little Fia...",
  ui_story_5037_50370701_272_dialog_content = "Cut your master some slack, will you?!",
  ui_story_5037_50370701_273_dialog_content = "Nope! You're gonna be a big, successful idol, and you're gonna like it!",
  ui_story_5037_50370701_274_dialog_content = "Wha—?!",
  ui_story_5037_50370701_275_dialog_content = "Oh look, we still have enough time to fit in some more training! Let's go, Master!",
  ui_story_5037_50370701_276_dialog_content = "B-But I don't wanna keep training... I'm totally exhausted...",
  ui_story_5037_50370701_277_dialog_content = "Oh, Kyllo? I think our master needs a little motivation.",
  ui_story_5037_50370701_278_dialog_content = "Noooo—!",
  ui_story_5037_50370701_279_dialog_content = "Sigh... I've never seen Master run so fast in my life.",
  ui_story_5037_50370701_280_dialog_content = "So much for being \"totally exhausted,\" huh? Hey! If you have enough energy to run away, then you still have enough energy to train!",
  ui_story_5037_50370701_281_dialog_content = "Vic...",
  ui_story_5037_50370701_282_dialog_content = "Hang in there!",
  ui_story_5037_50370701_283_dialog_content = "\"Best Producer,\" eh...?",
  ui_story_5037_50370701_284_dialog_content = "Heehee... I know I shouldn't let Lady Sheol's award go to my head.",
  ui_story_5037_50370701_285_dialog_content = "Thinking back to the day I first arrived at the Starlit Agency, I really had no idea what I was doing. I worried about making Goldie's life harder than it already was.",
  ui_story_5037_50370701_286_dialog_content = "But I managed to help Goldie with all three of her concerts and even got Lady Sheol to acknowledge me!",
  ui_story_5037_50370701_287_dialog_content = "Man, I can't wait to surprise Vice and Carleen with this.",
  ui_story_5037_50370701_288_dialog_content = "They should be somewhere nearby, right?",
  ui_story_5037_50370701_289_dialog_content = "I wonder if they're in this room?",
  ui_story_5037_50370701_290_dialog_content = "<color=#828282>Knock, knock!</color>",
  ui_story_5037_50370701_291_dialog_content = "Pardon the intrusion!",
  ui_story_5037_50370701_292_dialog_content = "Funny... The lights in this room are usually on. Why is it so dark in here today?",
  ui_story_5037_50370701_293_dialog_content = "Vice? Carleen? Huh, guess they're not here after all.",
  ui_story_5037_50370701_294_dialog_content = "<color=#828282>Slam!</color>",
  ui_story_5037_50370701_295_dialog_content = "Huh?!",
  ui_story_5037_50370701_296_dialog_content = "Surprise!!!",
  ui_story_5037_50370701_297_dialog_content = "Congrats on hosting a perfect graduation concert!",
  ui_story_5037_50370701_298_dialog_content = "And congratulations on completing your missions, PlayerName.",
  ui_story_5037_50370701_299_dialog_content = "Wh-What's all of this...?",
  ui_story_5037_50370701_300_dialog_content = "A selection of the best food and beverages from a new, high-end buffet recently opened in Umbraton.",
  ui_story_5037_50370701_301_dialog_content = "And also—this enormous cake! Looks tasty, huh?",
  ui_story_5037_50370701_302_dialog_content = "Ever since you started training to be a producer, you haven't been eating well.",
  ui_story_5037_50370701_303_dialog_content = "Soooo... We decided to put together a little celebratory feast just for you, PlayerName! See? It has all of your favorites!",
  ui_story_5037_50370701_304_dialog_content = "Vice, Carleen...",
  ui_story_5037_50370701_305_dialog_content = "How long have you two been planning this?",
  ui_story_5037_50370701_306_dialog_content = "I had no idea at all!",
  ui_story_5037_50370701_307_dialog_content = "Heehee! We came up with the idea a while ago, actually.",
  ui_story_5037_50370701_308_dialog_content = "And with how busy you've been today, we had plenty of time to prepare.",
  ui_story_5037_50370701_309_dialog_content = "Does that mean you two know the results of today's concert?",
  ui_story_5037_50370701_310_dialog_content = "Nope! We were hoping you would tell us.",
  ui_story_5037_50370701_311_dialog_content = "Er... What would you do if we lost? Would we still have a reason to celebrate?",
  ui_story_5037_50370701_312_dialog_content = "Vice and I already agreed that no matter what the results were today,",
  ui_story_5037_50370701_313_dialog_content = "all of your hard work is reason enough to celebrate.",
  ui_story_5037_50370701_314_dialog_content = "Not only did you study your heart out, PlayerName. You stuck with it until the very end! That's a huge accomplishment in my eyes!",
  ui_story_5037_50370701_315_dialog_content = "That's why we're gonna party no matter what!",
  ui_story_5037_50370701_316_dialog_content = "Y-You guys... Arrrgh, why do you have to be so nice?!",
  ui_story_5037_50370701_317_dialog_content = "See? Now I have something in my eye, thanks to you!",
  ui_story_5037_50370701_318_dialog_content = "So anyways, who won today?",
  ui_story_5037_50370701_319_dialog_content = "I thought you said it didn't matter?!",
  ui_story_5037_50370701_320_dialog_content = "Hahaha! That's because we trust you, PlayerName!",
  ui_story_5037_50370701_321_dialog_content = "Besides, you were muttering something about something you wanted to tell us when you were outside. So what is it?",
  ui_story_5037_50370701_322_dialog_content = "Heheheh. Guess what? Goldie and I won today!",
  ui_story_5037_50370701_323_dialog_content = "And not only that, Lady Sheol gave me the Best Producer award!",
  ui_story_5037_50370701_324_dialog_content = "Wow! I had no idea they even had an award for that!",
  ui_story_5037_50370701_325_dialog_content = "It appears Lady Sheol has quite a discerning eye. I don't think your incredible progress was lost on her at all, PlayerName.",
  ui_story_5037_50370701_326_dialog_content = "So did the award come with any prize money? Huh? Huh?!",
  ui_story_5037_50370701_327_dialog_content = "I, uh... Don't think so.",
  ui_story_5037_50370701_328_dialog_content = "Heheheh, that makes sense. After all, no amount of money could compare to the honor of getting that award, right?",
  ui_story_5037_50370701_329_dialog_content = "Agreed. You should have a much easier time finding work in the future with it.",
  ui_story_5037_50370701_330_dialog_content = "That's right! You're basically on the same level as any other professional producer now!",
  ui_story_5037_50370701_331_dialog_content = "But if it wasn't for you guys helping me the whole time, I never would've had the confidence to make it this far.",
  ui_story_5037_50370701_332_dialog_content = "Carleen, Vice, thank you both for always being at my side and teaching me so much these last few days.",
  ui_story_5037_50370701_333_dialog_content = "Don't mention it! There's just one little thing wrong with your statement, though.",
  ui_story_5037_50370701_334_dialog_content = "Huh?",
  ui_story_5037_50370701_335_dialog_content = "We haven't just been helping you for the last few days, right?",
  ui_story_5037_50370701_336_dialog_content = "She's right. We've been together all this time, haven't we?",
  ui_story_5037_50370701_337_dialog_content = "Yeah, you're right.",
  ui_story_5037_50370701_338_dialog_content = "Let me try again!",
  ui_story_5037_50370701_339_dialog_content = "Oh, just relax, will you? We're all friends here, so there's no need to be so formal!",
  ui_story_5037_50370701_340_dialog_content = "Anyway, guess what?",
  ui_story_5037_50370701_341_dialog_content = "On my last trip back to Illumina, I noticed that the entire region had gotten into idols!",
  ui_story_5037_50370701_342_dialog_content = "I think Officer Vivian is even planning some sort of big event to choose a group of idols to represent the entire Illumina Federation!",
  ui_story_5037_50370701_343_dialog_content = "What? Illumina idols?!",
  ui_story_5037_50370701_344_dialog_content = "Let us roar and liven up the show!",
  ui_story_5037_50370701_345_dialog_content = "Hmm? What's with the awfully silent crowd?",
  ui_story_5037_50370701_346_dialog_content = "Were you all so flabbergasted by my spectacular performance that you forgot to clap?",
  ui_story_5037_50370701_347_dialog_content = "Hahahahahahahaha!",
  ui_story_5037_50370701_348_dialog_content = "*Inhale*",
  ui_story_5037_50370701_349_dialog_content = "Hmm? Is something wrong, PlayerName? You look a little pale.",
  ui_story_5037_50370701_350_dialog_content = "I-It's nothing!",
  ui_story_5037_50370701_351_dialog_content = "I'm sure the search for Illumina's top idol will be an unforgettable experience!",
  ui_story_5037_50370701_352_dialog_content = "These idol contests are indeed worthy of serious consideration. Perhaps I should suggest a similar event for Lumopolis to my father?",
  ui_story_5037_50370701_353_dialog_content = "Er, do you think the nobles of Lumopolis would agree to this kind of thing?",
  ui_story_5037_50370701_354_dialog_content = "I suspect it won't be easy.",
  ui_story_5037_50370701_355_dialog_content = "But there's no denying the wealth of knowledge I gained from this experience.",
  ui_story_5037_50370701_356_dialog_content = "In fact, I believe I finally see the true value of displaying one's charm for the world to see.",
  ui_story_5037_50370701_357_dialog_content = "Oddly enough, it feels as though a weight has suddenly been lifted from my shoulders.",
  ui_story_5037_50370701_358_dialog_content = "Oh, I get it!",
  ui_story_5037_50370701_359_dialog_content = "I think you've gotten one step closer on your journey to succeeding your father, Carleen!",
  ui_story_5037_50370701_360_dialog_content = "You really think this has anything to do with that?",
  ui_story_5037_50370701_361_dialog_content = "It does if you really think about it.",
  ui_story_5037_50370701_362_dialog_content = "How so?",
  ui_story_5037_50370701_363_dialog_content = "The food's starting to get cold! Let's dig in!",
  ui_story_5037_50370701_364_dialog_content = "You are right. Let's celebrate our victory while the food is still warm.",
  ui_story_5037_50370701_365_dialog_content = "To PlayerName, the Best Producer!",
  ui_story_5037_50370701_366_dialog_content = "Cheers!",
  ui_story_5037_50370701_367_option_content = "Cheers!",
  ui_story_5037_50370801_1_dialog_content = "Choreography training, vocal exercises, a Q&A session, contacting the owner of the venue for the fan meet...",
  ui_story_5037_50370801_2_dialog_content = "?",
  ui_story_5037_50370801_3_dialog_content = "I should reach out to the owner sometime between lunch and dinner, but the reporter will be here this afternoon...",
  ui_story_5037_50370801_4_dialog_content = "...",
  ui_story_5037_50370801_5_dialog_content = "I also need to set aside enough time for Goldie to rest, as well as to change and do her makeup. With all of this happening in one day...",
  ui_story_5037_50370801_6_dialog_content = "...?",
  ui_story_5037_50370801_7_dialog_content = "I'll have to spend the entire day working again!",
  ui_story_5037_50370801_8_dialog_content = "PlayerName?",
  ui_story_5037_50370801_9_dialog_content = "Bwaaaa!!!",
  ui_story_5037_50370801_10_dialog_content = "Oh, it's just you, Goldie. My heart nearly jumped out of my chest just now.",
  ui_story_5037_50370801_11_dialog_content = "Can I ask what you're mumbling about over here?",
  ui_story_5037_50370801_12_dialog_content = "Actually, it looks like you're pretty low on energy. Wanna go practice some dance moves with me to get your spirits up?",
  ui_story_5037_50370801_13_dialog_content = "A little exercise can go a long way when it comes to staying healthy!",
  ui_story_5037_50370801_14_dialog_content = "A healthy producer is essential to an idol's success, after all! How else will you keep up with all of my concerts and events?",
  ui_story_5037_50370801_15_dialog_content = "Yeah, but I'm still planning out the schedule...",
  ui_story_5037_50370801_16_dialog_content = "There's so much to do every day that as soon as I'm done with one thing, I'm already late for the next...",
  ui_story_5037_50370801_17_dialog_content = "Even trying to fit in a few minutes of rest is nearly impossible now!",
  ui_story_5037_50370801_18_dialog_content = "I guess I'm really not that great of a producer, after all...",
  ui_story_5037_50370801_19_dialog_content = "No way! You're a fantastic producer!",
  ui_story_5037_50370801_20_dialog_content = "You've only been one for a few days, yet you're completely familiar with the daily requirements of the job! That's not something just anyone can do, you know!",
  ui_story_5037_50370801_21_dialog_content = "So don't be too hard on yourself, okay? Here, wanna pet Marshmallow?",
  ui_story_5037_50370801_22_dialog_content = "I always feel better after petting its soft, fluffy fur!",
  ui_story_5037_50370801_23_dialog_content = "Woof!",
  ui_story_5037_50370801_24_dialog_content = "Sure, why not—",
  ui_story_5037_50370801_25_dialog_content = "Wait!",
  ui_story_5037_50370801_26_dialog_content = "What's wrong?",
  ui_story_5037_50370801_27_dialog_content = "I forgot to call the newspaper about tomorrow's interview! I still haven't set up a time for it!",
  ui_story_5037_50370801_28_dialog_content = "Sorry, Goldie! I've gotta head off!",
  ui_story_5037_50370801_29_dialog_content = "...",
  ui_story_5037_50370801_30_dialog_content = "<color=#828282>A moment later</color>",
  ui_story_5037_50370801_31_dialog_content = "Phew... Thank goodness I made it in time.",
  ui_story_5037_50370801_32_dialog_content = "They're one of the biggest newspapers around. If I had left them hanging, it would've hurt Goldie's reputation.",
  ui_story_5037_50370801_33_dialog_content = "Welcome back, PlayerName!",
  ui_story_5037_50370801_34_dialog_content = "Oh, hi, Goldie! Sorry, I was in such a hurry that I forgot to say goodbye...",
  ui_story_5037_50370801_35_dialog_content = "That's okay. I know it's because you've been so busy with work lately.",
  ui_story_5037_50370801_36_dialog_content = "Being a producer can be pretty tough. Even though I've been slowly adapting to the work over the last few days,",
  ui_story_5037_50370801_37_dialog_content = "the job is still really demanding!",
  ui_story_5037_50370801_38_dialog_content = "If all I had to do was plan out schedules, it wouldn't be hard at all.",
  ui_story_5037_50370801_39_dialog_content = "But on top of all the planning, I have to fight off the paparazzi at every turn, and think of the right things to say every time...",
  ui_story_5037_50370801_40_dialog_content = "It's exhausting...",
  ui_story_5037_50370801_41_dialog_content = "I know it's a hard job.",
  ui_story_5037_50370801_42_dialog_content = "But no matter how tired you get, you always find a way to get the job done, PlayerName!",
  ui_story_5037_50370801_43_dialog_content = "That's what I find so incredible about you!",
  ui_story_5037_50370801_44_dialog_content = "Thanks, Goldie! Just hearing you say that makes me feel a lot less exhausted!",
  ui_story_5037_50370801_45_dialog_content = "See? Everyone needs encouragement from time to time, no matter who they are!",
  ui_story_5037_50370801_46_dialog_content = "Now that you mention it... Did you handle all of this by yourself before, Goldie?",
  ui_story_5037_50370801_47_dialog_content = "Not just being an idol, but being your own producer, as well...",
  ui_story_5037_50370801_48_dialog_content = "Training, planning, avoiding the paparazzi...",
  ui_story_5037_50370801_49_option_content = "You must be pretty amazing to have done all of that on your own!",
  ui_story_5037_50370801_50_dialog_content = "Haha... It was nothing, really.",
  ui_story_5037_50370801_51_option_content = "Handling everything on your own must've been hard...",
  ui_story_5037_50370801_52_dialog_content = "It was, but I made it through in the end.",
  ui_story_5037_50370801_53_dialog_content = "Even for someone like me, handling two completely different jobs wasn't easy.",
  ui_story_5037_50370801_54_dialog_content = "I ran into all kinds of obstacles in the past. There were even times when I wanted to give up and quit.",
  ui_story_5037_50370801_55_dialog_content = "You actually felt like quitting before? I can't even imagine that.",
  ui_story_5037_50370801_56_dialog_content = "It's one of my biggest secrets, so don't go around telling other people!",
  ui_story_5037_50370801_57_dialog_content = "I wouldn't dream of it! As your producer, I would never say or do anything to hurt you or your reputation!",
  ui_story_5037_50370801_58_dialog_content = "Heehee! Glad to hear it!",
  ui_story_5037_50370801_59_dialog_content = "But to answer your question... Yes, I had to handle all of the work on my own when I first became an idol.",
  ui_story_5037_50370801_60_dialog_content = "Training, planning, and avoiding the paparazzi... all of it.",
  ui_story_5037_50370801_61_dialog_content = "Back then, I only got about one or two hours of sleep every day!",
  ui_story_5037_50370801_62_dialog_content = "I had to wake up early every morning just to make up for any training I missed the day before.",
  ui_story_5037_50370801_63_dialog_content = "That's insane!",
  ui_story_5037_50370801_64_dialog_content = "I'm used to staying up late, but only one to two hours of sleep? I wouldn't even be able to roll out of bed the next day, much less do that every single day...",
  ui_story_5037_50370801_65_dialog_content = "That was basically me.",
  ui_story_5037_50370801_66_dialog_content = "One or two days is manageable for most people, but for several years? Forever?",
  ui_story_5037_50370801_67_dialog_content = "Every time I finished my training, I'd lie in my bed and my exhausted mind would think of an endless future of that kind of lifestyle.",
  ui_story_5037_50370801_68_dialog_content = "But in the end, you were able to fight through the tough times and become the famous idol you are today!",
  ui_story_5037_50370801_69_dialog_content = "That's right!",
  ui_story_5037_50370801_70_dialog_content = "Whenever I feel like giving up, I toss my lucky bullet in the air. If it lands pointing down, then it means something good is going to happen!",
  ui_story_5037_50370801_71_dialog_content = "Back then, my lucky bullet always pointed down, so I knew that if I just kept going... I would become the idol I always dreamed of becoming!",
  ui_story_5037_50370801_72_dialog_content = "You really have an indomitable spirit...",
  ui_story_5037_50370801_73_dialog_content = "Heehee!",
  ui_story_5037_50370801_74_dialog_content = "But things are a little different now, you know?",
  ui_story_5037_50370801_75_dialog_content = "I have you with me. The best producer I could ever ask for!",
  ui_story_5037_50370801_76_dialog_content = "Thanks to you, I can focus on my training without worrying about other things!",
  ui_story_5037_50370801_77_dialog_content = "My progress has never been faster!",
  ui_story_5037_50370801_78_dialog_content = "H-Have I... really been that helpful?",
  ui_story_5037_50370801_79_dialog_content = "Oh, absolutely!",
  ui_story_5037_50370801_80_dialog_content = "I'm glad to hear it!",
  ui_story_5037_50370801_81_dialog_content = "I felt so useless before... As if I was only making more problems for you.",
  ui_story_5037_50370801_82_dialog_content = "But hearing you say that makes me feel a lot more confident.",
  ui_story_5037_50370801_83_dialog_content = "As your producer, I'll keep doing my best for you, Goldie! Just leave it to me!",
  ui_story_5037_50370801_84_dialog_content = "I'll hold you to it!",
  ui_story_5037_50370901_1_dialog_content = "<color=#828282>After morning training</color>",
  ui_story_5037_50370901_2_dialog_content = "Thanks again for your help, PlayerName!",
  ui_story_5037_50370901_3_dialog_content = "I'm finished with my morning training, so now I have time to get some rest.",
  ui_story_5037_50370901_4_dialog_content = "Don't mention it, Goldie. Enjoy your break!",
  ui_story_5037_50370901_5_dialog_content = "<color=#828282>Knock, knock!</color>",
  ui_story_5037_50370901_6_dialog_content = "Come in!",
  ui_story_5037_50370901_7_dialog_content = "PlayerName! Oh, and Goldie too!",
  ui_story_5037_50370901_8_dialog_content = "Hi, Gronru!",
  ui_story_5037_50370901_9_dialog_content = "Gronru? What are you doing here?",
  ui_story_5037_50370901_10_dialog_content = "Oh, just buying some materials, that's all. I hear you're a big-shot producer in Umbraton now, so I thought I'd stop by and check things out!",
  ui_story_5037_50370901_11_dialog_content = "I also brought the latest game I designed! What do you say? Care to play a few rounds?",
  ui_story_5037_50370901_12_dialog_content = "Of course I—",
  ui_story_5037_50370901_13_dialog_content = "Er, I mean... Not right now, sorry.",
  ui_story_5037_50370901_14_dialog_content = "Huh? You don't wanna challenge me today? I gotta say, that's not like you at all...",
  ui_story_5037_50370901_15_dialog_content = "Because I still have a lot of work to do this afternoon. It's easy for me to lose track of time when I play video games...",
  ui_story_5037_50370901_16_dialog_content = "You have a point, yeah.... Oh well, maybe next time! I won't bother you guys anymore.",
  ui_story_5037_50370901_17_dialog_content = "Keep up the good work, PlayerName! You too, Goldie!",
  ui_story_5037_50370901_18_dialog_content = "I'm looking forward to your concert!",
  ui_story_5037_50370901_19_dialog_content = "Thanks! Hope to see you there, too!",
  ui_story_5037_50370901_20_dialog_content = "Bye-bye!",
  ui_story_5037_50370901_21_dialog_content = "See you!",
  ui_story_5037_50370901_22_dialog_content = "Alright, time to get ready for this afternoon's tasks...",
  ui_story_5037_50370901_23_dialog_content = "Wait, it's break time right now, isn't it? It's better to get rested, so you have the energy to do the rest of the day's work.",
  ui_story_5037_50370901_24_dialog_content = "I know, I know... But the concert is right around the corner.",
  ui_story_5037_50370901_25_dialog_content = "We're running out of time, but the work just keeps piling up. Sometimes, there's no choice but to give up a little bit of our free time...",
  ui_story_5037_50370901_26_dialog_content = "... Have you been using your breaks to work on the concert these last few days?",
  ui_story_5037_50370901_27_dialog_content = "Uh... K-Kind of...?",
  ui_story_5037_50370901_28_dialog_content = "That won't do!",
  ui_story_5037_50370901_29_dialog_content = "Without proper rest, your work quality will only suffer! You won't be able to get anything done at this rate!",
  ui_story_5037_50370901_30_dialog_content = "To make up for all the breaks you spent working, you're going to take the whole afternoon off!",
  ui_story_5037_50370901_31_dialog_content = "Go take a walk, get some fresh air, and don't come back until you're nice and rested!",
  ui_story_5037_50370901_32_dialog_content = "Th-That's really not necessary...",
  ui_story_5037_50370901_33_dialog_content = "I won't accept no for an answer! This concerns both your health and your work efficiency.",
  ui_story_5037_50370901_34_dialog_content = "B-But if I'm your producer, what will you do if I'm not around?",
  ui_story_5037_50370901_35_dialog_content = "You don't need to worry about that. I told you, I was my own producer for the longest time. This isn't a big deal.",
  ui_story_5037_50370901_36_dialog_content = "Now get some rest, and don't return to the office until tomorrow morning!",
  ui_story_5037_50370901_37_dialog_content = "<color=#828282>Slam!</color>",
  ui_story_5037_50370901_38_dialog_content = "(She just shoved me out the door...)",
  ui_story_5037_50370901_39_dialog_content = "(Hmm... Guess I'll go for a walk then.)",
  ui_story_5037_50370901_40_dialog_content = "<color=#828282>A few minutes later at a cafe</color>",
  ui_story_5037_50370901_41_dialog_content = "What can I get you?",
  ui_story_5037_50370901_42_dialog_content = "Let me take a look at the menu...",
  ui_story_5037_50370901_43_dialog_content = "\"Tri-colored Cake\"?",
  ui_story_5037_50370901_44_dialog_content = "Our mission is to hold three concerts within a certain period of time.",
  ui_story_5037_50370901_45_dialog_content = "We still have two more concerts to go...",
  ui_story_5037_50370901_46_dialog_content = "Why am I suddenly thinking about that?! Back to the menu!",
  ui_story_5037_50370901_47_dialog_content = "Let's see... Twin Cakes?",
  ui_story_5037_50370901_48_dialog_content = "After the shows start, the audience can follow their preferences and move freely between the stages.",
  ui_story_5037_50370901_49_dialog_content = "In the end, whichever stage manages to gain a larger crowd will be declared the winner.",
  ui_story_5037_50370901_50_dialog_content = "Sigh... I wonder what we can do to keep people's attention?",
  ui_story_5037_50370901_51_dialog_content = "Is Kyllo really that potent of a motivator?",
  ui_story_5037_50370901_52_dialog_content = "Should I find my own Kyllo to bite my ankle?",
  ui_story_5037_50370901_53_dialog_content = "Why can't I stop worrying?!",
  ui_story_5037_50370901_54_dialog_content = "Sorry, I think I still need more time to look at the menu.",
  ui_story_5037_50370901_55_dialog_content = "Not a problem. Just call me when you're ready.",
  ui_story_5037_50370901_56_dialog_content = "Even though I'm not at work, I can't stop thinking about the evaluation concert. It's just a few days away...",
  ui_story_5037_50370901_57_dialog_content = "I haven't planned out Goldie's schedule for tomorrow, either. I can't help but feel uneasy whenever I think about it...",
  ui_story_5037_50370901_58_dialog_content = "Sigh... Coffee and cake just don't taste as good when I'm this stressed out.",
  ui_story_5037_50370901_59_dialog_content = "I wonder how Goldie's training is going...?",
  ui_story_5037_50370901_60_dialog_content = "It's fine if I take a peek to ensure she's alright. Right?",
  ui_story_5037_50370901_61_dialog_content = "<color=#828282>Outside the agency</color>",
  ui_story_5037_50370901_62_dialog_content = "This should be the rehearsal room. I should be able to look inside through the window.",
  ui_story_5037_50370901_63_dialog_content = "I can see Goldie... But that person next to her...",
  ui_story_5037_50370901_64_dialog_content = "Hello, Goldie? I'm with the Daily Drivel, the source of the hottest gossip in all of Umbraton!",
  ui_story_5037_50370901_65_dialog_content = "I noticed that you slammed the door on your producer earlier today.",
  ui_story_5037_50370901_66_dialog_content = "Word on the street is you were never on good terms with him, and that you fired him on the spot! Is that true?",
  ui_story_5037_50370901_67_dialog_content = "PlayerName and I are on the best of terms, thank you very much. We have always been very good friends.",
  ui_story_5037_50370901_68_dialog_content = "Then how do you explain the scene from before?",
  ui_story_5037_50370901_69_dialog_content = "Throwing out your producer and leaving him standing around on the street... I've never seen such a pitiful sight!",
  ui_story_5037_50370901_70_dialog_content = "That was because—",
  ui_story_5037_50370901_71_dialog_content = "Crap... It's that obnoxious paparazzi from before!",
  ui_story_5037_50370901_72_dialog_content = "Goldie's never met or dealt with him before... If he's not stopped, he's going to make stuff up again!",
  ui_story_5037_50370901_73_dialog_content = "I have to help her!",
  ui_story_5037_50370901_74_dialog_content = "What a sad, little producer... Thrown out into the cold world like an unwanted dog, without so much as a—",
  ui_story_5037_50370901_75_dialog_content = "Hey! What's going on here?",
  ui_story_5037_50370901_76_dialog_content = "PlayerName?!",
  ui_story_5037_50370901_77_dialog_content = "I-It's you!",
  ui_story_5037_50370901_78_dialog_content = "Did I hear you say something about Goldie and I not getting along?",
  ui_story_5037_50370901_79_option_content = "Strongly deny the rumors",
  ui_story_5037_50370901_80_dialog_content = "That's ridiculous! Goldie and I are the best possible professional duo ever.",
  ui_story_5037_50370901_81_option_content = "Patiently explain the situation",
  ui_story_5037_50370901_82_dialog_content = "Our relationship is perfectly fine. We work really well together, in fact.",
  ui_story_5037_50370901_83_dialog_content = "*Scoffs*",
  ui_story_5037_50370901_84_dialog_content = "It's true!",
  ui_story_5037_50370901_85_dialog_content = "And don't even think about twisting our words around, or else...",
  ui_story_5037_50370901_86_dialog_content = "Okay, okay!",
  ui_story_5037_50370901_87_dialog_content = "Sorry, but I should get going!",
  ui_story_5037_50370901_88_dialog_content = "Whew... Thank goodness you came back, PlayerName.",
  ui_story_5037_50370901_89_dialog_content = "Otherwise, I don't know what I would've resorted to to make that guy go away.",
  ui_story_5037_50370901_90_dialog_content = "I never knew paparazzi could be this dedicated to their work...",
  ui_story_5037_50370901_91_dialog_content = "He swooped down practically the minute I left.",
  ui_story_5037_50370901_92_dialog_content = "That reminds me... Aren't you supposed to be on leave?",
  ui_story_5037_50370901_93_dialog_content = "What are you doing back at the office?",
  ui_story_5037_50370901_94_dialog_content = "I, uh... Well, because...",
  ui_story_5037_50370901_95_dialog_content = "Sigh. Look, I know you told me to get some rest, but I just can't do it right now.",
  ui_story_5037_50370901_96_dialog_content = "To tell you the truth... I can't stop worrying about the evaluation concert.",
  ui_story_5037_50370901_97_dialog_content = "As soon as I start to think about it, I lose my appetite, and I can't get any rest.",
  ui_story_5037_50370901_98_dialog_content = "I see...",
  ui_story_5037_50370901_99_dialog_content = "Yeah... That's why I just want to get things over with, you know? I don't think I'll be able to rest properly until the concert's over.",
  ui_story_5037_50370901_100_dialog_content = "Hmm...",
  ui_story_5037_50370901_101_dialog_content = "To be honest, I feel the same way.",
  ui_story_5037_50370901_102_dialog_content = "I used to be perfectly capable of dealing with these gossipy reporters... Nothing they said or wrote truly bothered me before.",
  ui_story_5037_50370901_103_dialog_content = "But ever since we started working together... I've been relying on you more and more to handle things like this.",
  ui_story_5037_50370901_104_dialog_content = "Now I can tell that I've gotten a little rusty when it comes to telling those guys off.",
  ui_story_5037_50370901_105_dialog_content = "Am I making you lose your edge?",
  ui_story_5037_50370901_106_dialog_content = "No way! If anything, seeing you show up just now made me feel stronger, PlayerName!",
  ui_story_5037_50370901_107_dialog_content = "Ever since you became my producer, I've been able to dedicate myself to training, improving all my skills by a whole bunch.",
  ui_story_5037_50370901_108_dialog_content = "I'm not the same Goldie that I used to be. I'm a new-and-improved Super Goldie!",
  ui_story_5037_50370901_109_dialog_content = "Hahahaha! Well, I'm relieved you don't think I'm holding you back.",
  ui_story_5037_50370901_110_dialog_content = "A fantastic producer like you could never do something like that, PlayerName!",
  ui_story_5037_50370901_111_dialog_content = "But when it comes to getting rest...",
  ui_story_5037_50370901_112_dialog_content = "You don't have to worry about me anymore, Goldie. I know we're super busy right now, but I promise I'll get the right amount of rest and exercise from now on!",
  ui_story_5037_50370901_113_dialog_content = "Then I'll also be sure to follow all your decisions as well.",
  ui_story_5037_50370901_114_dialog_content = "I believe in you!",
  ui_story_5037_50371001_1_dialog_content = "The evaluation concert is finally over!",
  ui_story_5037_50371001_2_dialog_content = "We finally cleared our biggest challenge! Thank goodness.",
  ui_story_5037_50371001_3_dialog_content = "As soon as I have a moment to relax, I suddenly start feeling so fatigued...",
  ui_story_5037_50371001_4_dialog_content = "Then you should celebrate by getting plenty of rest today!",
  ui_story_5037_50371001_5_dialog_content = "Yeah, it's about time.",
  ui_story_5037_50371001_6_dialog_content = "So... what should we do?",
  ui_story_5037_50371001_7_dialog_content = "Wait, I got it! Wanna hear me sing?",
  ui_story_5037_50371001_8_dialog_content = "I'm preparing a brand-new song for the graduation concert!",
  ui_story_5037_50371001_9_dialog_content = "It's still missing a few parts, but the rest of the song is already finished.",
  ui_story_5037_50371001_10_dialog_content = "Sure! I bet it already sounds amazing!",
  ui_story_5037_50371001_11_dialog_content = "Then without further ado...",
  ui_story_5037_50371001_12_dialog_content = "♪ Though we must go our separate ways, I know we'll be fine ♪",
  ui_story_5037_50371001_13_dialog_content = "♪ A thousand miles apart, yet our star will always shine ♪",
  ui_story_5037_50371001_14_dialog_content = "♪ So please don't cry; our future still lies ahead ♪",
  ui_story_5037_50371001_15_dialog_content = "♪ Through this song, I say goodbye, though I know we'll meet again ♪",
  ui_story_5037_50371001_16_dialog_content = "(Incredible...)",
  ui_story_5037_50371001_17_dialog_content = "(But this time, the lyrics mention saying farewell... And the melody sounds softer than her previous songs.)",
  ui_story_5037_50371001_18_dialog_content = "Well, PlayerName? What do you think?",
  ui_story_5037_50371001_19_option_content = "It was beautiful!",
  ui_story_5037_50371001_20_dialog_content = "Why, thank you!",
  ui_story_5037_50371001_21_option_content = "It's different from your previous songs.",
  ui_story_5037_50371001_22_dialog_content = "Ah, so you noticed.",
  ui_story_5037_50371001_23_dialog_content = "It's a song for the graduation concert, after all... So naturally, I wrote it with all of the gratitude in my heart!",
  ui_story_5037_50371001_24_dialog_content = "But it feels as though there's more to it than just gratitude.",
  ui_story_5037_50371001_25_dialog_content = "It sounds kind of sad, and wistful... I don't know.",
  ui_story_5037_50371001_26_dialog_content = "Because it's a farewell song.",
  ui_story_5037_50371001_27_dialog_content = "But who are you saying farewell to, Goldie?",
  ui_story_5037_50371001_28_dialog_content = "There's something I still don't understand... What exactly is a graduation concert?",
  ui_story_5037_50371001_29_dialog_content = "Graduation concerts are held for idols that are resigning and leaving.",
  ui_story_5037_50371001_30_dialog_content = "It's a chance for the idol to bid farewell to their fans.",
  ui_story_5037_50371001_31_dialog_content = "Wha—?!",
  ui_story_5037_50371001_32_dialog_content = "Are you not going to be an idol anymore after this concert???",
  ui_story_5037_50371001_33_dialog_content = "What are you talking about? I still have plenty of years of being an idol in me.",
  ui_story_5037_50371001_34_dialog_content = "This concert's just for a promotional video! My real graduation concert won't be for a long, long time!",
  ui_story_5037_50371001_35_dialog_content = "Also... As my producer, I wanted you to experience what it's like to work with an idol until the very end of her career!",
  ui_story_5037_50371001_36_dialog_content = "I still plan on being an idol afterwards, silly!",
  ui_story_5037_50371001_37_dialog_content = "You scared the crap out of me...",
  ui_story_5037_50371001_38_dialog_content = "For a second, I thought you were finished with being an idol.",
  ui_story_5037_50371001_39_dialog_content = "Of course not!",
  ui_story_5037_50371001_40_dialog_content = "For me, this next concert is just the conclusion of one chapter in my career.",
  ui_story_5037_50371001_41_dialog_content = "It'll serve as closure for all of the time we spent together, and all of the hardships and victories we shared!",
  ui_story_5037_50371001_42_dialog_content = "I see.",
  ui_story_5037_50371001_43_dialog_content = "Honestly, I can't picture you doing anything else in life...",
  ui_story_5037_50371001_44_dialog_content = "In my mind, you're the epitome of an idol.",
  ui_story_5037_50371001_45_dialog_content = "I can't tell you how much that means to me!",
  ui_story_5037_50371001_46_dialog_content = "If that's the impression I give you, then it means I'm doing my job right!",
  ui_story_5037_50371001_47_dialog_content = "But at the end of the day... I'm just an ordinary person, like everyone else.",
  ui_story_5037_50371001_48_dialog_content = "Someday, I'll have to hold a real graduation concert, and say good-bye to my fans.",
  ui_story_5037_50371001_49_dialog_content = "Let's talk about something less depressing...",
  ui_story_5037_50371001_50_dialog_content = "Is it? I don't really think so.",
  ui_story_5037_50371001_51_dialog_content = "No?",
  ui_story_5037_50371001_52_dialog_content = "Graduation is just another part of an idol's life, and it inevitably comes to all of us whether we welcome it or not.",
  ui_story_5037_50371001_53_dialog_content = "Rather than try to avoid it, I want to do everything I can to make sure my own graduation concert is the best one ever!",
  ui_story_5037_50371001_54_dialog_content = "Whatever happens, I don't want to have any regrets, for me or my fans.",
  ui_story_5037_50371001_55_dialog_content = "Whatever happens, I want to make sure I shine bright in their hearts for the rest of their lives.",
  ui_story_5037_50371001_56_dialog_content = "That's why I'm going to keep doing my best until graduation day comes!",
  ui_story_5037_50371001_57_dialog_content = "That sounds very much like you!",
  ui_story_5037_50371001_58_dialog_content = "So, once it's time to stop being an idol... What will you do then?",
  ui_story_5037_50371001_59_dialog_content = "Hmm... I haven't really decided yet!",
  ui_story_5037_50371001_60_dialog_content = "I have lots of ideas, but right now... My favorite is to open up my very own pet cafe!",
  ui_story_5037_50371001_61_dialog_content = "That way, I can work and keep Marshmallow company all at the same time!",
  ui_story_5037_50371001_62_dialog_content = "That sounds like a great idea!",
  ui_story_5037_50371001_63_dialog_content = "Drinking coffee and playing with cute, little animals... sounds like the dream.",
  ui_story_5037_50371001_64_dialog_content = "I'm right there with you!",
  ui_story_5037_50371001_65_dialog_content = "Whenever I'm feeling tired, petting Marshmallow's soft, fluffy fur always helps me relax.",
  ui_story_5037_50371001_66_dialog_content = "As an idol, my job is to cheer everyone up with the power of song and dance.",
  ui_story_5037_50371001_67_dialog_content = "A pet cafe would help me keep bringing joy to everyone's lives after I retire!",
  ui_story_5037_50371001_68_dialog_content = "Whatever happens in life, I know I'll be okay with it.",
  ui_story_5037_50371101_1_dialog_content = "(I found a letter from Vic in the office today. It was addressed to me.)",
  ui_story_5037_50371101_2_dialog_content = "(It said to wait for him in the dance hall later today... That he wanted to ask me about some things in private.)",
  ui_story_5037_50371101_3_dialog_content = "You came!",
  ui_story_5037_50371101_4_dialog_content = "Hm? Is that you, Fia?",
  ui_story_5037_50371101_5_dialog_content = "Ow, ow, ow... Slow down, Fia! You're gonna tear your poor master's ear off!",
  ui_story_5037_50371101_6_dialog_content = "What are you guys doing here?",
  ui_story_5037_50371101_7_dialog_content = "I told you there was no reason to bother with this, Fia!",
  ui_story_5037_50371101_8_dialog_content = "Even if PlayerName is our friend, he still needs to set things straight!",
  ui_story_5037_50371101_9_dialog_content = "...Would someone please explain what's going on?",
  ui_story_5037_50371101_10_dialog_content = "Alright, let me just be straightforward. What's the deal with that paparazzi that's been running around here every day?",
  ui_story_5037_50371101_11_dialog_content = "Paparazzi?",
  ui_story_5037_50371101_12_dialog_content = "Oh, you mean that sketchy-looking guy with a beard?",
  ui_story_5037_50371101_13_dialog_content = "Yeah, that's the one! So you do know him!",
  ui_story_5037_50371101_14_dialog_content = "That jerk keeps barging in and interrupting my good-for-nothing Master's training!",
  ui_story_5037_50371101_15_dialog_content = "What's worse is that every time I throw him out... The next day, he puts out a mean article that slanders Master and praises Goldie instead!",
  ui_story_5037_50371101_16_dialog_content = "Tell the truth! Is he working for you guys?",
  ui_story_5037_50371101_17_dialog_content = "... You honestly think I would do something like that?",
  ui_story_5037_50371101_18_dialog_content = "We get harassed by him every day too!",
  ui_story_5037_50371101_19_dialog_content = "Really?",
  ui_story_5037_50371101_20_dialog_content = "See? I told you it wasn't them!",
  ui_story_5037_50371101_21_dialog_content = "The same newspaper that slandered me has also done the same to Goldie in the past.",
  ui_story_5037_50371101_22_dialog_content = "R-Really?",
  ui_story_5037_50371101_23_dialog_content = "I guess I've only been reading the stuff about my good-for-nothing Master...",
  ui_story_5037_50371101_24_dialog_content = "Now that you mention it, though... I think I recall seeing slanderous articles about Vic, too.",
  ui_story_5037_50371101_25_dialog_content = "But if you guys didn't send him here, who did?",
  ui_story_5037_50371101_26_dialog_content = "I think he keeps coming back because he thinks this place is full of gossip to write about.",
  ui_story_5037_50371101_27_dialog_content = "Even though I make sure to lock the door up every day before I leave, he always manages to worm his way inside...",
  ui_story_5037_50371101_28_dialog_content = "I swear, there's just no getting rid of him!",
  ui_story_5037_50371101_29_dialog_content = "I know, huh! He's costing us a lot of fans, too!",
  ui_story_5037_50371101_30_dialog_content = "So I guess this was all just a misunderstanding...",
  ui_story_5037_50371101_31_dialog_content = "Sorry for suspecting you.",
  ui_story_5037_50371101_32_dialog_content = "Don't worry about it, Fia. Do you guys need anything else?",
  ui_story_5037_50371101_33_dialog_content = "Nope! Master still has lots of training to do, so we'll see you later!",
  ui_story_5037_50371101_34_dialog_content = "Let's all do our best, okay?",
  ui_story_5037_50371101_35_dialog_content = "Sure, then—",
  ui_story_5037_50371101_36_dialog_content = "<size=45>Wait!</size>",
  ui_story_5037_50371101_37_dialog_content = "Huh? What now?",
  ui_story_5037_50371101_38_dialog_content = "I have a small request, PlayerName.",
  ui_story_5037_50371101_39_dialog_content = "Y-Yeah...?",
  ui_story_5037_50371101_40_dialog_content = "Could you... Could you teach me how to deal with the paparazzi? I'm begging you!",
  ui_story_5037_50371101_41_dialog_content = "Hah?! M-Mind my personal space!",
  ui_story_5037_50371101_42_dialog_content = "Quit using my headband to wipe your tears!!",
  ui_story_5037_50371101_43_dialog_content = "*Sniff* Okay...",
  ui_story_5037_50371101_44_dialog_content = "Thanks to that stupid reporter, and all of his lies... I've lost more fans than I can afford to lose!",
  ui_story_5037_50371101_45_dialog_content = "The only way to make up for my lost fans is to train harder than ever before and enter as many idol events as possible.",
  ui_story_5037_50371101_46_dialog_content = "Fia won't let me out of it, either... She glares at me like a hawk during training, so I can't slack off for even a second!",
  ui_story_5037_50371101_47_dialog_content = "Why, just last training session, I tried to catch my breath for a few moments... And she made Kyllo bite my leg!",
  ui_story_5037_50371101_48_dialog_content = "Just look at this, PlayerName! My leg has more bite marks than a chew toy! You have to save me...",
  ui_story_5037_50371101_49_dialog_content = "Alright, fine! I'll teach you what I know!",
  ui_story_5037_50371101_50_dialog_content = "I knew I could count on you!",
  ui_story_5037_50371101_51_dialog_content = "Now, where should we begin...",
  ui_story_5037_50371101_52_dialog_content = "Why don't we take a look at today's issue of the Daily Drivel first? Let's see...",
  ui_story_5037_50371101_53_dialog_content = "\"Vic once described himself as an eternal 18-year-old, but his real age is far greater than that\"?!",
  ui_story_5037_50371101_54_dialog_content = "I mean, this sounds like a true statement.",
  ui_story_5037_50371101_55_dialog_content = "Oh, I remember! I suppose I did say that about myself, yes...",
  ui_story_5037_50371101_56_dialog_content = "How is this a lie, then?!",
  ui_story_5037_50371101_57_dialog_content = "My real age is a secret!",
  ui_story_5037_50371101_58_dialog_content = "Fine... I guess it's okay, just remember to keep it a secret.",
  ui_story_5037_50371101_59_dialog_content = "What else does it say? \"Vic believes that he is far more youthful and energetic than the ever-popular Goldie\"?!",
  ui_story_5037_50371101_60_dialog_content = "Hah? Those were his words, not mine! He said that while complimenting my performance!",
  ui_story_5037_50371101_61_dialog_content = "So... How did you respond?",
  ui_story_5037_50371101_62_dialog_content = "Well, a compliment's a compliment! Why would I deny it?",
  ui_story_5037_50371101_63_dialog_content = "If you agree with whatever he says, that just makes you an even easier target, Vic!",
  ui_story_5037_50371101_64_dialog_content = "Th-Then how should I have replied?!",
  ui_story_5037_50371101_65_dialog_content = "His phrasing was meant to trick you into admitting that you think you're better than the other idols.",
  ui_story_5037_50371101_66_dialog_content = "So if you find yourself in a similar situation, try being more humble and say that others are better than you. That way, he won't have anything to work with!",
  ui_story_5037_50371101_67_dialog_content = "Okay, okay. I'll try that next time!",
  ui_story_5037_50371101_68_dialog_content = "Let's keep reading...",
  ui_story_5037_50371101_69_dialog_content = "\"Vic's producer is known to threaten innocent reporters with violent, wild animals\"?!",
  ui_story_5037_50371101_70_dialog_content = "Fia... What did you do?",
  ui_story_5037_50371101_71_dialog_content = "D-Don't look at me!",
  ui_story_5037_50371101_72_dialog_content = "He was way too annoying, so I had Kyllo throw him out into the street!",
  ui_story_5037_50371101_73_dialog_content = "I-I see... Let's not do that anymore, okay?",
  ui_story_5037_50371101_74_dialog_content = "No matter how irritating these reporters are, resorting to violence is never the right way to deal with them.",
  ui_story_5037_50371101_75_dialog_content = "You're only giving them more reasons to target you with their slander.",
  ui_story_5037_50371101_76_dialog_content = "So then, how should I deal with them?!",
  ui_story_5037_50371101_77_dialog_content = "I can't stop them from coming in, and I can't make them leave... They're like a swarm of mosquitos but even more vicious!",
  ui_story_5037_50371101_78_dialog_content = "When they pester you like that, you can only politely insist that you aren't accepting interviews and turn them away.",
  ui_story_5037_50371101_79_dialog_content = "That way, even if they slander Vic in their articles, their claims won't have any real evidence to back them up, which people will notice.",
  ui_story_5037_50371101_80_dialog_content = "Also, as long as Vic keeps improving, no amount of gossip will be able to hurt his reputation.",
  ui_story_5037_50371101_81_dialog_content = "Okay, I think I understand now.",
  ui_story_5037_50371101_82_dialog_content = "Thank you, PlayerName. You really are a life-saver!",
  ui_story_5037_50371101_83_dialog_content = "Don't mention it. We might be rivals for the time being, but we'll always be friends first.",
  ui_story_5037_50371101_84_dialog_content = "I would never let something as trivial as a contest gets in the way of helping my friends!",
  ui_story_5037_50371101_85_dialog_content = "*Sobbing* You really are my hero!",
  ui_story_5037_50371101_86_dialog_content = "Thanks so much, PlayerName!",
  ui_story_5037_50371101_87_dialog_content = "I swear on my honor as an extrozoologist and idol that I won't let you down!",
  ui_story_5037_50371101_88_dialog_content = "When Fia was doing research on how to become a producer, she found a pair of books that you might find useful.",
  ui_story_5037_50371101_89_dialog_content = "Go ahead and choose one among them. Consider it a token of our gratitude.",
  ui_story_5037_50371101_90_dialog_content = "Wait... Aren't these my books? No wonder I couldn't find them all this time... You were hiding them in your clothing!",
  ui_story_5037_50371101_91_dialog_content = "A-Anyhow, I've already read through both of them, so choose whichever you want, PlayerName.",
  ui_story_5037_50371101_92_dialog_content = "Thanks... I'll just take this one for now—",
  ui_story_5037_50371101_93_option_content = "\"Crash Course for New Idols\"",
  ui_story_5037_50371101_94_option_content = "\"Professional Development for Professional Producers\"",
  ui_story_5037_50371101_95_dialog_content = "Right! We should get back to our training now!",
  ui_story_5037_50371101_96_dialog_content = "Let's go, you good-for-nothing master! The day's not over yet!",
  ui_story_5037_50371101_97_dialog_content = "H-Huh?! Still?!",
  ui_story_5037_50371101_98_dialog_content = "That's right! We wasted plenty of precious time talking to PlayerName, so now you're gonna make it all up!",
  ui_story_5037_50371101_99_dialog_content = "Someone save me... Please...",
  ui_story_5037_50371201_1_dialog_content = "Vic asked me to wait for him here... Doesn't he know the concert contest is just around the corner?",
  ui_story_5037_50371201_2_dialog_content = "He even told me to come here all by myself, and to keep it a secret from Fia...",
  ui_story_5037_50371201_3_dialog_content = "What the heck is he up to now?",
  ui_story_5037_50371201_4_dialog_content = "Oho? On time, just as I expected! Good to see you, PlayerName!",
  ui_story_5037_50371201_5_dialog_content = "Alright Vic, tell me what's going on...",
  ui_story_5037_50371201_6_dialog_content = "Oh, nothing terribly important, really! I just wanted to ask...",
  ui_story_5037_50371201_7_dialog_content = "Could you let me hide out here for a day? Please?!",
  ui_story_5037_50371201_8_dialog_content = "Huh...?!",
  ui_story_5037_50371201_9_dialog_content = "It's almost time for the concert, why would you want to hide out here instead of training?",
  ui_story_5037_50371201_10_dialog_content = "Precisely because of my training! Just listen, this is what a normal day looks like for me...",
  ui_story_5037_50371201_11_dialog_content = "Fia wakes me every morning for training before the sun even rises.",
  ui_story_5037_50371201_12_dialog_content = "Get up, lazy Master! It's training time!",
  ui_story_5037_50371201_13_dialog_content = "Let's start by whipping that flabby body into shape! Ten laps around the forest, go!",
  ui_story_5037_50371201_14_dialog_content = "Hrnnng... But I'm so sleepy...",
  ui_story_5037_50371201_15_dialog_content = "Just five more minutes...",
  ui_story_5037_50371201_16_dialog_content = "Not cooperating? Fine by me... Get him, Kyllo!",
  ui_story_5037_50371201_17_dialog_content = "Lo—!",
  ui_story_5037_50371201_18_dialog_content = "Ow!!!",
  ui_story_5037_50371201_19_dialog_content = "S-Stop with the biting! I'm up, I'm up!!!",
  ui_story_5037_50371201_20_dialog_content = "After my run, I go for a quick shower and breakfast.",
  ui_story_5037_50371201_21_dialog_content = "Today's breakfast is a sawdust bun with a side of boiled carrots and a glass of milk!",
  ui_story_5037_50371201_22_dialog_content = "B-But I've had boiled carrots for three days straight now... Can't we change things up a little?",
  ui_story_5037_50371201_23_dialog_content = "Like maybe some sizzling, spicy, grilled sandworm skewers?",
  ui_story_5037_50371201_24_dialog_content = "You're an idol now, Master, and idols must watch their figure at all times! If you don't want boiled carrots, then you're out of luck... Because guess what's for lunch and dinner?",
  ui_story_5037_50371201_25_dialog_content = "Nooooooo!",
  ui_story_5037_50371201_26_dialog_content = "Oh, and—",
  ui_story_5037_50371201_27_dialog_content = "Urgh... I-I think I've heard enough, Vic...",
  ui_story_5037_50371201_28_dialog_content = "That's why, in the interest of my health as well as my sanity, I'm begging you, PlayerName... Let me hide here for a day and rest!",
  ui_story_5037_50371201_29_dialog_content = "Just one day is more than enough! No Aurorian should ever have to go through this kind of hell!",
  ui_story_5037_50371201_30_dialog_content = "If this continues, the world will lose its greatest extrozoologist in no time!",
  ui_story_5037_50371201_31_dialog_content = "You... I... Sigh...",
  ui_story_5037_50371201_32_dialog_content = "I know Fia's only doing this to help you pass the concert contest, but her training regimen does seem a little... strict.",
  ui_story_5037_50371201_33_dialog_content = "You can stay here and rest for a bit, but only on two conditions—",
  ui_story_5037_50371201_34_dialog_content = "One, you have to go back to Fia as soon as you're rested, so she doesn't worry about you.",
  ui_story_5037_50371201_35_dialog_content = "And two... You need to have a serious talk with Fia about your feelings on her training regimen.",
  ui_story_5037_50371201_36_dialog_content = "Not a problem! As long as I manage to lose, er... I mean, lose some of this fatigue. I'll do whatever you want!",
  ui_story_5037_50371201_37_dialog_content = "Alright, then get some rest, Vic. I still have to draw up Goldie's schedule for today, so I'll leave you alone.",
  ui_story_5037_50371201_38_dialog_content = "Yes, yes, go ahead! I'll be fine by myself!",
  ui_story_5037_50371201_39_dialog_content = "This sofa looks awfully comfy... Perfect for a nice, long nap!",
  ui_story_5037_50371201_40_dialog_content = "Alright, my Little Furball, come here and let me hold you while I sleep!",
  ui_story_5037_50371201_41_dialog_content = "Chirp!",
  ui_story_5037_50371201_42_dialog_content = "Snore... Snore...",
  ui_story_5037_50371201_43_dialog_content = "(He's already asleep? That's Vic for you, I guess...)",
  ui_story_5037_50371201_44_dialog_content = "(Well, I should get back to work now.)",
  ui_story_5037_50371201_45_dialog_content = "<color=#828282>Some time later</color>",
  ui_story_5037_50371201_46_dialog_content = "(Alright, that should do it for the schedule! I think I'm starting to get the hang of this stuff!)",
  ui_story_5037_50371201_47_dialog_content = "<color=#828282>Knock, knock!</color>",
  ui_story_5037_50371201_48_dialog_content = "(Hmm? Someone's at the door...)",
  ui_story_5037_50371201_49_dialog_content = "Hello?",
  ui_story_5037_50371201_50_dialog_content = "Hiya, PlayerName! It's me, Fia!",
  ui_story_5037_50371201_51_dialog_content = "(F-Fia?!)",
  ui_story_5037_50371201_52_dialog_content = "(Oh no... Vic's still here!)",
  ui_story_5037_50371201_53_dialog_content = "<color=#828282>Knock, knock!</color>",
  ui_story_5037_50371201_54_dialog_content = "PlayerName?",
  ui_story_5037_50371201_55_dialog_content = "J-Just a second!",
  ui_story_5037_50371201_56_dialog_content = "Vic! Wake up, Vic!",
  ui_story_5037_50371201_57_dialog_content = "Nnng... Haha... Stop that, you Little Furball... Hahaha...",
  ui_story_5037_50371201_58_dialog_content = "He sleeps even heavier than I do!",
  ui_story_5037_50371201_59_dialog_content = "(Guess it can't be helped... I'll have to hide him for now.)",
  ui_story_5037_50371201_60_dialog_content = "(Let me see... This pile of magazines looks good. I'll hide him behind it!)",
  ui_story_5037_50371201_61_dialog_content = "Coming, Fia!",
  ui_story_5037_50371201_62_dialog_content = "What took you so long?",
  ui_story_5037_50371201_63_dialog_content = "S-Sorry, I was just, uh... Cleaning up the room!",
  ui_story_5037_50371201_64_dialog_content = "Well, it does look like the place could use some tidying up... That pile of magazines is as big as a mountain!",
  ui_story_5037_50371201_65_dialog_content = "Aha...ha... Anyways, did you need something, Fia?",
  ui_story_5037_50371201_66_dialog_content = "Yeah, actually... Have you seen Master Vic around here lately?",
  ui_story_5037_50371201_67_dialog_content = "Uh, V-Vic? Nope, can't say I have!",
  ui_story_5037_50371201_68_dialog_content = "You don't say...?",
  ui_story_5037_50371201_69_dialog_content = "I've been cleaning all day today, as well as working on Goldie's schedule... So no, I haven't seen Vic at all today!",
  ui_story_5037_50371201_70_dialog_content = "Sigh... If you say so. I'm honestly surprised he didn't come running to you first...",
  ui_story_5037_50371201_71_dialog_content = "Where did that good-for-nothing master of mine run off to...?",
  ui_story_5037_50371201_72_dialog_content = "Maybe he went somewhere to slack off for a bit? I'm sure he'll be back soon enough.",
  ui_story_5037_50371201_73_dialog_content = "The concert is just a few days away... I can't believe that guy still thinks he can screw around like this.",
  ui_story_5037_50371201_74_dialog_content = "I'll make sure to train him extra hard when he gets back...",
  ui_story_5037_50371201_75_dialog_content = "I-Is it possible that your training might be why he ran off, Fia?",
  ui_story_5037_50371201_76_dialog_content = "It's fine to take training seriously and all... But you have to remember to balance it out with rest as well.",
  ui_story_5037_50371201_77_dialog_content = "You think?",
  ui_story_5037_50371201_78_dialog_content = "You know, I was thinking of giving him the day off, so he could get some rest...",
  ui_story_5037_50371201_79_dialog_content = "But then he suddenly disappeared on me! I've searched all over Umbraton, but still no sign of him.",
  ui_story_5037_50371201_80_dialog_content = "(Fia was planning to give Vic a day off all along? So she has been arranging his schedule properly.)",
  ui_story_5037_50371201_81_dialog_content = "Don't worry, Fia. I'll ask everyone to help you look for him.",
  ui_story_5037_50371201_82_dialog_content = "Sure, thanks. I'll keep searching, then.",
  ui_story_5037_50371201_83_dialog_content = "Wait a second... Isn't that...?",
  ui_story_5037_50371201_84_dialog_content = "(Crap! She noticed the pile of magazines that Vic's hiding under!)",
  ui_story_5037_50371201_85_dialog_content = "Oh! S-Sorry, those are just some magazines I was flipping through earlier! I'll clean them up in a bit—",
  ui_story_5037_50371201_86_dialog_content = "It looks kind of funny, doesn't it? As if there's something buried underneath it...",
  ui_story_5037_50371201_87_dialog_content = "No, wait—!",
  ui_story_5037_50371201_88_dialog_content = "M-Master?!",
  ui_story_5037_50371201_89_dialog_content = "Snore... Snore...",
  ui_story_5037_50371201_90_dialog_content = "Wh-What's he doing sleeping here?!",
  ui_story_5037_50371201_91_dialog_content = "PlayerName... Were you lying to me?",
  ui_story_5037_50371201_92_dialog_content = "I, uh...",
  ui_story_5037_50371201_93_option_content = "Confess",
  ui_story_5037_50371201_94_dialog_content = "Alright, I confess... I was lying to you earlier.",
  ui_story_5037_50371201_95_dialog_content = "I'm sorry...",
  ui_story_5037_50371201_96_dialog_content = "It's okay, PlayerName. I know you wouldn't lie to me on purpose.",
  ui_story_5037_50371201_97_option_content = "Make something up",
  ui_story_5037_50371201_98_dialog_content = "H-He must have snuck in here before I arrived! Yeah, that must be it...",
  ui_story_5037_50371201_99_dialog_content = "I can tell you're lying, PlayerName... It's written all over your face.",
  ui_story_5037_50371201_100_dialog_content = "But I think I know what's going on here.",
  ui_story_5037_50371201_101_dialog_content = "My good-for-nothing master begged you to let him stay here, didn't he?",
  ui_story_5037_50371201_102_dialog_content = "Well, the truth is...",
  ui_story_5037_50371201_103_dialog_content = "Vic came to see me this morning and asked if he could hide here and rest for the day.",
  ui_story_5037_50371201_104_dialog_content = "He said that his idol training had left him completely exhausted, and he passed out not long after he got here.",
  ui_story_5037_50371201_105_dialog_content = "But I don't understand! Why would he run away and find you instead of talking to me?",
  ui_story_5037_50371201_106_dialog_content = "I was planning to give him the day off and everything!",
  ui_story_5037_50371201_107_dialog_content = "Why don't you have a word with him once he wakes up?",
  ui_story_5037_50371201_108_dialog_content = "Sigh... Forget it. I'll just let him rest here for now.",
  ui_story_5037_50371201_109_dialog_content = "Remind him to come back for training once he wakes up, okay?",
  ui_story_5037_50371201_110_dialog_content = "I'll put together some tips and tricks for idol training to share with you later. Take it as my way of saying thanks for keeping an eye on my good-for-nothing master.",
  ui_story_5037_50371201_111_dialog_content = "Sure, thanks!",
  ui_story_5037_50371201_112_dialog_content = "Oh, and one last thing... Don't tell him I came here, got it?",
  ui_story_5037_50371201_113_dialog_content = "Sure, but why?",
  ui_story_5037_50371201_114_dialog_content = "Because...",
  ui_story_5037_50371201_115_dialog_content = "<size=45>Master is completely untrustworthy!</size>",
  ui_story_5037_50371201_116_dialog_content = "Huh?!",
  ui_story_5037_50371201_117_dialog_content = "If you give him an inch, he'll take a mile before you know it!",
  ui_story_5037_50371201_118_dialog_content = "Whether it's training or even just doing stuff around the house, he'll just find more excuses to slack off if he finds out I was going to give him a break.",
  ui_story_5037_50371201_119_dialog_content = "For people like him, the only way to get them to cooperate is by being mercilessly strict!",
  ui_story_5037_50371201_120_dialog_content = "O-Okay!",
  ui_story_5037_50371201_121_dialog_content = "I'll send him back for training as soon as he wakes up!",
  ui_story_5037_50371301_1_dialog_content = "Why does this have to happen right now, of all times?",
  ui_story_5037_50371301_2_dialog_content = "Well, I don't really see a problem here...",
  ui_story_5037_50371301_3_dialog_content = "Only a good-for-nothing Master like you would say that at a time like this!",
  ui_story_5037_50371301_4_dialog_content = "Is this situation really bad?",
  ui_story_5037_50371301_5_dialog_content = "I'm afraid so...",
  ui_story_5037_50371301_6_dialog_content = "We're in serious trouble now, everyone!",
  ui_story_5037_50371301_7_dialog_content = "No matter how hard we try... Goldie and Vic's progress is starting to slow down!",
  ui_story_5037_50371301_8_dialog_content = "This is what they call the dreaded \"plateau\"!",
  ui_story_5037_50371301_9_dialog_content = "Fia and I came up with a unique solution to our problem so that we'll be able to realize our full potential before our graduation concerts!",
  ui_story_5037_50371301_10_dialog_content = "We're going to switch producers!",
  ui_story_5037_50371301_11_dialog_content = "Huh?!",
  ui_story_5037_50371301_12_dialog_content = "That's right! You're going to train my good-for-nothing master, PlayerName! Meanwhile, I'll work with Goldie on her training!",
  ui_story_5037_50371301_13_dialog_content = "Get ready for a super-exciting, one-day training exchange program!",
  ui_story_5037_50371301_14_dialog_content = "With new producers, new training regimens, and new environments for everyone involved... I'm sure we'll find new and exciting inspiration to break through our plateaus!",
  ui_story_5037_50371301_15_dialog_content = "So does this mean... I'll be in charge of training Vic?",
  ui_story_5037_50371301_16_dialog_content = "Ooh! Sounds like a fine idea to me! Maybe I'll finally be able to take it easy for a bit...",
  ui_story_5037_50371301_17_dialog_content = "Ow, ow, ow! That was my foot, Fia!",
  ui_story_5037_50371301_18_dialog_content = "We thought of that too, Master. Here you go, PlayerName; Kyllo will be your assistant for the training exchange.",
  ui_story_5037_50371301_19_dialog_content = "Lo!",
  ui_story_5037_50371301_20_dialog_content = "And don't worry, Kyllo knows exactly what to do if Master goofs off or refuses to get out of bed... Right, Kyllo?",
  ui_story_5037_50371301_21_dialog_content = "You really thought of everything, Fia...",
  ui_story_5037_50371301_22_dialog_content = "Alright, then it's settled!",
  ui_story_5037_50371301_23_dialog_content = "Do your best to help Vic just like you do with me, okay PlayerName?",
  ui_story_5037_50371301_24_dialog_content = "I know you'll do great!",
  ui_story_5037_50371301_25_dialog_content = "Sure, leave it to me.",
  ui_story_5037_50371301_26_dialog_content = "We'll be going, then! Good luck, you two!",
  ui_story_5037_50371301_27_dialog_content = "Now for a well-deserved break—",
  ui_story_5037_50371301_28_dialog_content = "Ow!!!",
  ui_story_5037_50371301_29_dialog_content = "L-Let go, Kyllo! My leg's not for eating!!!",
  ui_story_5037_50371301_30_dialog_content = "Lo!",
  ui_story_5037_50371301_31_dialog_content = "Wow... Kyllo can even tell when you're thinking about slacking off, Vic. Pretty impressive.",
  ui_story_5037_50371301_32_dialog_content = "Sigh... Fia really turned you against me, didn't she, Kyllo?",
  ui_story_5037_50371301_33_dialog_content = "After all I did for you too! Raising you from birth, giving you a way to survive in the world...",
  ui_story_5037_50371301_34_dialog_content = "Ou—ch!!!",
  ui_story_5037_50371301_35_dialog_content = "It looks like Kyllo means business, Vic... We should get started with training.",
  ui_story_5037_50371301_36_dialog_content = "*Sobbing* Why am I always the one who gets hurt...?",
  ui_story_5037_50371301_37_dialog_content = "Don't worry, Vic. I balance work and rest with my training, so you should be fine.",
  ui_story_5037_50371301_38_dialog_content = "First on the agenda today are vocal exercises.",
  ui_story_5037_50371301_39_dialog_content = "<color=#828282>Some time later</color>",
  ui_story_5037_50371301_40_dialog_content = "♪ Ah, spring has come hither, and everything has come alive again! ♪",
  ui_story_5037_50371301_41_dialog_content = "♪ Animals rise from their burrows and dens ♪",
  ui_story_5037_50371301_42_dialog_content = "♪ In the woods and in the prairies ♪",
  ui_story_5037_50371301_43_dialog_content = "Alright, you can take a break now, Vic.",
  ui_story_5037_50371301_44_dialog_content = "At last! It's finally break time!",
  ui_story_5037_50371301_45_dialog_content = "Lo...",
  ui_story_5037_50371301_46_dialog_content = "I'm not slacking off this time, Kyllo! This is a real and honest break!",
  ui_story_5037_50371301_47_dialog_content = "Hey, Vic? I've been meaning to ask... What made you want to become an idol in the first place?",
  ui_story_5037_50371301_48_dialog_content = "Huh? You've got it all wrong.",
  ui_story_5037_50371301_49_dialog_content = "Huh?",
  ui_story_5037_50371301_50_dialog_content = "First of all, I'm not an idol. I am, and always will be, an extrozoologist!",
  ui_story_5037_50371301_51_dialog_content = "So what are you doing in the competition?!",
  ui_story_5037_50371301_52_dialog_content = "To make money, obviously!",
  ui_story_5037_50371301_53_dialog_content = "You're just in it... for the prize money?",
  ui_story_5037_50371301_54_dialog_content = "I mean, I know Lady Sheol's offering a huge prize, and I know your financial situation is usually pretty grim...",
  ui_story_5037_50371301_55_dialog_content = "But why is Fia involved too?",
  ui_story_5037_50371301_56_dialog_content = "It was Fia's idea in the first place! She saw a poster for the contest and decided to drag me into her scheme...",
  ui_story_5037_50371301_57_dialog_content = "We were running a little low on funds for taking care of our wondrous beasts...",
  ui_story_5037_50371301_58_dialog_content = "How low?",
  ui_story_5037_50371301_59_dialog_content = "Well... I did have to go into a little debt just to buy Bica and Drakolion snacks...",
  ui_story_5037_50371301_60_dialog_content = "That bad?!",
  ui_story_5037_50371301_61_dialog_content = "Wait... Shouldn't you pass on snacks to save money if things are that bad?",
  ui_story_5037_50371301_62_dialog_content = "Not a chance!",
  ui_story_5037_50371301_63_dialog_content = "Those wondrous beasts are my friends; I couldn't live with myself if they had to go without their creature comforts!",
  ui_story_5037_50371301_64_dialog_content = "Usually, Fia and Shira make money by doing odd jobs in between their research projects, so we've never had to worry about going into debt.",
  ui_story_5037_50371301_65_dialog_content = "But during Fia's last expedition, she spent an incredible amount of time investigating a rare wondrous beast, only to return without any notable results.",
  ui_story_5037_50371301_66_dialog_content = "And just like that, our savings dried up and I had to borrow a bunch of money!",
  ui_story_5037_50371301_67_dialog_content = "... May I ask what you were doing while she was away?",
  ui_story_5037_50371301_68_dialog_content = "Me? Well, naturally, I was taking care of the wondrous beasts and conserving my energy with plenty of naps...",
  ui_story_5037_50371301_69_dialog_content = "It sounds like you weren't trying to help at all!",
  ui_story_5037_50371301_70_dialog_content = "Suddenly, I feel like I understand Fia and Shira's struggle much more...",
  ui_story_5037_50371301_71_dialog_content = "Well, I'm here making money now, aren't I? I even agreed to all these silly performances!",
  ui_story_5037_50371301_72_dialog_content = "I've been working really hard up till now!",
  ui_story_5037_50371301_73_dialog_content = "I know, I know... Honestly, I was expecting you to give up halfway and try to find a way out of this.",
  ui_story_5037_50371301_74_dialog_content = "I would never do such a thing! Especially when it comes to ensuring that the wondrous beasts have enough to eat!",
  ui_story_5037_50371301_75_dialog_content = "I'd do anything for those guys.",
  ui_story_5037_50371301_76_dialog_content = "And that's why I would gladly loan you my apprentices, for anything you might need! As long as you pay, of course.",
  ui_story_5037_50371301_77_dialog_content = "Forget it, Vic! Don't make life even harder for those two!",
  ui_story_5037_50371301_78_dialog_content = "I swear, sometimes it feels like you care more about your Little Furball than you do about Fia and Shira...",
  ui_story_5037_50371301_79_dialog_content = "You couldn't be more wrong! Words can't describe how proud I am of my cherished apprentices!",
  ui_story_5037_50371301_80_dialog_content = "Not only have I passed on all of my extrozoological expertise to them... They also know how to make money and survive in the world!",
  ui_story_5037_50371301_81_dialog_content = "On top of that, neither of them is afraid to fight off Eclipsites!",
  ui_story_5037_50371301_82_dialog_content = "Someday, I'll be able to entrust them with all of my research projects on Astra's wondrous beasts...",
  ui_story_5037_50371301_83_dialog_content = "What will you do then? Take even more naps?",
  ui_story_5037_50371301_84_dialog_content = "Not a bad idea! I'll be sure to consider it!",
  ui_story_5037_50371301_85_dialog_content = "But before then, I still have a lot of important work to do.",
  ui_story_5037_50371301_86_dialog_content = "I believe that there are other continents like Astra in our world.",
  ui_story_5037_50371301_87_dialog_content = "I want to see them all, and learn everything there is to know about the wondrous beasts that inhabit their lands!",
  ui_story_5037_50371301_88_dialog_content = "I had no idea you had such a grandiose dream...",
  ui_story_5037_50371301_89_dialog_content = "But of course! After all, I'm—",
  ui_story_5037_50371301_90_dialog_content = "Ow!!!",
  ui_story_5037_50371301_91_dialog_content = "What's the big idea, Kyllo?!",
  ui_story_5037_50371301_92_dialog_content = "It looks like Kyllo was reminding you that your break is over, Vic. Back to training!",
  ui_story_5037_50371301_93_dialog_content = "Fia really had a bad influence on you, didn't she Kyllo? You're even harsher than she is now!",
  ui_story_5037_50371301_94_dialog_content = "But since PlayerName is in charge of my training today, maybe he can extend my break time by a few more minutes, what do you say?",
  ui_story_5037_50371301_95_dialog_content = "Hmm...",
  ui_story_5037_50371301_96_dialog_content = "Come on! I'll even let you pet Little Furball in the meantime!",
  ui_story_5037_50371301_97_dialog_content = "Well, when you put it that way, I suppose we can...",
  ui_story_5037_50371301_98_option_content = "Train twice as hard!",
  ui_story_5037_50371301_99_option_content = "Train ten times as hard!",
  ui_story_5037_50371301_100_dialog_content = "I developed a training program to help Goldie break through a potential plateau.",
  ui_story_5037_50371301_101_dialog_content = "I never put it into practice because it seemed too hard, but I'm gonna try it out on you first!",
  ui_story_5037_50371301_102_dialog_content = "What?!",
  ui_story_5037_50371301_103_dialog_content = "Don't worry, it's just for a bit. That way, I can make a few adjustments before I show it to Goldie.",
  ui_story_5037_50371301_104_dialog_content = "Naturally, this should also help you improve.",
  ui_story_5037_50371301_105_dialog_content = "We can't let all of Fia's hard work be in vain, so we're going to train our hearts out! You ready, Vic?",
  ui_story_5037_50371301_106_dialog_content = "Noooo—!!!",
  ui_story_5037_50371401_1_dialog_content = "Team PlayerName's emergency meeting, take one! Three, two, one... Action!",
  ui_story_5037_50371401_2_dialog_content = "D-Do we really have to film this, too?",
  ui_story_5037_50371401_3_dialog_content = "Duh! A great director never lets a precious opportunity go to waste!",
  ui_story_5037_50371401_4_dialog_content = "If you say so...",
  ui_story_5037_50371401_5_dialog_content = "Then let's begin our very first Producer's Crash Course Workshop.",
  ui_story_5037_50371401_6_dialog_content = "...",
  ui_story_5037_50371401_7_dialog_content = "(There are books scattered all about the office...)",
  ui_story_5037_50371401_8_dialog_content = "(Did Vice and Carleen really bring all of these for the workshop?)",
  ui_story_5037_50371401_9_dialog_content = "(They look dead serious... I have a bad feeling about this...)",
  ui_story_5037_50371401_10_dialog_content = "Um, why do you two look so serious...?",
  ui_story_5037_50371401_11_dialog_content = "Because it IS serious, PlayerName. This will affect whether or not you can become a successful producer.",
  ui_story_5037_50371401_12_dialog_content = "Indeed. When it comes to your success, we can't afford to be careless.",
  ui_story_5037_50371401_13_dialog_content = "Thanks for the concern, but I'm the one responsible for that, not you two...",
  ui_story_5037_50371401_14_dialog_content = "What are you talking about? We're partners, aren't we? We're always going to be here to back you up!",
  ui_story_5037_50371401_15_dialog_content = "And in order to help you understand your new profession as much as possible, Vice and I did our own share of research.",
  ui_story_5037_50371401_16_dialog_content = "That's right! Everything you could ever want to learn, from being an idol to being a producer, is in these books!",
  ui_story_5037_50371401_17_dialog_content = "Starting today, this will be where our Producer's Crash Course Workshop takes place!",
  ui_story_5037_50371401_18_dialog_content = "Wait a minute... These are all notes and article clippings?!",
  ui_story_5037_50371401_19_dialog_content = "Yup! Carleen went to the library and took notes on every single book related to training regimens for singers and dancers.",
  ui_story_5037_50371401_20_dialog_content = "Meanwhile, I bought a copy of every newspaper printed over the last few years and clipped everything that has to do with idols and producers!",
  ui_story_5037_50371401_21_dialog_content = "That's scary impressive...",
  ui_story_5037_50371401_22_dialog_content = "It must have taken days to read all of those books and write these notes...",
  ui_story_5037_50371401_23_dialog_content = "Well, I did have some help from Chloe and Keating during my research.",
  ui_story_5037_50371401_24_dialog_content = "Both of them know far more about music than I do, so they wrote a large portion of these notes.",
  ui_story_5037_50371401_25_dialog_content = "And I had some help from Brandy!",
  ui_story_5037_50371401_26_dialog_content = "As a professional reporter, she's really familiar with all sorts of news and events!",
  ui_story_5037_50371401_27_dialog_content = "Yes, all of this would not have been possible without everyone's help.",
  ui_story_5037_50371401_28_dialog_content = "No kidding...",
  ui_story_5037_50371401_29_dialog_content = "Looks like I can't afford to slack off! Everyone's expecting a lot from me!",
  ui_story_5037_50371401_30_dialog_content = "Then let's get started.",
  ui_story_5037_50371401_31_dialog_content = "Our next order of business is to decide on a training plan for you, PlayerName!",
  ui_story_5037_50371401_32_dialog_content = "A training plan?",
  ui_story_5037_50371401_33_dialog_content = "Yes. We developed two different training plans for you. We'll let you decide which one is more suitable.",
  ui_story_5037_50371401_34_dialog_content = "This one is called \"Producers: From Beginner to Expert.\"",
  ui_story_5037_50371401_35_dialog_content = "It's so thick!!",
  ui_story_5037_50371401_36_dialog_content = "It contains knowledge that ranges in complexity from rudimentary to professional level. However, the material is dense and will require more time to study.",
  ui_story_5037_50371401_37_dialog_content = "And the other one...?",
  ui_story_5037_50371401_38_dialog_content = "This one is called \"Advanced Producer Techniques.\" It includes different time management techniques used by famous scholars throughout the ages.",
  ui_story_5037_50371401_39_dialog_content = "However, this plan requires a basic knowledge of the industry to be understood well enough to use.",
  ui_story_5037_50371401_40_dialog_content = "Go ahead, PlayerName! Choose the plan you think suits you best!",
  ui_story_5037_50371401_41_dialog_content = "The plan that suits me best...",
  ui_story_5037_50371401_42_dialog_content = "Well, I'm still pretty inexperienced as a producer, so I think this one will do—",
  ui_story_5037_50371401_43_option_content = "\"Producers: From Beginner to Expert\"",
  ui_story_5037_50371401_44_dialog_content = "If I want to start with the fundamentals, this plan should be my safest bet!",
  ui_story_5037_50371401_45_dialog_content = "I agree.",
  ui_story_5037_50371401_46_dialog_content = "Then it's settled! Starting today, you'll use this to help you learn how to be a professional producer!",
  ui_story_5037_50371401_47_dialog_content = "I'll do my best!",
  ui_story_5037_50371401_48_dialog_content = "<color=#828282>Some time later</color>",
  ui_story_5037_50371401_49_dialog_content = "A producer's main responsibilities... Tracking progress, developing schedules...",
  ui_story_5037_50371401_50_dialog_content = "What else? Ugh, I think I already forgot...",
  ui_story_5037_50371401_51_dialog_content = "Why don't you take a break?",
  ui_story_5037_50371401_52_dialog_content = "You've already memorized a lot. Your next step is to try and put those concepts into practice.",
  ui_story_5037_50371401_53_option_content = "\"Advanced Producer Techniques\"",
  ui_story_5037_50371401_54_dialog_content = "I already decided to challenge myself by doing this, so let's start with the hard stuff!",
  ui_story_5037_50371401_55_dialog_content = "Are you sure?!",
  ui_story_5037_50371401_56_dialog_content = "If this is how you want to proceed, then we'll do our best to support you.",
  ui_story_5037_50371401_57_dialog_content = "I-I should be fine!",
  ui_story_5037_50371401_58_dialog_content = "<color=#828282>Some time later</color>",
  ui_story_5037_50371401_59_dialog_content = "It's too hard!",
  ui_story_5037_50371401_60_dialog_content = "I agree, this does seem a little hard...",
  ui_story_5037_50371401_61_dialog_content = "I felt the same when I was devising this plan... Many complex topics are involved, all of which are interconnected in some way or another.",
  ui_story_5037_50371401_62_dialog_content = "Looks like I'll have to take it step by step if I want to learn things right.",
  ui_story_5037_50371401_63_dialog_content = "It's getting late, though. Let's stop here for today.",
  ui_story_5037_50371401_64_dialog_content = "Good work, PlayerName!",
  ui_story_5037_50371401_65_dialog_content = "Well done.",
  ui_story_5037_50371401_66_dialog_content = "I should be the one saying that! I'm sure it wasn't easy to gather all of these materials...",
  ui_story_5037_50371401_67_dialog_content = "We're such good friends, there's no need for formalities.",
  ui_story_5037_50371401_68_dialog_content = "Go back and get some rest, okay?",
  ui_story_5037_50371401_69_dialog_content = "Yeah, same to you two!",
  ui_story_5037_50371401_70_dialog_content = "We still have some matters to attend to before we return, so no need to wait for us.",
  ui_story_5037_50371401_71_dialog_content = "Huh? Where are you going?",
  ui_story_5037_50371401_72_dialog_content = "We set up a few interviews with some Aurorian singers in town. We want to learn about singing techniques from them.",
  ui_story_5037_50371401_73_dialog_content = "Even though their styles and backgrounds are different, they must still have some advice to offer.",
  ui_story_5037_50371401_74_dialog_content = "If we can pinpoint their techniques and present them to Goldie, I'm certain it will be of great use to her.",
  ui_story_5037_50371401_75_dialog_content = "But you've already done so much just to help me out!",
  ui_story_5037_50371401_76_dialog_content = "I feel like if anyone needs rest, it's you two...",
  ui_story_5037_50371401_77_dialog_content = "Don't worry about us! I still feel revved up and ready to go!",
  ui_story_5037_50371401_78_dialog_content = "This is a new and exciting experience for both of us.",
  ui_story_5037_50371401_79_dialog_content = "Perhaps it's because of this that we don't feel tired, despite all the work we've been doing.",
  ui_story_5037_50371401_80_dialog_content = "Don't you feel like that sometimes, PlayerName?",
  ui_story_5037_50371401_81_dialog_content = "I do, yeah...",
  ui_story_5037_50371401_82_dialog_content = "Ever since I started working as a producer, I don't think a day's gone by that I didn't work from dawn till dusk.",
  ui_story_5037_50371401_83_dialog_content = "But because of all the new challenges I face every day, I don't feel nearly as tired as I should!",
  ui_story_5037_50371401_84_dialog_content = "It feels like when I first got out from underground and met you guys.",
  ui_story_5037_50371401_85_dialog_content = "Even though Eclipsites were chasing us for days, I never felt tired or hopeless.",
  ui_story_5037_50371401_86_dialog_content = "That's the kind of excitement a brand-new adventure brings!",
  ui_story_5037_50371401_87_dialog_content = "Yeah!",
  ui_story_5037_50371401_88_dialog_content = "But even so, I can't just stand around while you two are so busy!",
  ui_story_5037_50371401_89_dialog_content = "Huh?",
  ui_story_5037_50371401_90_dialog_content = "Why is that?",
  ui_story_5037_50371401_91_dialog_content = "Because we're all in this together, that's how it's always been.",
  ui_story_5037_50371401_92_dialog_content = "No matter how long the journey or how dangerous the adventure, the three of us have always stuck together.",
  ui_story_5037_50371401_93_dialog_content = "So that's why I'm coming with you!",
  ui_story_5037_50371401_94_dialog_content = "But—",
  ui_story_5037_50371401_95_dialog_content = "Don't worry about me! We'll all do our best, just like we always do.",
  ui_story_5037_50371401_96_dialog_content = "Sure! Just like we always do!",
  ui_story_5037_50371501_1_dialog_content = "Team PlayerName's last-minute meeting! Three, two, one... Action!",
  ui_story_5037_50371501_2_dialog_content = "Sorry, I'm late!",
  ui_story_5037_50371501_3_dialog_content = "It's okay. At least you made it!",
  ui_story_5037_50371501_4_dialog_content = "Huh? Where's Goldie?",
  ui_story_5037_50371501_5_dialog_content = "She went to talk to Lady Sheol about her upcoming plans, so she won't be back for a while.",
  ui_story_5037_50371501_6_dialog_content = "Aw, really? What a shame...",
  ui_story_5037_50371501_7_dialog_content = "Why is that?",
  ui_story_5037_50371501_8_dialog_content = "We wanted to congratulate you both for hosting a successful debut concert.",
  ui_story_5037_50371501_9_dialog_content = "We prepared some drinks and treats for when you and Goldie returned.",
  ui_story_5037_50371501_10_dialog_content = "Wow, thanks! And don't worry, I'll be sure to bring some back for Goldie.",
  ui_story_5037_50371501_11_dialog_content = "I just wish she could be here to enjoy them right now...",
  ui_story_5037_50371501_12_dialog_content = "I spent so much time baking these cookies, so I wanted everyone to try them while they were fresh.",
  ui_story_5037_50371501_13_dialog_content = "It took a lot of tries to figure out how to bake them without burning them, too.",
  ui_story_5037_50371501_14_dialog_content = "It sounds like you really poured your heart into these, Vice...",
  ui_story_5037_50371501_15_dialog_content = "(These cookies should taste fine if she worked this hard on them... Right?)",
  ui_story_5037_50371501_16_dialog_content = "Time flies, doesn't it? I can't believe the debut concert is already over.",
  ui_story_5037_50371501_17_dialog_content = "Yeah... We've also held so many Producer's Crash Course Workshops, too!",
  ui_story_5037_50371501_18_dialog_content = "When we first started helping PlayerName become a producer, we were all so busy...",
  ui_story_5037_50371501_19_dialog_content = "But all of our efforts are starting to pay off! PlayerName managed to help Goldie host a spectacular debut concert!",
  ui_story_5037_50371501_20_dialog_content = "He's become quite the dependable producer, indeed.",
  ui_story_5037_50371501_21_dialog_content = "No kidding! You've really shown a lot of progress!",
  ui_story_5037_50371501_22_dialog_content = "Hehehe... You two are gonna make me blush! I'm the one who should be thanking you!",
  ui_story_5037_50371501_23_dialog_content = "Congratulations!",
  ui_story_5037_50371501_24_dialog_content = "Congratulations, PlayerName.",
  ui_story_5037_50371501_25_dialog_content = "Thank you!",
  ui_story_5037_50371501_26_dialog_content = "Right, now let's get this party started!",
  ui_story_5037_50371501_27_dialog_content = "Any longer and the tea will get cold!",
  ui_story_5037_50371501_28_dialog_content = "<color=#828282>Rustle...</color>",
  ui_story_5037_50371501_29_dialog_content = "... Did either of you hear a strange noise just now?",
  ui_story_5037_50371501_30_dialog_content = "Hmm? No, I don't think so?",
  ui_story_5037_50371501_31_dialog_content = "<color=#828282>Rustle, rustle——</color>",
  ui_story_5037_50371501_32_dialog_content = "There it is again. It sounds like it's coming from near the musical instruments.",
  ui_story_5037_50371501_33_dialog_content = "Maybe it was just the wind?",
  ui_story_5037_50371501_34_dialog_content = "<color=#828282>Rustle, rustle——</color>",
  ui_story_5037_50371501_35_dialog_content = "...",
  ui_story_5037_50371501_36_dialog_content = "I think something is hiding behind the drums...",
  ui_story_5037_50371501_37_dialog_content = "Could it be... an Eclipsite?",
  ui_story_5037_50371501_38_dialog_content = "I'll go take a closer look.",
  ui_story_5037_50371501_39_dialog_content = "Ice Blossom—",
  ui_story_5037_50371501_40_dialog_content = "Lo! Lo, lo, lo!",
  ui_story_5037_50371501_41_dialog_content = "What the...? It's Kyllo!",
  ui_story_5037_50371501_42_dialog_content = "But what's Kyllo doing here? Where's Fia?",
  ui_story_5037_50371501_43_dialog_content = "Lo... (Translation: Fia sent me on a top-secret mission to spy on PlayerName and the others...)",
  ui_story_5037_50371501_44_dialog_content = "Lo, lo! (Translation: But I didn't expect to find so many people here at once!)",
  ui_story_5037_50371501_45_dialog_content = "Lo... Lo! (Translation: Looks like my cover's blown... I have to find a way out of here, fast!)",
  ui_story_5037_50371501_46_dialog_content = "You wouldn't happen to be spying on us... Would you?",
  ui_story_5037_50371501_47_dialog_content = "L-Lo, lo!!",
  ui_story_5037_50371501_48_dialog_content = "I think it's trying to deny it.",
  ui_story_5037_50371501_49_dialog_content = "Makes sense... Given Kyllo's usual behavior, my guess is that it got lost while looking for something to eat.",
  ui_story_5037_50371501_50_dialog_content = "Did you maybe sneak over here because you couldn't stand Fia's training anymore either, Kyllo?",
  ui_story_5037_50371501_51_dialog_content = "Lo!",
  ui_story_5037_50371501_52_dialog_content = "I'm pretty sure that's a yes.",
  ui_story_5037_50371501_53_dialog_content = "Poor little guy. Keeping Vic in line during his training every day must be exhausting...",
  ui_story_5037_50371501_54_dialog_content = "Lo...",
  ui_story_5037_50371501_55_dialog_content = "It can rest here for a while. We have plenty of snacks to share with it.",
  ui_story_5037_50371501_56_dialog_content = "Yeah, I agree! I'll just take it back to Fia once we're done.",
  ui_story_5037_50371501_57_dialog_content = "Lo! Lo! (Translation: Great, it looks like they didn't figure out the real reason I'm here!)",
  ui_story_5037_50371501_58_dialog_content = "Lo! (Translation: I wonder what kind of snacks they were talking about?)",
  ui_story_5037_50371501_59_dialog_content = "Fia mentioned that Kyllo loved eating animal crackers, didn't she?",
  ui_story_5037_50371501_60_dialog_content = "I don't know if my cookies taste as good as the crackers you like, but...",
  ui_story_5037_50371501_61_dialog_content = "(Uh-oh... I remember this feeling!)",
  ui_story_5037_50371501_62_dialog_content = "(It's the same one as before!)",
  ui_story_5037_50371501_63_dialog_content = "Lo! (Translation: W-Wait a second! Is this even edible?!)",
  ui_story_5037_50371501_64_dialog_content = "Here, Kyllo! Try one of my fresh-baked cookies!",
  ui_story_5037_50371501_65_dialog_content = "I know they don't look as pretty as the ones in the Lumopolis bakeries, but the recipe is exactly the same!",
  ui_story_5037_50371501_66_dialog_content = "Lo! Lo! (Translation: S-Stay away from me!)",
  ui_story_5037_50371501_67_dialog_content = "Say, ahhh—",
  ui_story_5037_50371501_68_dialog_content = "Lo!!!",
  ui_story_5037_50371501_69_dialog_content = "Kyllo's running away!",
  ui_story_5037_50371501_70_dialog_content = "It's running towards our pile of books!",
  ui_story_5037_50371501_71_dialog_content = "Grab it before it makes a sticky mess out of them!",
  ui_story_5037_50371501_72_dialog_content = "Come here, Kyllo!",
  ui_story_5037_50371501_73_dialog_content = "Lo!!!",
  ui_story_5037_50371501_74_dialog_content = "(Crap! Kyllo's trying to dive into the pile of books!)",
  ui_story_5037_50371501_75_option_content = "Protect the professional books",
  ui_story_5037_50371501_76_option_content = "Protect the magazines",
  ui_story_5037_50371501_77_dialog_content = "<color=#828282>Wham!</color>",
  ui_story_5037_50371501_78_dialog_content = "Oof—!",
  ui_story_5037_50371501_79_dialog_content = "<size=45>Ow!!!</size>",
  ui_story_5037_50371501_80_dialog_content = "PlayerName?!",
  ui_story_5037_50371501_81_dialog_content = "I-I'm fine... That just hurt a little, is all...",
  ui_story_5037_50371501_82_dialog_content = "Lo...",
  ui_story_5037_50371501_83_dialog_content = "Lo, lo, lo!",
  ui_story_5037_50371501_84_dialog_content = "It runs so fast!",
  ui_story_5037_50371501_85_dialog_content = "Are the books okay?",
  ui_story_5037_50371501_86_dialog_content = "*Coughing* Yeah... Well, a portion of them, anyways...",
  ui_story_5037_50371501_87_dialog_content = "I managed to preserve some of our notes and clippings, too.",
  ui_story_5037_50371501_88_dialog_content = "The rest of them appear to be completely soaked...",
  ui_story_5037_50371501_89_dialog_content = "Well, there's no time to waste. We need to remove all of the wet books first.",
  ui_story_5037_50371501_90_dialog_content = "One, two...",
  ui_story_5037_50371501_91_dialog_content = "I think we can still read these if we manage to dry them out first.",
  ui_story_5037_50371501_92_dialog_content = "These, on the other hand... The ink is completely smeared, so we can do nothing to salvage them.",
  ui_story_5037_50371501_93_dialog_content = "I think there are a few books in there that we borrowed from other people!",
  ui_story_5037_50371501_94_dialog_content = "It can't be helped. We have to sort them out, return them to their owners, and offer our apologies as well as compensation.",
  ui_story_5037_50371501_95_dialog_content = "Guess we really don't have a choice, huh?",
  ui_story_5037_50371501_96_dialog_content = "I don't know if I have enough Nightium to cover the damages, though...",
  ui_story_5037_50371501_97_dialog_content = "I can pitch in too.",
  ui_story_5037_50371501_98_dialog_content = "As will I. After all, I wasn't able to stop Kyllo, so I'm partly to blame as well.",
  ui_story_5037_50371501_99_dialog_content = "Don't worry, PlayerName! We won't leave you out to dry!",
  ui_story_5037_50371501_100_dialog_content = "Thanks, Vice. Thanks, Carleen.",
  ui_story_5037_50371501_101_dialog_content = "That just leaves one last thing to do.",
  ui_story_5037_50371501_102_dialog_content = "We need to find Fia, and make sure she disciplines Kyllo properly.",
  ui_story_5037_50371601_1_dialog_content = "Team PlayerName's final meeting! Three, two, one... Action!",
  ui_story_5037_50371601_2_dialog_content = "Last meeting, huh? Wow, time sure does fly...",
  ui_story_5037_50371601_3_dialog_content = "I know, right? It'll be time for the graduation concert in just a few days!",
  ui_story_5037_50371601_4_dialog_content = "It seems like just yesterday we were moving all of those books here to prepare for our first Producer's Crash Course Workshop.",
  ui_story_5037_50371601_5_dialog_content = "So what's the plan for today?",
  ui_story_5037_50371601_6_dialog_content = "We only have one important task for today... and that's cleaning up the place!",
  ui_story_5037_50371601_7_dialog_content = "After finishing every part of your training plan, you've become a talented and respectable producer, PlayerName!",
  ui_story_5037_50371601_8_dialog_content = "Which means our Producer's Crash Course Workshop has officially come to an end!",
  ui_story_5037_50371601_9_dialog_content = "Indeed, we must gather all our books and materials and return them to their proper places today.",
  ui_story_5037_50371601_10_dialog_content = "That way, we can also return all of the materials we borrowed from others for the workshop.",
  ui_story_5037_50371601_11_dialog_content = "I see. I'll help, too!",
  ui_story_5037_50371601_12_dialog_content = "Let's tidy everything up as quickly as we can!",
  ui_story_5037_50371601_13_dialog_content = "Yeah!",
  ui_story_5037_50371601_14_dialog_content = "<color=#828282>Some time later</color>",
  ui_story_5037_50371601_15_dialog_content = "Where should I put this copy of \"Forming Good Habits: A Beginner's Guide\"?",
  ui_story_5037_50371601_16_dialog_content = "Here, give it to me.",
  ui_story_5037_50371601_17_dialog_content = "Officer Vivian was kind enough to let us borrow it. She said it would be perfect for your training!",
  ui_story_5037_50371601_18_dialog_content = "She herself learned better time management after reading it.",
  ui_story_5037_50371601_19_dialog_content = "She's right, there was tons of useful information in it!",
  ui_story_5037_50371601_20_dialog_content = "PlayerName? Could you hand me that copy of \"300 Essential Choir Skills\" beside you?",
  ui_story_5037_50371601_21_dialog_content = "Sure, here you go.",
  ui_story_5037_50371601_22_dialog_content = "Let me guess... Keating lent us that book, didn't they?",
  ui_story_5037_50371601_23_dialog_content = "How did you know?",
  ui_story_5037_50371601_24_dialog_content = "Because even though the cover looks perfectly clean... There are all sorts of scribbles and drawings on every page's number.",
  ui_story_5037_50371601_25_dialog_content = "There's even a crude drawing of me on one of the pages, where they drew these big, dark circles around my eyes!",
  ui_story_5037_50371601_26_dialog_content = "... Pfft.",
  ui_story_5037_50371601_27_dialog_content = "That does sound like something they would do, yes.",
  ui_story_5037_50371601_28_dialog_content = "If it truly bothers you, I'll have them erase all of their drawings in this book.",
  ui_story_5037_50371601_29_dialog_content = "That's not really necessary...",
  ui_story_5037_50371601_30_dialog_content = "If you make them do that, I'm sure they'll just find an even worse way to make fun of me.",
  ui_story_5037_50371601_31_dialog_content = "Just leave it be.",
  ui_story_5037_50371601_32_dialog_content = "Those kids really know how to get on everyone's nerves.",
  ui_story_5037_50371601_33_dialog_content = "Looks like we're almost done here, right?",
  ui_story_5037_50371601_34_dialog_content = "Yep! Everything is in order!",
  ui_story_5037_50371601_35_dialog_content = "Aside from all the books we used, there's also this huge stack of notes.",
  ui_story_5037_50371601_36_dialog_content = "We accumulated all these notes over the past few days.",
  ui_story_5037_50371601_37_dialog_content = "That's right, every single note-covered page is a testament to all of our hard work!",
  ui_story_5037_50371601_38_dialog_content = "It really is a big stack, huh?",
  ui_story_5037_50371601_39_dialog_content = "It didn't feel like it while we were taking them...",
  ui_story_5037_50371601_40_dialog_content = "but I can't believe we took so many notes!",
  ui_story_5037_50371601_41_dialog_content = "This is the fruit of your acquired knowledge.",
  ui_story_5037_50371601_42_dialog_content = "I gotta say, it's been a long time since I've written this many notes... It felt a lot like our time back at the academy!",
  ui_story_5037_50371601_43_dialog_content = "Going to class, taking notes, getting lunch together... Those were such peaceful days, weren't they, Carleen?",
  ui_story_5037_50371601_44_dialog_content = "Except for when we had exams coming up, of course...",
  ui_story_5037_50371601_45_dialog_content = "Student life, huh? It's pretty hard for me to imagine.",
  ui_story_5037_50371601_46_dialog_content = "After all, I've never attended school before, so I don't know what it's like.",
  ui_story_5037_50371601_47_dialog_content = "Has Soroz always been your teacher, PlayerName?",
  ui_story_5037_50371601_48_dialog_content = "In that case, it really would be difficult to imagine studying with others.",
  ui_story_5037_50371601_49_dialog_content = "It's a lot like our adventures together. Minus the Eclipsites, of course.",
  ui_story_5037_50371601_50_dialog_content = "We should visit Dawn Academy when we get the chance.",
  ui_story_5037_50371601_51_dialog_content = "You can experience life as a student there, just like you experienced life as a producer here.",
  ui_story_5037_50371601_52_dialog_content = "Sure, but... maybe I can skip the exams.",
  ui_story_5037_50371601_53_dialog_content = "We've been so busy lately, I'm starting to feel a little burned out...",
  ui_story_5037_50371601_54_dialog_content = "I don't want to think about contests or exams anymore. Right now, what I want most is to get some decent rest!",
  ui_story_5037_50371601_55_option_content = "But I can't rest just yet!",
  ui_story_5037_50371601_56_dialog_content = "I still have lots of work to do for the final concert.",
  ui_story_5037_50371601_57_dialog_content = "If I start taking it easy now, I won't be able to finish what I started!",
  ui_story_5037_50371601_58_dialog_content = "You always face new experiences with such enthusiasm!",
  ui_story_5037_50371601_59_dialog_content = "Well, yeah... After all, I spent 17 years underground...",
  ui_story_5037_50371601_60_dialog_content = "So you wish to experience everything for yourself, yes?",
  ui_story_5037_50371601_61_dialog_content = "That's right!",
  ui_story_5037_50371601_62_option_content = "I just wanna lay down right now...",
  ui_story_5037_50371601_63_dialog_content = "Everything felt so new and exciting when I first became a producer, but I'm slowly starting to get used to it.",
  ui_story_5037_50371601_64_dialog_content = "Doing the same exact work, day in and day out... I've gotten so familiar with the job, but I can't help but feel a little bored sometimes...",
  ui_story_5037_50371601_65_dialog_content = "I know exactly how you feel...",
  ui_story_5037_50371601_66_dialog_content = "Even the most exciting things become monotonous after a while.",
  ui_story_5037_50371601_67_dialog_content = "Which is why we must always find new ways to challenge ourselves.",
  ui_story_5037_50371601_68_dialog_content = "Still, this has been a valuable experience!",
  ui_story_5037_50371601_69_dialog_content = "I got to help Goldie hold concerts, and I got to study alongside both of you.",
  ui_story_5037_50371601_70_dialog_content = "I couldn't ask for a better way to learn and grow as a person!",
  ui_story_5037_50371601_71_dialog_content = "You could probably make a name for yourself if you stay here and keep being a producer.",
  ui_story_5037_50371601_72_dialog_content = "Which do you like better? Being a producer or being an adventurer?",
  ui_story_5037_50371601_73_dialog_content = "Are you kidding me? My answer should be clear as day!",
  ui_story_5037_50371601_74_dialog_content = "!",
  ui_story_5037_50371601_75_dialog_content = "Adventuring with you guys is what makes me happiest!",
  ui_story_5037_50371701_1_dialog_content = "Florine? I wasn't expecting you here! Welcome, welcome!",
  ui_story_5037_50371701_2_dialog_content = "If you came to hear Goldie sing, I'm afraid I'll have to disappoint you. The concert isn't for a few more days, and she's still in the middle of training.",
  ui_story_5037_50371701_3_dialog_content = "I'm not here to attend the concert.",
  ui_story_5037_50371701_4_dialog_content = "Huh?",
  ui_story_5037_50371701_5_dialog_content = "I'm here to lend my assistance.",
  ui_story_5037_50371701_6_dialog_content = "I hear that you're trying your hand at a new profession? A producer, I believe they called it.",
  ui_story_5037_50371701_7_dialog_content = "I came as your friend to see how you were doing.",
  ui_story_5037_50371701_8_dialog_content = "Tell me, last Caelestite... Is there anything I can do to help you?",
  ui_story_5037_50371701_9_dialog_content = "I don't think so...",
  ui_story_5037_50371701_10_dialog_content = "Is that so...",
  ui_story_5037_50371701_11_dialog_content = "(Huh? Why does Florine look so disappointed?)",
  ui_story_5037_50371701_12_dialog_content = "(Is it because I don't need her help right now...?)",
  ui_story_5037_50371701_13_dialog_content = "W-Wait! There is something I could use a hand with!",
  ui_story_5037_50371701_14_dialog_content = "What is it?",
  ui_story_5037_50371701_15_dialog_content = "(What should I tell her?)",
  ui_story_5037_50371701_16_dialog_content = "(I don't want to disappoint her, but I don't want to bother her, either...)",
  ui_story_5037_50371701_17_dialog_content = "(Wait, didn't she say she used to be student council president? In that case...)",
  ui_story_5037_50371701_18_option_content = "Ask for help with music",
  ui_story_5037_50371701_19_dialog_content = "Goldie's in the process of writing a new song, but it's still missing accompaniment. Maybe you could help her with that?",
  ui_story_5037_50371701_20_dialog_content = "Musical accompaniment? Sorry, but I'm not very familiar with the subject...",
  ui_story_5037_50371701_21_dialog_content = "Although I am a fan of the opera, so I do know just a little. I'll do my best!",
  ui_story_5037_50371701_22_dialog_content = "Great, thanks a lot!",
  ui_story_5037_50371701_23_option_content = "Ask for help with studying",
  ui_story_5037_50371701_24_dialog_content = "Goldie wants me to provide some constructive criticism on her performances, but I don't really understand what she's looking for.",
  ui_story_5037_50371701_25_dialog_content = "I need to learn as much as possible about music as quickly as possible, so I can give her the feedback she needs. Any suggestions?",
  ui_story_5037_50371701_26_dialog_content = "You've come to the right person! I know everything there is to know about systematized self-study, and I'm more than willing to share my knowledge with you!",
  ui_story_5037_50371701_27_dialog_content = "Great! I'm counting on you!",
  ui_story_5037_50371701_28_dialog_content = "<color=#828282>Some time later</color>",
  ui_story_5037_50371701_29_dialog_content = "... There! I've shared all that I know with you.",
  ui_story_5037_50371701_30_dialog_content = "W-Wait, I still haven't got it all down.",
  ui_story_5037_50371701_31_dialog_content = "Let me just check my notes...",
  ui_story_5037_50371701_32_dialog_content = "You write very detailed notes, don't you? That's a very good habit.",
  ui_story_5037_50371701_33_dialog_content = "I always forget things, so I take lots of notes when I'm studying.",
  ui_story_5037_50371701_34_dialog_content = "It's why I keep a diary. I never want to forget all the important things that happen in my life, so I write them down too.",
  ui_story_5037_50371701_35_dialog_content = "I guess for me, a good notebook is worth a thousand memories.",
  ui_story_5037_50371701_36_dialog_content = "Then I wish you the best of luck, last Caelestite.",
  ui_story_5037_50371701_37_dialog_content = "Your hard work and dedication will pave the way to your success.",
  ui_story_5037_50371701_38_dialog_content = "Thanks for the words of encouragement, Florine!",
  ui_story_5037_50371701_39_dialog_content = "These aren't simply words of encouragement.",
  ui_story_5037_50371701_40_dialog_content = "They're not...?",
  ui_story_5037_50371701_41_dialog_content = "They're the culmination of my very own experiences as a student as well.",
  ui_story_5037_50371701_42_dialog_content = "Hard work and dedication are the means by which an ordinary person can accomplish the extraordinary... So never underestimate the value of hard work.",
  ui_story_5037_50371701_43_dialog_content = "I see! And I won't!",
  ui_story_5037_50371701_44_dialog_content = "Anyway, how come you're still wearing all that old-era stuff? Don't you want to change it?",
  ui_story_5037_50371701_45_dialog_content = "No, not really. It's really light and comfortable. And it reminds me of my school days.",
  ui_story_5037_50371701_46_dialog_content = "Wearing it means I'm always reminded...",
  ui_story_5037_50371701_47_dialog_content = "to be more like a student. To be humble, and have integrity. Always strive for improvement, and become a responsible individual.",
  ui_story_5037_50371701_48_dialog_content = "You could try wearing it too, PlayerName. I'm sure it would be inspirational.",
  ui_story_5037_50371701_49_dialog_content = "Umm... I think I'll pass!",
  ui_story_5037_50371701_50_dialog_content = "I'm far more comfortable in my own clothes.",
  ui_story_5037_50371701_51_dialog_content = "Well then, as you will.",
  ui_story_5037_50371701_52_dialog_content = "You'll be fine so long as you always do your best and don't be lazy.",
  ui_story_5037_50371701_53_dialog_content = "Sure you're not too hard on yourself, Florine?",
  ui_story_5037_50371701_54_dialog_content = "Hard on myself? I don't think so.",
  ui_story_5037_50371701_55_dialog_content = "I just want to be able to help everyone, like Miss Hedy.",
  ui_story_5037_50371701_56_dialog_content = "As long as I can become as reliable as her, I'll do my best, no matter the difficulties I may face.",
  ui_story_5037_50371701_57_dialog_content = "I still have room to improve.",
  ui_story_5037_50371701_58_dialog_content = "I think you're awesome just the way you are now!",
  ui_story_5037_50371701_59_dialog_content = "Being able to persevere so tenaciously all the time is really impressive.",
  ui_story_5037_50371701_60_dialog_content = "I'd love to be more like you.",
  ui_story_5037_50371701_61_dialog_content = "Well, let's both work hard to become who we want to be.",
  ui_story_5037_50371701_62_dialog_content = "Deal!",
  ui_story_5037_50371701_63_dialog_content = "Oh, one more thing. Remind Goldie to stay hydrated and look after herself.",
  ui_story_5037_50371701_64_dialog_content = "Singing for so long places quite a strain on the throat, so it's important to drink plenty of water to avoid irritation.",
  ui_story_5037_50371701_65_dialog_content = "Dancing is also a pretty vigorous exercise, so regular hydration is critical.",
  ui_story_5037_50371701_66_dialog_content = "No worries. I'll be sure to remind her.",
  ui_story_5037_50371701_67_dialog_content = "Don't forget to look after yourself too, last Caelestite.",
  ui_story_5037_50371701_68_dialog_content = "No matter how busy work is, you must find time to look after yourself.",
  ui_story_5037_50371701_69_dialog_content = "Okay...",
  ui_story_5037_50371701_70_dialog_content = "May the God of Light bless you, and smooth the path of your future endeavors.",
  ui_story_5037_50371701_71_dialog_content = "Yup!",
  ui_story_5037_50371801_1_dialog_content = "Oh, I can't miss this! Cellulo, get a good shot of Goldie, PlayerName, and me!",
  ui_story_5037_50371801_2_dialog_content = "3... 2... 1... Action!",
  ui_story_5037_50371801_3_dialog_content = "Hi guys! It's your intrepid director, Lilica!",
  ui_story_5037_50371801_4_dialog_content = "Today I'm taking on the role of a mentor in a collaboration with Goldie and her producer PlayerName.",
  ui_story_5037_50371801_5_dialog_content = "We're going to go through some performing arts training!",
  ui_story_5037_50371801_6_dialog_content = "Say hi to the folks watching at home, Goldie, PlayerName!",
  ui_story_5037_50371801_7_dialog_content = "Hi to all my adorable fans out there!",
  ui_story_5037_50371801_8_dialog_content = "H-hi, everyone...",
  ui_story_5037_50371801_9_dialog_content = "(Knowing that my performance is gonna be recorded and watched by so many people is really unnerving...)",
  ui_story_5037_50371801_10_dialog_content = "I prepared a special game to help us out with today's training!",
  ui_story_5037_50371801_11_dialog_content = "A game? Awesome, I love games!",
  ui_story_5037_50371801_12_dialog_content = "What sort of game is it?",
  ui_story_5037_50371801_13_dialog_content = "It's called \"Charades.\"",
  ui_story_5037_50371801_14_dialog_content = "One's costume, makeup, lines, and expression all affect the outcome of one's performance.",
  ui_story_5037_50371801_15_dialog_content = "What an actor can do is deepen their understanding of the character as much as possible and make sure their manner and their lines fit!",
  ui_story_5037_50371801_16_dialog_content = "Sounds about right!",
  ui_story_5037_50371801_17_dialog_content = "I observed a lot of your companions and wrote a few lines based off their individual characteristics.",
  ui_story_5037_50371801_18_dialog_content = "During the game, Goldie will pick one of them and imitate their mannerisms.",
  ui_story_5037_50371801_19_dialog_content = "Then, PlayerName, you'll guess who Goldie is imitating!",
  ui_story_5037_50371801_20_dialog_content = "Her performance will be considered a success if you manage to get it right!",
  ui_story_5037_50371801_21_dialog_content = "Sounds like fun!",
  ui_story_5037_50371801_22_dialog_content = "I see!",
  ui_story_5037_50371801_23_dialog_content = "Since Goldie's a newcomer, we'll make it multiple choice. You just have to choose the right answer.",
  ui_story_5037_50371801_24_dialog_content = "Anyway, I'm sure it won't be too difficult, so let's have fun!",
  ui_story_5037_50371801_25_dialog_content = "Alright!",
  ui_story_5037_50371801_26_dialog_content = "Just you wait for my performance!",
  ui_story_5037_50371801_27_dialog_content = "Goldie, please select someone from this list. Then the stage is yours.",
  ui_story_5037_50371801_28_dialog_content = "Okay... This one!",
  ui_story_5037_50371801_29_dialog_content = "I'm gonna begin, PlayerName.",
  ui_story_5037_50371801_30_dialog_content = "\"Hey, kid!\"",
  ui_story_5037_50371801_31_dialog_content = "(That tone sounds really familiar...!)",
  ui_story_5037_50371801_32_dialog_content = "\"Ready to go hunt something with me?\"",
  ui_story_5037_50371801_33_dialog_content = "Ready to guess who Goldie's impersonating, PlayerName?",
  ui_story_5037_50371801_34_option_content = "Barton?",
  ui_story_5037_50371801_35_dialog_content = "Ohhh, that's close but not quite right!",
  ui_story_5037_50371801_36_dialog_content = "The correct answer is... Sinsa!",
  ui_story_5037_50371801_37_dialog_content = "I can't believe I got it wrong.",
  ui_story_5037_50371801_38_dialog_content = "Was it my acting? I'll do better next time!",
  ui_story_5037_50371801_39_option_content = "Sinsa?",
  ui_story_5037_50371801_40_dialog_content = "Correct!",
  ui_story_5037_50371801_41_dialog_content = "Seems like Goldie's performance was very convincing!",
  ui_story_5037_50371801_42_dialog_content = "It really was! It was totally like Sinsa!",
  ui_story_5037_50371801_43_dialog_content = "I could have sworn you were about to pull out a big red wrench...",
  ui_story_5037_50371801_44_dialog_content = "Uh... I'll take that as a compliment?",
  ui_story_5037_50371801_45_option_content = "Kleken?",
  ui_story_5037_50371801_46_dialog_content = "That's... totally wrong!",
  ui_story_5037_50371801_47_dialog_content = "The correct answer is... Sinsa!",
  ui_story_5037_50371801_48_dialog_content = "You've gotta watch Goldie's performance more carefully, PlayerName!",
  ui_story_5037_50371801_49_dialog_content = "I-I'm sorry...",
  ui_story_5037_50371801_50_dialog_content = "I should try harder too!",
  ui_story_5037_50371801_51_dialog_content = "We're ramping up the difficulty for this next one!",
  ui_story_5037_50371801_52_dialog_content = "Goldie, let's see you imitate this person!",
  ui_story_5037_50371801_53_dialog_content = "Wow... They're pretty different from me, but I'll try my best!",
  ui_story_5037_50371801_54_dialog_content = "\"What are you doing, young one?\"",
  ui_story_5037_50371801_55_dialog_content = "(Who's she playing this time...?)",
  ui_story_5037_50371801_56_dialog_content = "\"Could you bring my tea to my room if you have a minute? I'm too lazy to go fetch it myself.\"",
  ui_story_5037_50371801_57_dialog_content = "Have a guess, PlayerName!",
  ui_story_5037_50371801_58_option_content = "Migard?",
  ui_story_5037_50371801_59_dialog_content = "Correct!",
  ui_story_5037_50371801_60_dialog_content = "That really was pretty tough...",
  ui_story_5037_50371801_61_dialog_content = "It was tough for me too. Her bearing and mannerisms are pretty hard to express.",
  ui_story_5037_50371801_62_dialog_content = "I got it right though! I think that shows Goldie's performance was a success!",
  ui_story_5037_50371801_63_option_content = "The City Lord?",
  ui_story_5037_50371801_64_dialog_content = "Well, from an age perspective, he certainly could call you young one...",
  ui_story_5037_50371801_65_dialog_content = "But the correct answer is Migard!",
  ui_story_5037_50371801_66_dialog_content = "I need to try harder...",
  ui_story_5037_50371801_67_dialog_content = "No, maybe I need to pay more attention...",
  ui_story_5037_50371801_68_option_content = "Tweety?",
  ui_story_5037_50371801_69_dialog_content = "Nope! How could Tweety call you young one when she's still so young herself?!",
  ui_story_5037_50371801_70_dialog_content = "The correct answer is Migard!",
  ui_story_5037_50371801_71_dialog_content = "Even though she's a gorgeous woman, she still has a lot of the mannerisms of an old man...",
  ui_story_5037_50371801_72_dialog_content = "I-Indeed...",
  ui_story_5037_50371801_73_dialog_content = "I always feel like I'm being scrutinized when I see her!",
  ui_story_5037_50371801_74_dialog_content = "Let's try harder for the next one, PlayerName!",
  ui_story_5037_50371801_75_dialog_content = "Next up, our final challenge!",
  ui_story_5037_50371801_76_dialog_content = "Goldie, please become this person!",
  ui_story_5037_50371801_77_dialog_content = "Huh?! I-is this really okay?",
  ui_story_5037_50371801_78_dialog_content = "Of course! You're free to act as you see fit!",
  ui_story_5037_50371801_79_dialog_content = "Alright... Here I go!",
  ui_story_5037_50371801_80_dialog_content = "\"PlayerName...\"",
  ui_story_5037_50371801_81_dialog_content = "(Has she already started?!)",
  ui_story_5037_50371801_82_dialog_content = "\"Let's give it our all today as well!\"",
  ui_story_5037_50371801_83_dialog_content = "Alright, PlayerName. What's your guess?",
  ui_story_5037_50371801_84_option_content = "Lilica?",
  ui_story_5037_50371801_85_dialog_content = "It did resemble Lilica! But it's not her.",
  ui_story_5037_50371801_86_dialog_content = "It's not? Really?",
  ui_story_5037_50371801_87_dialog_content = "The answer is right in front of your eyes, PlayerName!",
  ui_story_5037_50371801_88_dialog_content = "Were you... acting yourself?!",
  ui_story_5037_50371801_89_dialog_content = "Correct!",
  ui_story_5037_50371801_90_option_content = "Goldie?",
  ui_story_5037_50371801_91_dialog_content = "Bingo!",
  ui_story_5037_50371801_92_dialog_content = "I really didn't expect you to get it right!",
  ui_story_5037_50371801_93_dialog_content = "It sounded so energetic, just like how you usually are.",
  ui_story_5037_50371801_94_dialog_content = "I'm just a little confused why you used her?",
  ui_story_5037_50371801_95_dialog_content = "A producer's own perception of their actor's performance will influence their training.",
  ui_story_5037_50371801_96_dialog_content = "Apart from understanding the roles, the best producers also have another skill...",
  ui_story_5037_50371801_97_dialog_content = "They know the characteristics and strengths of their actors themselves!",
  ui_story_5037_50371801_98_dialog_content = "Only this allows for bespoke, targeted training.",
  ui_story_5037_50371801_99_dialog_content = "So that final challenge was actually meant as a test for you!",
  ui_story_5037_50371801_100_dialog_content = "So that's what it was all about! I understand now.",
  ui_story_5037_50371801_101_dialog_content = "I learned a lot too!",
  ui_story_5037_50371801_102_dialog_content = "There are so many differences between each role. I've gotta keep working hard!",
  ui_story_5037_50371801_103_dialog_content = "That's it for today's training! We wish both of you the best!",
  ui_story_5037_50371801_104_dialog_content = "Don't forget to put what you learned today into practice!",
  ui_story_5037_50371801_105_dialog_content = "Got it!",
  ui_story_5037_50371801_106_dialog_content = "Yes, Director Lilica!",
  ui_story_5037_50371901_1_dialog_content = "So, what exactly is a Cloud Island priestess like?",
  ui_story_5037_50371901_2_dialog_content = "I hear that the priestesses are amazing dancers, graceful and mysterious, and also highly skilled in Luminatics.",
  ui_story_5037_50371901_3_dialog_content = "My imagination is just running wild!",
  ui_story_5037_50371901_4_dialog_content = "You'll get to see for yourself very soon!",
  ui_story_5037_50371901_5_dialog_content = "I managed to carve out some time to come to your Colossus just for this meeting!",
  ui_story_5037_50371901_6_dialog_content = "My heart started racing the second I heard that I had the chance to ask a real priestess for dancing tips!",
  ui_story_5037_50371901_7_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5037_50371901_8_dialog_content = "My apologies for keeping you both waiting.",
  ui_story_5037_50371901_9_dialog_content = "Not at all! I'm just so grateful that you came all the way from Cloud Island to coach us!",
  ui_story_5037_50371901_10_dialog_content = "You must be Goldie, right?",
  ui_story_5037_50371901_11_dialog_content = "Yes! Hello Rinne, I'm Goldie, an idol.",
  ui_story_5037_50371901_12_dialog_content = "Hi, Goldie. I'm Rinne, a priestess from Cloud Island.",
  ui_story_5037_50371901_13_dialog_content = "Is an idol the same as a singer?",
  ui_story_5037_50371901_14_dialog_content = "There are some differences. Aside from singing, I also need to learn other skills, like dancing and acting!",
  ui_story_5037_50371901_15_dialog_content = "I see. And that's why you wish to learn the kagura dance?",
  ui_story_5037_50371901_16_dialog_content = "Yes! Can you teach me, Rinne?",
  ui_story_5037_50371901_17_dialog_content = "Of course! Why don't I dance for you now, as a little demonstration?",
  ui_story_5037_50371901_18_dialog_content = "Really?! Oh, yes! I can't believe I get to actually witness a priestess doing a kagura dance!",
  ui_story_5037_50371901_19_dialog_content = "Hehe...",
  ui_story_5037_50371901_20_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5037_50371901_21_dialog_content = "<color=#828282>Ding...</color>",
  ui_story_5037_50371901_22_dialog_content = "Stunning...",
  ui_story_5037_50371901_23_dialog_content = "The sound of the bells and the sight of Rinne's dance fills me with serenity...",
  ui_story_5037_50371901_24_dialog_content = "These are just a few of the basic kagura steps. Would you like to have a go, Goldie?",
  ui_story_5037_50371901_25_dialog_content = "Yeah!",
  ui_story_5037_50371901_26_dialog_content = "Is this right?",
  ui_story_5037_50371901_27_dialog_content = "Well done. You've got the movements down perfectly!",
  ui_story_5037_50371901_28_dialog_content = "I'm pretty confident in my mirroring skills!",
  ui_story_5037_50371901_29_dialog_content = "But still, I can't help but feel like my kagura is missing something...",
  ui_story_5037_50371901_30_dialog_content = "True, it doesn't give off the same calming feel that Rinne's does.",
  ui_story_5037_50371901_31_dialog_content = "Miss Rinne, do you use some kind of special Luminatics when you dance?",
  ui_story_5037_50371901_32_dialog_content = "Not at all. I am not using any Luminatics. It's only dance, nothing more.",
  ui_story_5037_50371901_33_dialog_content = "So what exactly am I doing differently?",
  ui_story_5037_50371901_34_dialog_content = "May I inquire what you were thinking while you were dancing?",
  ui_story_5037_50371901_35_dialog_content = "What I was thinking...?",
  ui_story_5037_50371901_36_dialog_content = "Lots of things, like if my moves were right, and what comes next...",
  ui_story_5037_50371901_37_dialog_content = "It was my first time dancing kagura, so I was worrying about getting it right.",
  ui_story_5037_50371901_38_dialog_content = "Ahh... Perhaps that is the source of the problem.",
  ui_story_5037_50371901_39_dialog_content = "Kagura is a dance for the gods. When you move, your thoughts must only be with the divine.",
  ui_story_5037_50371901_40_dialog_content = "Only then can your heart be expressed through the dance.",
  ui_story_5037_50371901_41_dialog_content = "Oh...! Alright, I think I understand!",
  ui_story_5037_50371901_42_dialog_content = "That was fast!",
  ui_story_5037_50371901_43_dialog_content = "It's kinda similar to how I usually perform!",
  ui_story_5037_50371901_44_dialog_content = "My fans are the only things I think about when I'm singing or dancing, and how much I hope I'm bringing them joy.",
  ui_story_5037_50371901_45_dialog_content = "When I'm in the zone like that, my vocals and movements seem to flow almost effortlessly.",
  ui_story_5037_50371901_46_dialog_content = "The dances may be different, but some things are the same.",
  ui_story_5037_50371901_47_dialog_content = "Would you try the dance again, bearing that all in mind?",
  ui_story_5037_50371901_48_dialog_content = "Yes!",
  ui_story_5037_50371901_49_dialog_content = "Think only of my fans...",
  ui_story_5037_50371901_50_dialog_content = "(That's amazing! It's a totally different vibe compared to the first time!)",
  ui_story_5037_50371901_51_dialog_content = "(But there still seems to be some differences between Goldie's dance and Rinne's.)",
  ui_story_5037_50371901_52_dialog_content = "What do you think, Rinne? PlayerName?",
  ui_story_5037_50371901_53_option_content = "It's a lot more like Rinne's!",
  ui_story_5037_50371901_54_dialog_content = "Really? That's great!",
  ui_story_5037_50371901_55_dialog_content = "Hmm... There are still some differences.",
  ui_story_5037_50371901_56_dialog_content = "Oh?",
  ui_story_5037_50371901_57_option_content = "Your version of the dance has its own charm!",
  ui_story_5037_50371901_58_dialog_content = "Oh?",
  ui_story_5037_50371901_59_dialog_content = "Your dance felt a little livelier, a little lighter.",
  ui_story_5037_50371901_60_dialog_content = "Goldie and I are dancing for different people, after all.",
  ui_story_5037_50371901_61_dialog_content = "Goldie's dance is for an enthusiastic, passionate audience.",
  ui_story_5037_50371901_62_dialog_content = "Identical movements can convey very different emotions according to each individual.",
  ui_story_5037_50371901_63_dialog_content = "This is not a bad thing and is entirely natural, so there's no need to worry about it.",
  ui_story_5037_50371901_64_dialog_content = "Your mind and your moves are yours alone.",
  ui_story_5037_50371901_65_dialog_content = "Okay!",
  ui_story_5037_50371901_66_dialog_content = "Thank you for your guidance!",
  ui_story_5037_50372001_1_dialog_content = "Seeing as we're somewhere else today, I need to start filming. Watch your expressions, guys.",
  ui_story_5037_50372001_2_dialog_content = "3... 2... 1... Action!",
  ui_story_5037_50372001_3_dialog_content = "Are we rolling? *Cough*...",
  ui_story_5037_50372001_4_dialog_content = "My vocal class begins now.",
  ui_story_5037_50372001_5_dialog_content = "Hi, Nina!",
  ui_story_5037_50372001_6_dialog_content = "I'm a little confused...",
  ui_story_5037_50372001_7_dialog_content = "Aren't we supposed to have vocal training right now? What are we doing at the concert hall?",
  ui_story_5037_50372001_8_dialog_content = "An excellent question, PlayerName.",
  ui_story_5037_50372001_9_dialog_content = "This lesson will not be active but passive. Today we are listening.",
  ui_story_5037_50372001_10_dialog_content = "Listening...?",
  ui_story_5037_50372001_11_dialog_content = "Listening to other artists' songs is an important part of an idol's training!",
  ui_story_5037_50372001_12_dialog_content = "We need to know what fans currently like if we want to make music that people want to listen to.",
  ui_story_5037_50372001_13_dialog_content = "Yep! Know the trend, follow the trend, and lead the trend. This is the lifeblood of the industry!",
  ui_story_5037_50372001_14_dialog_content = "So, today we're going to listen to a musical called \"Phantom of the Theatre.\"",
  ui_story_5037_50372001_15_dialog_content = "It tells the tale of an immortal stage actor.",
  ui_story_5037_50372001_16_dialog_content = "The changing plays performed provides a throughline that links together each era of Umbraton.",
  ui_story_5037_50372001_17_dialog_content = "That's amazing!",
  ui_story_5037_50372001_18_dialog_content = "Popular culture is a reflection of the zeitgeist, after all!",
  ui_story_5037_50372001_19_dialog_content = "Excellent, ten points for Goldie.",
  ui_story_5037_50372001_20_dialog_content = "Hand out the material please, Minos.",
  ui_story_5037_50372001_21_dialog_content = "Yes, Miss.",
  ui_story_5037_50372001_22_dialog_content = "What's this...?",
  ui_story_5037_50372001_23_dialog_content = "Miss specially prepared this herself. It lists all the popular songs and operas of Umbraton over the past decade.",
  ui_story_5037_50372001_24_dialog_content = "Make sure to look after it.",
  ui_story_5037_50372001_25_dialog_content = "O-Okay...",
  ui_story_5037_50372001_26_dialog_content = "In this class, you will learn about each of these songs, as well as the trends in Umbraton over the last ten years.",
  ui_story_5037_50372001_27_dialog_content = "This should refine your taste, and help you record more on-trend songs.",
  ui_story_5037_50372001_28_dialog_content = "Nina, I appreciate your efforts, but...",
  ui_story_5037_50372001_29_dialog_content = "Surely this is way too much?!",
  ui_story_5037_50372001_30_dialog_content = "You can't expect us to read them all today?",
  ui_story_5037_50372001_31_dialog_content = "Read them all? No, of course not! I'd never set such an impossible task. It would hardly be reasonable.",
  ui_story_5037_50372001_32_dialog_content = "Each of these songs will be referenced in what we're watching today.",
  ui_story_5037_50372001_33_dialog_content = "You can refer to the comprehensive list I put together, in order to gain a deeper understanding of how pop culture differed between the eras.",
  ui_story_5037_50372001_34_dialog_content = "Thank you so much!",
  ui_story_5037_50372001_35_dialog_content = "We'll study it closely!",
  ui_story_5037_50372001_36_dialog_content = "The performance is about to start, so we should hurry up and take our seats.",
  ui_story_5037_50372001_37_dialog_content = "This way, everyone.",
  ui_story_5037_50372001_38_dialog_content = "Miss kindly procured VIP seats for you.",
  ui_story_5037_50372001_39_dialog_content = "Wow, so close to the stage! We probably have the best view of the performance in the whole place!",
  ui_story_5037_50372001_40_dialog_content = "<color=#828282>...</color>",
  ui_story_5037_50372001_41_dialog_content = "\"Happy times, beautiful music... All are fleeting.\"",
  ui_story_5037_50372001_42_dialog_content = "\"Beautiful lady, might you do me the honor of a dance?\"",
  ui_story_5037_50372001_43_dialog_content = "This is \"Kleo and Jessica,\" one of Umbraton's earliest plays.",
  ui_story_5037_50372001_44_dialog_content = "I know this one! I heard the story when I was a kid, adapted from the play!",
  ui_story_5037_50372001_45_dialog_content = "It tells the tragic tale of two Aurorians from rival families who fall in love with each other.",
  ui_story_5037_50372001_46_dialog_content = "That's right. As you can see, during this time, Umbraton culture was heavily influenced by Lumopolis.",
  ui_story_5037_50372001_47_dialog_content = "We can learn a lot about the lives and habits of contemporary Lumo Nobles from this, such as...",
  ui_story_5037_50372001_48_dialog_content = "(Nina and Goldie are really getting on.)",
  ui_story_5037_50372001_49_dialog_content = "(The play's alright, but I don't really know much about the history of Lumopolis or Umbraton...)",
  ui_story_5037_50372001_50_dialog_content = "(I'm sleepy... I can't help it, watching something I don't really understand just makes me yawn...)",
  ui_story_5037_50372001_51_dialog_content = "(But Nina went to a lot of trouble to arrange all this...)",
  ui_story_5037_50372001_52_option_content = "Don't give in to fatigue.",
  ui_story_5037_50372001_53_dialog_content = "(No, I can't sleep. I've gotta see this through to the end!)",
  ui_story_5037_50372001_54_dialog_content = "(This is priceless reference material!)",
  ui_story_5037_50372001_55_dialog_content = "<color=#828282>After painstakingly staying awake till the end of the performance</color>",
  ui_story_5037_50372001_56_dialog_content = "I had absolutely no idea quite how complicated Umbraton's cultural development was until right now!",
  ui_story_5037_50372001_57_dialog_content = "I learned a lot too!",
  ui_story_5037_50372001_58_dialog_content = "Even though I wasn't really familiar with the content...",
  ui_story_5037_50372001_59_dialog_content = "Don't worry! I've already highlighted the pertinent points in the material.",
  ui_story_5037_50372001_60_dialog_content = "You can flip through to refresh your memories whenever you want.",
  ui_story_5037_50372001_61_dialog_content = "Wow, thanks again for taking the time to do this for us, Nina!",
  ui_story_5037_50372001_62_option_content = "Surrender to slumber.",
  ui_story_5037_50372001_63_dialog_content = "(Gotta stay awake... Gotta stay... Zzzz...)",
  ui_story_5037_50372001_64_dialog_content = "<color=#828282>Who knows how long later...</color>",
  ui_story_5037_50372001_65_dialog_content = "PlayerName? PlayerName!",
  ui_story_5037_50372001_66_dialog_content = "Let me try, Miss Goldie.",
  ui_story_5037_50372001_67_dialog_content = "Will you please wake up, PlayerName!",
  ui_story_5037_50372001_68_dialog_content = "Eh?!",
  ui_story_5037_50372001_69_dialog_content = "Why are you sleeping? The show's already over.",
  ui_story_5037_50372001_70_dialog_content = "What? It's over?!",
  ui_story_5037_50372001_71_dialog_content = "I was too engrossed in explaining things for Goldie that I didn't even notice you'd fallen asleep...",
  ui_story_5037_50372001_72_dialog_content = "It's terribly offensive to spurn Miss' kindness...",
  ui_story_5037_50372001_73_dialog_content = "I-I'm sorry!",
  ui_story_5037_50372001_74_dialog_content = "It was my mistake...",
  ui_story_5037_50372001_75_dialog_content = "It's alright.",
  ui_story_5037_50372001_76_dialog_content = "It's a shame you missed the chance to increase your knowledge while enjoying a performance.",
  ui_story_5037_50372001_77_dialog_content = "But luckily for you, I already highlighted the pertinent points in the material.",
  ui_story_5037_50372001_78_dialog_content = "You'll pick some things up, provided you actually review it.",
  ui_story_5037_50372001_79_dialog_content = "I'll read it all super carefully! And won't fall asleep!",
  ui_story_5037_50372001_80_dialog_content = "I hope you all gained something from this performance.",
  ui_story_5037_50372001_81_dialog_content = "Knowing what the public wants is the key to popular culture. You cannot just bury your head in the sand and ignore it.",
  ui_story_5037_50372001_82_dialog_content = "This is all the help I am able to offer you. From here on, it's up to you two to put the effort in.",
  ui_story_5037_50372001_83_dialog_content = "Thank you, Miss Nina, Minos!",
  ui_story_5037_50372001_84_dialog_content = "Yes, thank you!",
  ui_story_5037_50372101_1_dialog_content = "Fleur, thank you for mentoring Goldie and me—",
  ui_story_5037_50372101_2_dialog_content = "Shhh!",
  ui_story_5037_50372101_3_dialog_content = "Eh? Why are you leaning against the door, Fleur?",
  ui_story_5037_50372101_4_dialog_content = "Please, PlayerName, Goldie... I must trouble you to be quiet for a second...",
  ui_story_5037_50372101_5_dialog_content = "...",
  ui_story_5037_50372101_6_dialog_content = "...",
  ui_story_5037_50372101_7_dialog_content = "Phew... Looks like those guys have gone.",
  ui_story_5037_50372101_8_dialog_content = "Don't tell me you've gotten yourself into trouble again?",
  ui_story_5037_50372101_9_dialog_content = "Well...",
  ui_story_5037_50372101_10_dialog_content = "I mean, on the way here, I said hi to a few people I'd previously helped...",
  ui_story_5037_50372101_11_dialog_content = "Hello.",
  ui_story_5037_50372101_12_dialog_content = "Huh? Why, if it isn't Fleur! Thank you so much for your help the other day!",
  ui_story_5037_50372101_13_dialog_content = "But then, after hearing my name, more and more people came over...",
  ui_story_5037_50372101_14_dialog_content = "What? Fleur's here? I really owe you one for the last time!",
  ui_story_5037_50372101_15_dialog_content = "Fleur!! I'm a massive fan!!!",
  ui_story_5037_50372101_16_dialog_content = "It took ages for me to escape the throng of adoring fans. I even had to take the long route just to make sure no one was following me...",
  ui_story_5037_50372101_17_dialog_content = "Sometimes it's a hassle being so popular...",
  ui_story_5037_50372101_18_dialog_content = "I'm so jealous, I wish I were as popular as you!",
  ui_story_5037_50372101_19_dialog_content = "It's really very draining.",
  ui_story_5037_50372101_20_dialog_content = "That wouldn't bother me at all!",
  ui_story_5037_50372101_21_dialog_content = "It would be amazing to attract more fans to enjoy my dancing and singing!",
  ui_story_5037_50372101_22_dialog_content = "If that's what you want, I have no objections.",
  ui_story_5037_50372101_23_dialog_content = "It's just that I'm only popular thanks to my special constitution.",
  ui_story_5037_50372101_24_dialog_content = "It's not just something that can be taught...",
  ui_story_5037_50372101_25_dialog_content = "Really?",
  ui_story_5037_50372101_26_dialog_content = "And to be honest, I don't really know precisely how one becomes popular either.",
  ui_story_5037_50372101_27_dialog_content = "Thanks to my peculiarity, I spend most of my time studying how to become inconspicuous or even disliked.",
  ui_story_5037_50372101_28_dialog_content = "I can't believe it...",
  ui_story_5037_50372101_29_dialog_content = "What should we do, then?",
  ui_story_5037_50372101_30_dialog_content = "I know!",
  ui_story_5037_50372101_31_dialog_content = "Have you come up with something?",
  ui_story_5037_50372101_32_dialog_content = "Well, since Fleur's already thought long and hard about how to become UNpopular, why don't we just do the complete opposite?",
  ui_story_5037_50372101_33_dialog_content = "You mean, get Fleur to teach you his tactics, then reverse them?",
  ui_story_5037_50372101_34_dialog_content = "So make the method for unpopularity into one for popularity instead?",
  ui_story_5037_50372101_35_dialog_content = "Correct! This is why you're my producer, you catch on so quickly!",
  ui_story_5037_50372101_36_dialog_content = "Do you really think that'll work?",
  ui_story_5037_50372101_37_dialog_content = "We'll never know if we don't try, right? Would you teach me, Fleur? Please?",
  ui_story_5037_50372101_38_dialog_content = "Okay... Do you guys wanna learn how to be inconspicuous, or how to be actively disliked?",
  ui_story_5037_50372101_39_dialog_content = "What do you think, PlayerName?",
  ui_story_5037_50372101_40_dialog_content = "(Since we'll be reversing it, surely the more people dislike you, the more they will like you when flipped?)",
  ui_story_5037_50372101_41_option_content = "How to be inconspicuous",
  ui_story_5037_50372101_42_dialog_content = "Becoming inconspicuous is actually quite simple: the trick is to just be like other people.",
  ui_story_5037_50372101_43_dialog_content = "All you gotta do is act like others do while concealing whatever distinguishing features make you stand out, and that's it!",
  ui_story_5037_50372101_44_dialog_content = "You make it sound easy!",
  ui_story_5037_50372101_45_dialog_content = "You generally won't draw attention to yourself if you wear ordinary, boring clothes and walk around with your head down.",
  ui_story_5037_50372101_46_dialog_content = "Some people even wear hats, which can help hide their faces!",
  ui_story_5037_50372101_47_dialog_content = "So then the opposite of that would be... Walking around with my head held high, showing off my singing and dancing?",
  ui_story_5037_50372101_48_dialog_content = "It sounds a little weird, but since you sing and dance really well...",
  ui_story_5037_50372101_49_dialog_content = "It should be enough, right?",
  ui_story_5037_50372101_50_option_content = "How to be disliked",
  ui_story_5037_50372101_51_dialog_content = "It's a little tricky to make people actively dislike you.",
  ui_story_5037_50372101_52_dialog_content = "I've tried loads of different things, like sneaking around suspiciously, dressing in rags, or making my face dirty.",
  ui_story_5037_50372101_53_dialog_content = "I had some success, although I was mistaken for a thief a couple of times...",
  ui_story_5037_50372101_54_dialog_content = "But because of my particular problem, once people saw who I really was, no amount of subterfuge would work.",
  ui_story_5037_50372101_55_dialog_content = "I've got it.",
  ui_story_5037_50372101_56_dialog_content = "So the opposite would be to have a dignified posture, dress well, and look good, right?",
  ui_story_5037_50372101_57_dialog_content = "And always being positive and flashing an idol's smile wherever I go!",
  ui_story_5037_50372101_58_dialog_content = "That's gotta work!",
  ui_story_5037_50372101_59_dialog_content = "Don't forget that your bearing is an important factor in whichever method you use.",
  ui_story_5037_50372101_60_dialog_content = "You're an excellent dancer, Goldie, so you should know this already.",
  ui_story_5037_50372101_61_dialog_content = "Totally! Bearing and posture are crucial when dancing. The difference between standing upright and having a hunched back when you dance is extreme.",
  ui_story_5037_50372101_62_dialog_content = "Anyway, thank you so much, Fleur!",
  ui_story_5037_50372101_63_dialog_content = "My pleasure. If there's anything else I can help with, don't hesitate to let me know.",
  ui_story_5037_50372101_64_dialog_content = "I bet part of the reason you're so popular is that you're always so willing to help people.",
  ui_story_5037_50372101_65_dialog_content = "Y-you think??",
  ui_story_5037_50372101_66_dialog_content = "But I can't just ignore people who need help...",
  ui_story_5037_50372101_67_dialog_content = "And that's a great thing, definitely don't change that!",
  ui_story_5037_50372101_68_dialog_content = "Alright, got it.",
  ui_story_5037_50372101_69_dialog_content = "Thank you, PlayerName.",
  ui_story_5037_50372101_70_dialog_content = "People always like those who help others, and do good deeds!",
  ui_story_5037_50372101_71_dialog_content = "PlayerName, we should go try out what we've learned!",
  ui_story_5037_50372101_72_dialog_content = "Now?!",
  ui_story_5037_50372101_73_dialog_content = "We should strike while the iron is hot! Let's go—",
  ui_story_5037_50372101_74_dialog_content = "Hang on a minute, Goldie! Don't open the door yet!",
  ui_story_5037_50372101_75_dialog_content = "Oh?",
  ui_story_5037_50372101_76_dialog_content = "<color=#828282>Creak—</color>",
  ui_story_5037_50372101_77_dialog_content = "(There are loads of people outside!)",
  ui_story_5037_50372101_78_dialog_content = "Where's Fleur?",
  ui_story_5037_50372101_79_dialog_content = "I thought I just heard someone shouting his name!",
  ui_story_5037_50372101_80_dialog_content = "Fleuurrrr! Why are you running?!",
  ui_story_5037_50372101_81_dialog_content = "Please, everyone, calm down...",
  ui_story_5037_50372101_82_dialog_content = "WE LOVE YOU!!",
  ui_story_5037_50372101_83_dialog_content = "Wow! You really do attract them!",
  ui_story_5037_50372101_84_dialog_content = "Popularity does seem like it can be a hassle...",
  ui_story_5037_50372201_1_dialog_content = "\"It's lonely at the top.\"",
  ui_story_5037_50372201_2_dialog_content = "\"Eating, drinking, and sleeping alone... This is the source of their art.\"",
  ui_story_5037_50372201_3_dialog_content = "\"Knowing this, know too that loneliness is not an enemy but a friend, a constant companion!\"",
  ui_story_5037_50372201_4_dialog_content = "Amazing!",
  ui_story_5037_50372201_5_dialog_content = "Isn't that a line from \"Interview with the Famous\"?",
  ui_story_5037_50372201_6_dialog_content = "Thank you, young lady. That you enjoy my performance speaks volumes about your artistic tastes.",
  ui_story_5037_50372201_7_dialog_content = "Hang on, Charon. Could you explain something...?",
  ui_story_5037_50372201_8_dialog_content = "How did a whole Eraveil set appear here in just the ten minutes we've been gone?",
  ui_story_5037_50372201_9_dialog_content = "You shouldn't be so surprised, my friend. Illumina's engineers are the best in Astra.",
  ui_story_5037_50372201_10_dialog_content = "I don't think this is what you're supposed to use engineers for...",
  ui_story_5037_50372201_11_dialog_content = "This is a really incredible set! When I walked in, I thought I'd somehow been transported to Eraveil!",
  ui_story_5037_50372201_12_dialog_content = "Please believe me, friends. Everything I do is in support of furthering this young lady's acting talents.",
  ui_story_5037_50372201_13_dialog_content = "Really?",
  ui_story_5037_50372201_14_dialog_content = "True knowledge is gained through practice. One must experience acting, to gain acting experience.",
  ui_story_5037_50372201_15_dialog_content = "I prepared both the set and script in the hopes that the two of you might experience the beauty of performance.",
  ui_story_5037_50372201_16_dialog_content = "Amazing! Idols sometimes have to act in plays as well.",
  ui_story_5037_50372201_17_dialog_content = "My acting skills would definitely improve with help from a skilled professional!",
  ui_story_5037_50372201_18_dialog_content = "In that case, let us begin at once.",
  ui_story_5037_50372201_19_dialog_content = "Here is the script I prepared.",
  ui_story_5037_50372201_20_dialog_content = "Er...",
  ui_story_5037_50372201_21_dialog_content = "Isn't this just \"Ada and the Colossus,\" but with some of the lines changed?",
  ui_story_5037_50372201_22_dialog_content = "That's right. I intentionally chose a play adapted from a fairy tale.",
  ui_story_5037_50372201_23_dialog_content = "Fairy tales are relatively simple, easy to understand, and present few challenges for novice actors.",
  ui_story_5037_50372201_24_dialog_content = "You thought of everything!",
  ui_story_5037_50372201_25_dialog_content = "But of course. I know what it's like to grow from a rookie actor into the talented thespian I am today!",
  ui_story_5037_50372201_26_dialog_content = "Shall we assign roles, PlayerName?",
  ui_story_5037_50372201_27_dialog_content = "Okay. Since I'm familiar with Colossi, I can take the role of Kaz.",
  ui_story_5037_50372201_28_dialog_content = "I'll play Ada then!",
  ui_story_5037_50372201_29_dialog_content = "She's an adorable character who's curious about everything and full of energy.",
  ui_story_5037_50372201_30_dialog_content = "I shall undertake the role of narrator and other bit parts.",
  ui_story_5037_50372201_31_dialog_content = "Since that's all decided, we might as well begin.",
  ui_story_5037_50372201_32_dialog_content = "\"In peaceful Eraveil lies, a Colossus named Kaz.\"",
  ui_story_5037_50372201_33_dialog_content = "\"It yearns for the open sky, yet remains trapped on the ground without a navigator.\"",
  ui_story_5037_50372201_34_dialog_content = "\"Yet Colossi were born for the heavens!\"",
  ui_story_5037_50372201_35_dialog_content = "\"There may be models adapted for land and sea, but the sky remains their true home!\"",
  ui_story_5037_50372201_36_dialog_content = "\"I wonder what it's like to have a navigator... How great it must be...\"",
  ui_story_5037_50372201_37_dialog_content = "\"Having a navigator must be like having a best friend...\"",
  ui_story_5037_50372201_38_dialog_content = "\"Huh? Who goes there? How come you can speak with me...?\"",
  ui_story_5037_50372201_39_dialog_content = "\"Is it a phantom? After all, no Caelestite would be wandering around this rusty old Colossus...\"",
  ui_story_5037_50372201_40_dialog_content = "\"And yet here before you does stand a Caelestite!\"",
  ui_story_5037_50372201_41_dialog_content = "\"Ada approaches Kaz, observing how the flowers that grow all over its head, and reaches out a hand to touch it.\"",
  ui_story_5037_50372201_42_dialog_content = "(Hang on, she touches its head? That's not in my script...)",
  ui_story_5037_50372201_43_dialog_content = "(What should I do? Just go on?)",
  ui_story_5037_50372201_44_option_content = "Continue the performance",
  ui_story_5037_50372201_45_dialog_content = "\"I touch...\"",
  ui_story_5037_50372201_46_dialog_content = "\"Heeeeey! You think it's alright for Caelestites to eavesdrop on someone's private thoughts, then just walk up and touch them?\"",
  ui_story_5037_50372201_47_dialog_content = "\"My gorgeous head cannot be touched by just anyone!\"",
  ui_story_5037_50372201_48_dialog_content = "\"But it truly IS gorgeous and adorned with cute little flowers!\"",
  ui_story_5037_50372201_48X1_dialog_content = "Cut!",
  ui_story_5037_50372201_49_dialog_content = "Well done, PlayerName!",
  ui_story_5037_50372201_50_dialog_content = "Huh?",
  ui_story_5037_50372201_51_option_content = "Ask a question",
  ui_story_5037_50372201_52_dialog_content = "Wait a minute, that's not in the script.",
  ui_story_5037_50372201_52X1_dialog_content = "Cut!",
  ui_story_5037_50372201_53_dialog_content = "That is correct.",
  ui_story_5037_50372201_54_dialog_content = "Mine doesn't have it either...",
  ui_story_5037_50372201_55_dialog_content = "What's up with this, Charon?",
  ui_story_5037_50372201_56_dialog_content = "Performances may need scripts, but people play the parts.",
  ui_story_5037_50372201_57_dialog_content = "Unexpected events can happen in the course of a performance. The script won't always be followed to a tee.",
  ui_story_5037_50372201_58_dialog_content = "An outstanding actor must therefore be able to adapt and improvise in the face of changing circumstances!",
  ui_story_5037_50372201_59_dialog_content = "I see!",
  ui_story_5037_50372201_60_dialog_content = "Indeed! I've seen a few plays where the lines spoken on stage were different from what was written in the script.",
  ui_story_5037_50372201_61_dialog_content = "Yet the actor's improvisation was so natural that no one could tell!",
  ui_story_5037_50372201_62_dialog_content = "Improvisation is an important skill for actors.",
  ui_story_5037_50372201_63_dialog_content = "One must first understand one's character, and then become them. Only then can you express them most naturally.",
  ui_story_5037_50372201_64_dialog_content = "I get it!",
  ui_story_5037_50372201_65_dialog_content = "I'll work hard at this, and refine my acting abilities even more!",
  ui_story_5037_50379901_1_dialog_content = "This is weird...",
  ui_story_5037_50379901_2_dialog_content = "This is way too weird!",
  ui_story_5037_50379901_3_dialog_content = "Why have Vice and Carleen been avoiding me for the last few days?",
  ui_story_5037_50379901_4_dialog_content = "Did I say something that offended them?",
  ui_story_5037_50379901_5_dialog_content = "Don't tell me it has something to do with what happened...",
  ui_story_5037_50379901_6_option_content = "On the bridge",
  ui_story_5037_50379901_7_dialog_content = "Wow, it's been a while since I wore this outfit. At least it still fits!",
  ui_story_5037_50379901_8_dialog_content = "What do you think, PlayerName? Between this and my usual Illumina uniform, which do you think looks better?",
  ui_story_5037_50379901_9_dialog_content = "Huh? Oh, I don't know.",
  ui_story_5037_50379901_10_dialog_content = "...",
  ui_story_5037_50379901_11_dialog_content = "I should've said they both looked good!",
  ui_story_5037_50379901_12_option_content = "In the lounge",
  ui_story_5037_50379901_13_dialog_content = "PlayerName?!",
  ui_story_5037_50379901_14_dialog_content = "Wh-What are you doing here?! Turn around! Don't look!",
  ui_story_5037_50379901_15_dialog_content = "I-I just came to get something to drink...",
  ui_story_5037_50379901_16_dialog_content = "What did you see just now...?",
  ui_story_5037_50379901_17_dialog_content = "Huh? Well, I saw you in your pajamas, staring happily at yourself in the mirror...",
  ui_story_5037_50379901_18_dialog_content = "You didn't see anything!!!",
  ui_story_5037_50379901_19_dialog_content = "Argh! I should've just stayed in bed that night!",
  ui_story_5037_50379901_20_dialog_content = "Still, I don't think those screw-ups were enough to make them ignore me like this...",
  ui_story_5037_50379901_21_dialog_content = "Aaaaaah! What exactly did I do wrong? It's driving me crazy!!",
  ui_story_5037_50379901_22_dialog_content = "It's almost the end of the year too! We can't go into the new year with this kind of awkwardness between us!",
  ui_story_5037_50379901_23_dialog_content = "M-Maybe I should just ask them directly?",
  ui_story_5037_50379901_24_dialog_content = "<color=#e8d9bb>Knock, knock, knock!</color>",
  ui_story_5037_50379901_25_dialog_content = "Vice? Carleen? You there...?",
  ui_story_5037_50379901_26_dialog_content = "<size=33>Huh? I-It's PlayerName! Ugh... What's he doing here now, of all times?!</size>",
  ui_story_5037_50379901_27_dialog_content = "<size=33>Hurry...!</size>",
  ui_story_5037_50379901_28_dialog_content = "Oh hey, PlayerName! You came just in time!",
  ui_story_5037_50379901_29_dialog_content = "Carleen and I were just about to go look for you. Come in!",
  ui_story_5037_50379901_30_dialog_content = "Huh? But you two have been avoiding me for days now! What's with the sudden change in attitude?",
  ui_story_5037_50379901_31_dialog_content = "You'll know once you step inside!",
  ui_story_5037_50379901_32_dialog_content = "Uh... Why are all the lights out? It's so dark in here... It's kinda creepy.",
  ui_story_5037_50379901_33_dialog_content = "You only experience the full effect if the lights are off.",
  ui_story_5037_50379901_34_dialog_content = "Th-The full effect of what?!",
  ui_story_5037_50379901_35_dialog_content = "Keep your eyes up ahead, it's starting.",
  ui_story_5037_50379901_36_dialog_content = "Huh?",
  ui_story_5037_50379901_38_dialog_content = "Wow... Time sure does fly, doesn't it?",
  ui_story_5037_50379901_39_dialog_content = "Without realizing it, another year has already passed by!",
  ui_story_5037_50379901_40_dialog_content = "But the fact that it felt so quick is a good thing.",
  ui_story_5037_50379901_41_dialog_content = "It means we had a very meaningful year.",
  ui_story_5037_50379901_42_dialog_content = "Haha, ever since we started adventuring with PlayerName, every day has felt meaningful!",
  ui_story_5037_50379901_43_dialog_content = "Is that so? Then let's reminisce, shall we?",
  ui_story_5037_50379901_44_dialog_content = "Do you still remember all of the places we traveled to this past year?",
  ui_story_5037_50379901_45_dialog_content = "Hehe, of course!",
  ui_story_5037_50379901_46_dialog_content = "Over the past year, we weathered a fierce storm before finally arriving in Northland...",
  ui_story_5037_50379901_47_dialog_content = "That was my first time seeing the aurora above the Winter Palace with my own eyes!",
  ui_story_5037_50379901_48_dialog_content = "It was also my first time trying Northland's fried meatballs in strawberry sauce. I had no idea the two went together so perfectly!",
  ui_story_5037_50379901_49_dialog_content = "PlayerName spent a lot of time by Lake Mirror during that trip. He said he saw the queen's past in the water...",
  ui_story_5037_50379901_50_dialog_content = "I wonder what kinds of visions revealed themselves to him?",
  ui_story_5037_50379901_51_dialog_content = "Then we decorated the glimmer tree and did a countdown for the new year!",
  ui_story_5037_50379901_52_dialog_content = "Ah, this really brings back memories...",
  ui_story_5037_50379901_53_dialog_content = "Of what, fried meatballs?",
  ui_story_5037_50379901_54_dialog_content = "Ehehehe...",
  ui_story_5037_50379901_55_dialog_content = "On the way back from Northland, we accidentally landed in the ruins of an ancient, underground city.",
  ui_story_5037_50379901_56_dialog_content = "In order to avoid being attacked by the city's droids, we had to don the attire of the people who once lived there.",
  ui_story_5037_50379901_57_dialog_content = "Hahaha! I still remember the look on PlayerName's face when he had to wear that dress!",
  ui_story_5037_50379901_58_dialog_content = "Afterward, we ran into a group of friends who were also trapped in the city.",
  ui_story_5037_50379901_59_dialog_content = "At first, our differences caused nothing but constant quarreling...",
  ui_story_5037_50379901_60_dialog_content = "But when everyone worked together, we finally managed to convince those two girls living in the ancient city...",
  ui_story_5037_50379901_61_dialog_content = "And so all of us made it safely out of the city before it was completely destroyed.",
  ui_story_5037_50379901_62_dialog_content = "PlayerName even received a message from the city after we got back!",
  ui_story_5037_50379901_63_dialog_content = "Perhaps we will have the chance to visit it again someday.",
  ui_story_5037_50379901_64_dialog_content = "Yeah... But that'll have to wait! We still have things to do!",
  ui_story_5037_50379901_65_dialog_content = "Pick a red flower for the lady...",
  ui_story_5037_50379901_66_dialog_content = "Petals fall like snow on a piece of jade.",
  ui_story_5037_50379901_67_dialog_content = "After arriving in Koufu-jou for a job, we met the priestess of the city.",
  ui_story_5037_50379901_68_dialog_content = "It also happened to be the Kasuga Festival at the time, so the entire city was covered in bright-pink cherry blossoms!",
  ui_story_5037_50379901_69_dialog_content = "But none of us knew that beneath Koufu-jou's beautiful appearance...",
  ui_story_5037_50379901_70_dialog_content = "An assassination plot was underway.",
  ui_story_5037_50379901_71_dialog_content = "A burning vengeance sent the peace and prosperity of the past into flames.",
  ui_story_5037_50379901_72_dialog_content = "What songs of sorrow...",
  ui_story_5037_50379901_73_dialog_content = "await the city?",
  ui_story_5037_50379901_74_dialog_content = "I wasn't there, so I have no way of answering that question...",
  ui_story_5037_50379901_75_dialog_content = "Hey, yeah! Weren't you back in Lumopolis at the time?",
  ui_story_5037_50379901_76_dialog_content = "N-Next time, Carleen! I promise we'll remember to invite you next time!",
  ui_story_5037_50379901_77_dialog_content = "Hey... Wait a second! Is that why you didn't ask me to come when you invited PlayerName to see that show in Lumopolis?!",
  ui_story_5037_50379901_78_dialog_content = "I told you, it was just to look for Gretel.",
  ui_story_5037_50379901_79_dialog_content = "We followed the clues all the way to The Manor of Truth.",
  ui_story_5037_50379901_80_dialog_content = "Ironically enough, it was full of completely irrational fools.",
  ui_story_5037_50379901_81_dialog_content = "Trust me...",
  ui_story_5037_50379901_82_dialog_content = "You should consider yourself lucky that you didn't have to sit through that performance.",
  ui_story_5037_50379901_83_dialog_content = "Hmm, that only makes me even more curious!",
  ui_story_5037_50379901_84_dialog_content = "Anyway, doesn't it feel like we forgot something?",
  ui_story_5037_50379901_85_dialog_content = "You mean that time when PlayerName went to the Rediesel Desert? You were there too, weren't you?",
  ui_story_5037_50379901_86_dialog_content = "Oh yeah, the Blazing Rally! I actually thought PlayerName had been kidnapped by Sinsa at the time.",
  ui_story_5037_50379901_87_dialog_content = "Unfortunately, I only managed to catch up at the very end of the rally.",
  ui_story_5037_50379901_88_dialog_content = "As for PlayerName, I had no idea how he ended up in the passenger seat of that car...",
  ui_story_5037_50379901_89_dialog_content = "Or what kinds of stories from Azure's past she told him, now that I think about it...",
  ui_story_5037_50379901_90_dialog_content = "I don't have any of the details.",
  ui_story_5037_50379901_91_dialog_content = "But one thing I'm sure about is that Rediesel Desert barbecue is absolutely delicious!",
  ui_story_5037_50379901_92_dialog_content = "I see... It looks like this year has been full of very robust culinary experiences for you, Vice.",
  ui_story_5037_50379901_93_dialog_content = "You think so too, Carleen?",
  ui_story_5037_50379901_94_dialog_content = "I knew I had a special talent for cooking!",
  ui_story_5037_50379901_95_dialog_content = "PlayerName, you just wait for the new dishes I'll concoct!",
  ui_story_5037_50379901_96_dialog_content = "You know, I heard that he hired a professional butler when we weren't around.",
  ui_story_5037_50379901_97_dialog_content = "During that period...",
  ui_story_5037_50379901_98_dialog_content = "PlayerName probably ate a lot of delicious food.",
  ui_story_5037_50379901_99_dialog_content = "Yeah... at first I wondered how he would survive without us at his side.",
  ui_story_5037_50379901_100_dialog_content = "But he's totally capable of feeding himself!",
  ui_story_5037_50379901_101_dialog_content = "He even hosts guests now at Cloud Gardens,",
  ui_story_5037_50379901_102_dialog_content = "which is managed so meticulously well!",
  ui_story_5037_50379901_103_dialog_content = "His management skills have indeed seen a lot of improvement.",
  ui_story_5037_50379901_104_dialog_content = "But if you ask me, he still needs people at his side very much.",
  ui_story_5037_50379901_105_dialog_content = "After all, he's the type to help his own kidnappers count their ransom money.",
  ui_story_5037_50379901_106_dialog_content = "Luckily for him, the only kidnapper he ran into was just a wondrous beast trainer.",
  ui_story_5037_50379901_107_dialog_content = "As for what exactly happened during that little escapade...",
  ui_story_5037_50379901_108_dialog_content = "We can only read about it in \"The Adventures of the Extrozoologist\" now.",
  ui_story_5037_50379901_109_dialog_content = "Actually, Fia told me all about their adventure. Many times, in fact.",
  ui_story_5037_50379901_110_dialog_content = "Huh? When?!",
  ui_story_5037_50379901_111_dialog_content = "We ran into Fia in Harbor City, remember?",
  ui_story_5037_50379901_112_dialog_content = "Oh! So that's when she told you about it!",
  ui_story_5037_50379901_113_dialog_content = "I remember now... The carnival on the Emerald was so much fun!",
  ui_story_5037_50379901_114_dialog_content = "Indeed, but who could have guessed...",
  ui_story_5037_50379901_115_dialog_content = "that behind all of the fun and festivity, Lord Elvis was plotting something so dangerous.",
  ui_story_5037_50379901_116_dialog_content = "Despite realizing the extent of his suffering afterward...",
  ui_story_5037_50379901_117_dialog_content = "As a city lord, there are certain actions one must never take.",
  ui_story_5037_50379901_118_dialog_content = "But in the end, Elvis sacrificed himself to save Harbor City from certain destruction.",
  ui_story_5037_50379901_119_dialog_content = "That day, it became very clear to me that we cannot define a person as entirely good or bad.",
  ui_story_5037_50379901_120_dialog_content = "I wonder if Jeno ever found a way to awaken Elvis from his coma?",
  ui_story_5037_50379901_121_dialog_content = "If Elvis were to awaken from his coma, I would personally escort him back to Lumopolis to stand trial.",
  ui_story_5037_50379901_122_dialog_content = "Oh, uh... Right...",
  ui_story_5037_50379901_123_dialog_content = "After coming back from Harbor City, PlayerName ran into Corax, who was in the middle of hunting down a serial killer.",
  ui_story_5037_50379901_124_dialog_content = "They followed the killer's trail all the way to a small town called Euphoria.",
  ui_story_5037_50379901_125_dialog_content = "Even though people once knew it as Wonderland, Euphoria is now completely mired by organized crime and gang violence.",
  ui_story_5037_50379901_126_dialog_content = "Every day, you hear about all kinds of murders, robberies, and infighting within the local gangs.",
  ui_story_5037_50379901_127_dialog_content = "But even in a place as dirty and dangerous as Euphoria, beautiful hydrangeas still bloom all over the place.",
  ui_story_5037_50379901_128_dialog_content = "I believe that Euphoria will become a true Wonderland again someday soon.",
  ui_story_5037_50379901_129_dialog_content = "Anyway, not long after that adventure...",
  ui_story_5037_50379901_130_dialog_content = "PlayerName and I went to check out the grand opening of the Andersen Haunted House!",
  ui_story_5037_50379901_131_dialog_content = "By total coincidence, we ended up being part of a supernatural investigation video.",
  ui_story_5037_50379901_132_dialog_content = "We just wanted to have some fun... Who would've guessed there was actual paranormal activity going on there?!",
  ui_story_5037_50379901_133_dialog_content = "The screams we heard inside the haunted house were completely real!",
  ui_story_5037_50379901_134_dialog_content = "And my favorite horror movie director... He'd been using Eclipsites in his shots all along!",
  ui_story_5037_50379901_135_dialog_content = "Thank goodness I had other business at the time...",
  ui_story_5037_50379901_136_dialog_content = "Don't tell me the all-powerful Carleen is afraid of haunted houses?",
  ui_story_5037_50379901_137_dialog_content = "Hmph. I was just worried that I would've frightened that female ghost to death... So to speak.",
  ui_story_5037_50379901_138_dialog_content = "Hahahaha! You actually think you're that scary?",
  ui_story_5037_50379901_139_dialog_content = "...",
  ui_story_5037_50379901_140_dialog_content = "<size=45>Ah—Ghost!!!</size>",
  ui_story_5037_50379901_141_dialog_content = "See? That's what I meant.",
  ui_story_5037_50379901_142_dialog_content = "Th-That was you, Carleen?! Don't tell me... Are you a ghost too?!",
  ui_story_5037_50379901_143_dialog_content = "Isn't role-playing in these days? Everyone does it.",
  ui_story_5037_50379901_144_dialog_content = "Y-Yeah, you're right...",
  ui_story_5037_50379901_145_dialog_content = "Ahem! But enough about that! Back to the real reason we're here!",
  ui_story_5037_50379901_146_dialog_content = "The year is coming to an end soon, PlayerName.",
  ui_story_5037_50379901_147_dialog_content = "We put this video together to help you remember everything we did this year!",
  ui_story_5037_50379901_148_dialog_content = "In the coming year you must remember...",
  ui_story_5037_50379901_149_dialog_content = "to take us with you on all your coming adventures!",
  ui_story_5037_50379901_151_dialog_content = "You guys...",
  ui_story_5037_50379901_152_dialog_content = "So this is why you've been acting so secretive lately? Because you were making this video?",
  ui_story_5037_50379901_153_dialog_content = "Heehee! We wanted it to be a surprise!",
  ui_story_5037_50379901_154_dialog_content = "Today is the final day of the year. How could we not make it special?",
  ui_story_5037_50379901_155_dialog_content = "You could've just told me, you know...",
  ui_story_5037_50379901_156_dialog_content = "You really didn't have to go through all the trouble of shooting a video and everything!",
  ui_story_5037_50379901_157_dialog_content = "Well, we did pay Tourdog a lot of money to find artists to create all of this art...",
  ui_story_5037_50379901_158_dialog_content = "so we had to go all out to get our money's worth!",
  ui_story_5037_50379901_159_dialog_content = "A perfectly reasonable way to ring in the new year, if you ask me.",
  ui_story_5037_50379901_160_dialog_content = "And some things are just too hard to say in person...",
  ui_story_5037_50379901_161_dialog_content = "Unless... you don't like our video surprise?",
  ui_story_5037_50379901_162_option_content = "I like it!",
  ui_story_5037_50379901_163_option_content = "I really like it!",
  ui_story_5037_50379901_164_dialog_content = "Huff, huff...",
  ui_story_5037_50379901_165_dialog_content = "I... I finally made it! I hope... I'm not late... Am I?",
  ui_story_5037_50379901_166_dialog_content = "Lola? Shouldn't you be in Northland right now?",
  ui_story_5037_50379901_167_dialog_content = "But Vice and Carleen invited me to come and celebrate the new year with you, PlayerName!",
  ui_story_5037_50379901_168_dialog_content = "R-Really? Care to explain, you two?",
  ui_story_5037_50379901_169_dialog_content = "Yeah, about that...",
  ui_story_5037_50379901_170_dialog_content = "Come on out, everyone!",
  ui_story_5037_50379901_171_dialog_content = "Hey, PlayerName! You been well?",
  ui_story_5037_50379901_172_dialog_content = "PlayerName! When did you get a white cat? It scared the living daylights out of Bently and Lompty!",
  ui_story_5037_50379901_173_dialog_content = "Don't worry, Ruby! I'll help you catch it!",
  ui_story_5037_50379901_174_dialog_content = "Don't you bully Mr. Beau!",
  ui_story_5037_50379901_175_dialog_content = "Baaaa!",
  ui_story_5037_50379901_176_dialog_content = "May, Lenore will help protect Mr. Beau.",
  ui_story_5037_50379901_177_dialog_content = "Ow... I tripped again... What's a snake doing here, anyway?",
  ui_story_5037_50379901_178_dialog_content = "Hissss!",
  ui_story_5037_50379901_179_dialog_content = "Uh, Erica? Please don't try to speak snake, you might offend Alba...",
  ui_story_5037_50379901_180_dialog_content = "Having a party without me? Such a naughty little Caelestite...",
  ui_story_5037_50379901_181_dialog_content = "Oh no!",
  ui_story_5037_50379901_182_dialog_content = "Huh?",
  ui_story_5037_50379901_183_dialog_content = "The new year countdown is about to begin! Get ready, everyone!",
  ui_story_5037_50379901_184_dialog_content = "Quit stuffing your face, Yao... We're about to begin.",
  ui_story_5037_50379901_185_dialog_content = "Munch, munch, munch... Coming!",
  ui_story_5037_50379901_186_dialog_content = "Here we go!",
  ui_story_5037_50379901_187_dialog_content = "Ten! Nine! Eight! Seven! Six!",
  ui_story_5037_50379901_188_dialog_content = "Five! Four! Three!",
  ui_story_5037_50379901_189_dialog_content = "Two! One!",
  ui_story_5037_50379901_190_dialog_content = "<color=#FFB400>Happy New Year,</color> PlayerName!",
  ui_story_5037_50379901_191_dialog_content = "You guys...",
  ui_story_5037_50379901_192_option_content = "Happy New Year!"
}
return config
